def _bench_kind(code):
    for b in BENCH_CATALOG + [BENCH_RF]:
        if b["code"] == code:
            return b["kind"]
    return "index"


def _bench_iss(url):
    last = None
    for i in range(3):
        try:
            return json.loads(http_text(url, 30))
        except Exception as e:  # noqa: BLE001
            last = e
            time.sleep(0.4 * (i + 1))
    raise last


def _bench_fetch(code, frm, to=None):
    """Дневные закрытия с Мосбиржи (ISS отдаёт страницами по 100 строк). Фонд на нескольких досках за день — строка с максимальным оборотом."""
    fund = _bench_kind(code) == "fund"
    mkt = "shares" if fund else "index"
    cols = "BOARDID,TRADEDATE,CLOSE,VALUE" if fund else "TRADEDATE,CLOSE"
    out, best, start = {}, {}, 0
    for _ in range(80):
        url = ("https://iss.moex.com/iss/history/engines/stock/markets/%s/securities/%s.json?from=%s%s&start=%d"
               "&iss.only=history,history.cursor&history.columns=%s") % (mkt, code, frm, "&till=" + to if to else "", start, cols)
        j = _bench_iss(url)
        rows = (j.get("history") or {}).get("data") or []
        for r in rows:
            if fund:
                _, d, c, v = r
                if c is None:
                    continue
                if d not in best or (v or 0) >= best[d]:
                    best[d], out[d] = (v or 0), float(c)
            elif r[1] is not None:
                out[r[0]] = float(r[1])
        cur = ((j.get("history.cursor") or {}).get("data") or [[0, 0, 100]])[0]
        start = cur[0] + len(rows)
        if not rows or start >= cur[1]:
            break
    return out


def bench_history(code, frm=None, force=False):
    """{дата: закрытие}. Кэш в SQLite под ключом bench_v1:{CODE}: дозагружается хвост (с последней даты минус 5 дней)
    не чаще раза в 6 часов, а при запросе более ранней даты — начало. При сбое сети отдаётся прежний кэш."""
    frm = max(frm or BENCH_FROM_MIN, BENCH_FROM_MIN)
    key = "bench_v1:" + code
    with _bench_locks_lock:
        lk = _bench_locks.setdefault(code, threading.Lock())
    with lk:
        c = store().get(key)
        now = time.time()
        failed = now - _bench_fail.get(code, 0) < 300
        try:
            if not c or not c.get("d"):
                if failed:
                    return {}
                c = {"t": now, "from": frm, "d": _bench_fetch(code, frm)}
                store().put(key, c)
            else:
                changed = False
                if frm < c["from"] and not failed:
                    c["d"].update(_bench_fetch(code, frm, (datetime.strptime(c["from"], "%Y-%m-%d") + timedelta(days=7)).strftime("%Y-%m-%d")))
                    c["from"] = frm
                    changed = True
                if (force or now - c["t"] > BENCH_TTL) and not failed:
                    last = max(c["d"])
                    since = (datetime.strptime(last, "%Y-%m-%d") - timedelta(days=5)).strftime("%Y-%m-%d")
                    c["d"].update(_bench_fetch(code, since))
                    c["t"] = now
                    changed = True
                if changed:
                    store().put(key, c)
        except Exception:  # noqa: BLE001
            _bench_fail[code] = now
            return (c or {}).get("d") or {}
        return c["d"]


def _bench_carry(series, days):
    """Значения ряда на каждый календарный день с переносом последнего известного вперёд (до первой даты — None)."""
    ks = sorted(series)
    out, j, cur = [], 0, None
    for d in days:
        while j < len(ks) and ks[j] <= d:
            cur = series[ks[j]]
            j += 1
        out.append(cur)
    return out


def bench_rusfar_acc(frm=None):
    """RUSFAR — это ставка в % годовых. Накопленный доход: произведение (1 + r/100/365) по календарным дням. {дата: уровень}."""
    rates = bench_history("RUSFAR", frm)
    if not rates:
        return {}
    ks = sorted(rates)
    memo = _bench_rf_memo.get("v")
    if memo and memo[0] == (len(ks), ks[0], ks[-1]):
        return memo[1]
    d0, d1 = datetime.strptime(ks[0], "%Y-%m-%d").date(), date.today()
    lvl, r, out, j, d = 1.0, rates[ks[0]], {}, 0, d0
    while d <= d1:
        ds = d.isoformat()
        while j < len(ks) and ks[j] <= ds:
            r = rates[ks[j]]
            j += 1
        lvl *= 1 + r / 100.0 / 365.0
        out[ds] = lvl
        d += timedelta(days=1)
    _bench_rf_memo["v"] = ((len(ks), ks[0], ks[-1]), out)
    return out


def bench_lqdt_yield():
    """Текущая доходность фонда ликвидности LQDT, % годовых: рост цены пая за последние 30 дней, пересчитанный на год
    ((P_t / P_t-30) ^ (365 / дни) - 1). None при ошибке. Вызывается и из других разделов (калькулятор, скринер)."""
    key = "bench_lqdt_yield_v1"
    try:
        hit = store().get(key, 3 * 3600)
        if hit and hit.get("v") is not None:
            return hit["v"]
        frm = (date.today() - timedelta(days=75)).isoformat()
        h = bench_history("LQDT", frm)
        if len(h) < 5:
            return None
        ks = sorted(h)
        last = ks[-1]
        if (date.today() - datetime.strptime(last, "%Y-%m-%d").date()).days > 10:
            return None
        target = (datetime.strptime(last, "%Y-%m-%d") - timedelta(days=30)).strftime("%Y-%m-%d")
        i = bisect.bisect_right(ks, target) - 1
        if i < 0:
            return None
        days = (datetime.strptime(last, "%Y-%m-%d") - datetime.strptime(ks[i], "%Y-%m-%d")).days
        if days < 20 or h[ks[i]] <= 0:
            return None
        v = ((h[last] / h[ks[i]]) ** (365.0 / days) - 1) * 100
        v = round(v, 2)
        store().put(key, {"v": v, "d": last})
        return v
    except Exception:  # noqa: BLE001
        return None


# ── расчёты ──

def _bn_stats(xs):
    n = len(xs)
    if n < 2:
        return 0.0, 0.0
    m = sum(xs) / n
    return m, (sum((x - m) ** 2 for x in xs) / (n - 1)) ** 0.5


def _bn_risk(idx, lv, rf, pt=None):
    """Риск-метрики по точкам-индексам idx (торговые дни). lv/rf — уровни по календарным дням. pt — доходности портфеля для беты."""
    L = [lv[i] for i in idx]
    if len(L) < 3 or any(x is None or x <= 0 for x in L):
        return None
    r = [L[k] / L[k - 1] - 1 for k in range(1, len(L))]
    ex = []
    for k in range(1, len(idx)):
        a, b = rf[idx[k - 1]], rf[idx[k]]
        ex.append(r[k - 1] - ((b / a - 1) if a and b else 0.0))
    m, sd = _bn_stats(r)
    peak, dd = L[0], 0.0
    for x in L:
        peak = max(peak, x)
        dd = min(dd, x / peak - 1)
    res = {"vol": sd * 252 ** 0.5, "maxdd": dd, "n": len(r),
           "sharpe": (_bn_stats(ex)[0] / sd * 252 ** 0.5) if sd > 1e-9 else None, "ret": r}
    return res


def _bn_cov(a, b):
    n = min(len(a), len(b))
    if n < 3:
        return None, None
    ma, mb = sum(a) / n, sum(b) / n
    cov = sum((a[i] - ma) * (b[i] - mb) for i in range(n)) / (n - 1)
    va = sum((x - ma) ** 2 for x in a) / (n - 1)
    vb = sum((x - mb) ** 2 for x in b) / (n - 1)
    beta = cov / vb if vb > 1e-14 else None
    corr = cov / (va * vb) ** 0.5 if va > 1e-14 and vb > 1e-14 else None
    return beta, corr


def _bn_window(days, period):
    today = date.today()
    last = len(days) - 1
    s = e = None
    if period == "1m":
        s = (today - timedelta(days=30)).isoformat()
    elif period == "3m":
        s = (today - timedelta(days=91)).isoformat()
    elif period == "12m":
        s = (today - timedelta(days=365)).isoformat()
    elif period == "ytd":
        s = "%d-01-01" % today.year
    elif period == "py":
        s, e = "%d-01-01" % (today.year - 1), "%d-12-31" % (today.year - 1)
    i0 = 0
    if s:
        i0 = next((i for i, d in enumerate(days) if d >= s), None)
        if i0 is None:
            return None
        i0 = max(0, i0 - 1)
    i1 = last
    if e:
        while i1 > 0 and days[i1] > e:
            i1 -= 1
    if i1 <= i0:
        return None
    return i0, i1


def _bn_thin(n, k=400):
    if n <= k:
        return list(range(n))
    step = (n - 1) / float(k - 1)
    idx = sorted({int(round(i * step)) for i in range(k)} | {n - 1})
    return idx


def bench_liquidity(cfg, acc, total):
    mon = build_monitor(cfg, acc)
    rows = [r for r in (mon.get("rows") or []) if (r.get("value_rub") or 0) > 0]
    defs = [("d1", "до 1 дня", lambda x: x <= 1), ("d5", "1–5 дней", lambda x: 1 < x <= 5), ("dm", "больше 5 дней", lambda x: x > 5)]
    bv = sum(r["value_rub"] for r in rows)
    out = []
    for k, label, fn in defs:
        sel = [r for r in rows if r.get("days_to_sell") is not None and fn(r["days_to_sell"])]
        out.append({"key": k, "label": label, "value": sum(r["value_rub"] for r in sel), "count": len(sel)})
    sel = [r for r in rows if r.get("days_to_sell") is None]
    out.append({"key": "na", "label": "нет данных", "value": sum(r["value_rub"] for r in sel), "count": len(sel)})
    for b in out:
        b["share"] = b["value"] / bv * 100 if bv else None
        b["share_total"] = b["value"] / total * 100 if total else None
    slow = sorted([r for r in rows if r.get("days_to_sell") is not None], key=lambda r: -r["days_to_sell"])[:8]
    return {"bonds_value": bv, "bonds_count": len(rows), "portfolio_value": total, "buckets": out,
            "slowest": [{"name": r.get("name"), "isin": r.get("isin"), "value_rub": r["value_rub"], "days": r["days_to_sell"],
                         "turnover": r.get("turnover_avg")} for r in slow],
            "part": MON_PART * 100, "fund_days": 0}


def bench_premium(cfg, acc):
    lq = bench_lqdt_yield()
    b = build_bonds(cfg, acc)
    m = b.get("metrics") or {}
    rows = [r for r in (b.get("rows") or []) if r.get("ytm") is not None and (r.get("value_rub") or 0) > 0 and r.get("qty")]
    ok = [r for r in rows if r["ytm"] <= YTM_HIGH]
    wv = sum(r["value_rub"] for r in ok)
    res = {"lqdt": lq, "ytm_ex": sum(r["ytm"] * r["value_rub"] for r in ok) / wv if wv else None, "ytm": m.get("ytm"), "irr": m.get("irr"), "ytm_tax": m.get("ytm_tax"), "bonds_value": m.get("value"),
           "count": m.get("count"), "high_yield_value": m.get("high_yield_value"), "below": [], "below_value": 0.0}
    if lq is not None:
        res["prem_ytm"] = m["ytm"] - lq if m.get("ytm") is not None else None
        res["prem_ytm_ex"] = res["ytm_ex"] - lq if res["ytm_ex"] is not None else None
        res["prem_irr"] = m["irr"] - lq if m.get("irr") is not None else None
        bl = sorted([r for r in rows if r["ytm"] < lq], key=lambda r: r["ytm"] - lq)
        res["below_value"] = sum(r["value_rub"] for r in bl)
        res["below"] = [{"name": r.get("name"), "isin": r.get("isin"), "ytm": r["ytm"], "diff": r["ytm"] - lq, "value_rub": r["value_rub"]} for r in bl[:12]]
        res["below_count"] = len(bl)
    return res


def bench_payload(cfg, acc, q=None):
    q = q or {}
    period = q.get("period") or "all"
    if period not in ("1m", "3m", "ytd", "12m", "py", "all"):
        period = "all"
    want = {c for c in (q.get("codes") or "").replace(";", ",").split(",") if c}
    key = ("bench", token_key(cfg), acc, period, tuple(sorted(want)))
    hit = mem_get(key, 600)
    if hit:
        return hit
    h = build_history_for(cfg, acc)
    days = h.get("days") or []
    if len(days) < 3:
        return {"error": "Нет операций для сравнения: история портфеля пуста."}
    win = _bn_window(days, period)
    if not win:
        return {"error": "За выбранный период нет данных по портфелю. Выберите период длиннее."}
    i0, i1 = win
    notes = []
    frm = (datetime.strptime(days[i0], "%Y-%m-%d") - timedelta(days=12)).strftime("%Y-%m-%d")
    cat = [b for b in BENCH_CATALOG if not want or b["code"] in want]
    jobs = [b["code"] for b in cat] + ["RUSFAR"]
    if not any(b["code"] == "LQDT" for b in cat):
        jobs.append("LQDT")      # календарь торговых дней
    jobs = list(dict.fromkeys(jobs))
    hs = dict(zip(jobs, pool_map(lambda c: bench_history(c, frm), jobs, workers=6)))
    # торговые дни Мосбиржи
    cal_src = hs.get("LQDT") or next((v for v in hs.values() if v), {})
    d_start, d_end = days[i0], days[i1]
    cal = sorted(d for d in cal_src if d_start < d <= d_end)
    didx = {d: i for i, d in enumerate(days)}
    cal_i = [didx[d] for d in cal if d in didx]
    # безрисковая ставка
    acc_rf = bench_rusfar_acc(frm)
    rf = _bench_carry(acc_rf, days) if acc_rf else [None] * len(days)
    if not acc_rf:
        notes.append("Ставка RUSFAR не загрузилась: коэффициент Шарпа посчитан без вычета безрисковой ставки.")
    elif acc_rf and min(acc_rf) > d_start:
        notes.append("Данные RUSFAR начинаются с %s: до этой даты безрисковая ставка принята равной нулю." % min(acc_rf))
    val, inv, twr = h["value"], h["invested"], h["twr"]
    # портфель
    base_t = twr[i0]
    pw = [x / base_t - 1 for x in twr[i0:i1 + 1]]
    years = (datetime.strptime(d_end, "%Y-%m-%d") - datetime.strptime(d_start, "%Y-%m-%d")).days / 365.25
    total = pw[-1]
    ann = (1 + total) ** (1 / years) - 1 if years >= 0.98 and total > -1 else None
    pidx = [i0] + cal_i
    prk = _bn_risk(pidx, twr, rf)
    if prk:
        k = max(range(len(prk["ret"])), key=lambda n: abs(prk["ret"][n]))
        if abs(prk["ret"][k]) > 0.1:
            notes.append("В истории портфеля есть резкий скачок %s%% за один торговый день (%s). Обычно это следствие неполных цен по какой-то бумаге; "
                         "из-за такого скачка волатильность, просадка и бета портфеля за период могут быть завышены." % (
                             ("%+.0f" % (prk["ret"][k] * 100)).replace("-", "−"), days[pidx[k + 1]]))
    flows = [(i, inv[i] - inv[i - 1]) for i in range(i0 + 1, i1 + 1) if abs(inv[i] - inv[i - 1]) > 0.005]
    net_flow = sum(f for _, f in flows)
    dts = [datetime.strptime(d, "%Y-%m-%d").date() for d in days]

    def xr(v_end, series_flows):
        fl = ([(dts[i0], -val[i0])] if val[i0] > 0 else []) + [(dts[i], -f) for i, f in series_flows] + [(dts[i1], v_end)]
        if years < 0.25:       # годовая ставка по коротким отрезкам вводит в заблуждение
            return None
        try:
            return xirr(fl)
        except Exception:  # noqa: BLE001
            return None

    pf = {"ret": total * 100, "ann": ann * 100 if ann is not None else None,
          "vol": prk["vol"] * 100 if prk else None, "maxdd": prk["maxdd"] * 100 if prk else None,
          "sharpe": prk["sharpe"] if prk else None, "xirr": (lambda x: x * 100 if x is not None else None)(xr(val[i1], flows)),
          "value_start": val[i0], "value_end": val[i1], "net_flow": net_flow, "gain": val[i1] - val[i0] - net_flow}
    # график: проредить
    tix = _bn_thin(i1 - i0 + 1)
    sd = [days[i0 + k] for k in tix]
    series = {"dates": sd, "portfolio": [round(pw[k] * 100, 3) for k in tix], "bench": {}}
    out = []
    for b in cat + [BENCH_RF]:
        code = b["code"]
        if code == "RUSFAR":
            if not acc_rf:
                continue
            lv = rf
        else:
            ser = hs.get(code) or {}
            if not ser:
                out.append(dict(b, available=False, reason="Мосбиржа не отдала историю"))
                continue
            lv = _bench_carry(ser, days)
        j = next((i for i in range(i0, i1 + 1) if lv[i]), None)
        if j is None or j > i1 - 5:
            out.append(dict(b, available=False, reason="нет данных за период"))
            continue
        partial = j > i0 + 7
        if partial:
            notes.append("%s: история в выбранном периоде начинается с %s." % (code, days[j]))
        j = max(j, i0)
        b0 = lv[j]
        cum = [None if lv[i] is None or i < j else lv[i] / b0 - 1 for i in range(i0, i1 + 1)]
        series["bench"][code] = [None if cum[k] is None else round(cum[k] * 100, 3) for k in tix]
        tot_b = cum[-1]
        yrs = (datetime.strptime(d_end, "%Y-%m-%d") - datetime.strptime(days[j], "%Y-%m-%d")).days / 365.25
        ann_b = (1 + tot_b) ** (1 / yrs) - 1 if yrs >= 0.98 and tot_b > -1 else None
        idx = [j] + [i for i in cal_i if i > j]
        rk = _bn_risk(idx, lv, rf)
        e = dict(b, available=True, partial=partial, start=days[j], ret=tot_b * 100, ann=ann_b * 100 if ann_b is not None else None,
                 vol=rk["vol"] * 100 if rk else None, maxdd=rk["maxdd"] * 100 if rk else None,
                 sharpe=rk["sharpe"] if (rk and code != "RUSFAR") else None, beta=None, corr=None, same=None)
        if rk and prk and code != "RUSFAR":
            pr = _bn_risk(idx, twr, rf)
            if pr:
                e["beta"], e["corr"] = _bn_cov(pr["ret"], rk["ret"])
        # «те же деньги в тот же день — в бенчмарк»
        if code != "RUSFAR":
            u = val[j] / lv[j] if val[j] > 0 else 0.0
            sf, ok = [], True
            for i in range(j + 1, i1 + 1):
                f = inv[i] - inv[i - 1]
                if abs(f) > 0.005:
                    if not lv[i]:
                        ok = False
                        break
                    u += f / lv[i]
                    sf.append((i, f))
            if ok and u >= 0:
                fin = u * lv[i1]
                nf = sum(f for _, f in sf)
                x = None
                if j == i0:
                    x = xr(fin, sf)
                e["same"] = {"final": fin, "diff": val[i1] - fin, "gain": fin - val[j] - nf, "xirr": x * 100 if x is not None else None}
        out.append(e)
    res = {"period": period, "start": d_start, "end": d_end, "years": years, "series": series, "portfolio": pf,
           "bench": out, "groups": list(dict.fromkeys([b["group"] for b in BENCH_CATALOG] + [BENCH_RF["group"]])),
           "trading_days": len(cal_i), "notes": notes}
    try:
        res["liquidity"] = bench_liquidity(cfg, acc, val[-1])
    except Exception as e:  # noqa: BLE001
        res["liquidity"] = None
        notes.append("Данные о ликвидности недоступны: %s" % str(e)[:100])
    try:
        res["premium"] = bench_premium(cfg, acc)
    except Exception as e:  # noqa: BLE001
        res["premium"] = None
        notes.append("Данные о доходности облигаций недоступны: %s" % str(e)[:100])
    res["lqdt_yield"] = bench_lqdt_yield()
    return mem_put(key, res)
# ═══════════════════════════════ калькулятор инвестиций: параметры рынка ═══════════════════════════════

CALC_TTL = 3600
CALC_LOSS_GIVEN_DEFAULT = 0.75      # потери при дефолте: 1 − ставка возмещения 25 %
_calc_mem = {}


def _calc_med(xs):
    xs = sorted(x for x in xs if x is not None)
    if not xs:
        return None
    n = len(xs)
    return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2.0


def _calc_segments(key_rate):
    """Сегменты рынка: ОФЗ, AAA, AA, A, ВДО — текущая медианная доходность и дюрация. Что не нашли — запасной вариант с флагом."""
    pd = RISK_PD_HIST
    loss = lambda *ks: sum(pd[k] for k in ks) / len(ks) / 100.0 * CALC_LOSS_GIVEN_DEFAULT
    # ожидаемые годовые потери: средняя вероятность дефолта по рейтингам сегмента × (1 − 0,25)
    meta = {"ofz": ("ОФЗ", 0.0), "aaa": ("Корпоративные AAA", loss("AAA")),
            "aa": ("Корпоративные AA", loss("AA+", "AA", "AA-")),
            "a": ("Корпоративные A", loss("A+", "A", "A-")),
            "hy": ("ВДО (BB и ниже)", loss("BB+", "BB", "BB-", "B+"))}
    fb = {"ofz": (key_rate - 0.5, 4.0), "aaa": (key_rate + 0.5, 2.5), "aa": (key_rate + 1.5, 2.5),
          "a": (key_rate + 3.0, 2.0), "hy": (key_rate + 8.0, 1.5)}
    got = {}
    try:
        sp = screener_payload()
        rows = sp.get("rows") or []
        buckets = {"aaa": "AAA", "aa": "AA", "a": "A", "hy": "BB и ниже"}
        for k, b in buckets.items():
            sel = [r for r in rows if r.get("kind") == "corp" and r.get("cur") == "RUB" and r.get("rating")
                   and rating_bucket(r["rating"]) == b and 0 < r["yield"] < 60 and (r.get("dur") or 0) > 0.1]
            if len(sel) >= 3:
                got[k] = (_calc_med([r["yield"] for r in sel]), _calc_med([r["dur"] for r in sel]), len(sel))
        sel = [r for r in rows if r.get("kind") == "ofz" and r.get("cur") == "RUB" and 0 < r["yield"] < 60
               and (r.get("dur") or 0) > 0.1 and not r.get("floating") and r.get("sub") != "ofz_floater"]
        if len(sel) >= 3:
            got["ofz"] = (_calc_med([r["yield"] for r in sel]), _calc_med([r["dur"] for r in sel]), len(sel))
    except Exception:  # noqa: BLE001
        pass
    out = {}
    for k, (name, ls) in meta.items():
        g = got.get(k)
        out[k] = {"name": name, "yield": round(g[0] if g else fb[k][0], 2), "dur": round(g[1] if g else fb[k][1], 2),
                  "loss": round(ls * 100, 3), "n": g[2] if g else 0, "estimate": g is None}
    return out


def _calc_portfolio(cfg, acc):
    if not cfg.get("token"):
        return None
    pf = {"value": None, "bonds_value": None, "irr": None, "irr_tax": None, "monthly": None, "coupons_12m": None}
    s = None
    try:
        s = build_summary(cfg, acc, "all")
        pf["value"] = round(s["portfolio"]["total"], 2)
        pf["bonds_value"] = round(s["portfolio"]["bonds"], 2)
    except Exception:  # noqa: BLE001
        pass
    try:
        if s:
            lim = (date.today() - timedelta(days=365)).strftime("%Y-%m")
            net = 0.0
            for m, v in s.get("months") or []:
                if m >= lim:
                    net += (v.get("deposits") or 0.0) - (v.get("withdrawals") or 0.0)
            pf["monthly"] = round(max(net, 0.0) / 12.0, 2)
    except Exception:  # noqa: BLE001
        pass
    try:
        m = build_bonds(cfg, acc).get("metrics") or {}
        irr = m.get("irr") if m.get("irr") is not None else m.get("ytm")
        if irr is not None:
            pf["irr"] = round(irr, 2)
        irt = m.get("irr_tax")
        if irt is not None:
            pf["irr_tax"] = round(irt, 2)
        pf["coupons_12m"] = round(m.get("coupons_12m") or 0.0, 2)
    except Exception:  # noqa: BLE001
        pass
    if all(pf[k] is None for k in ("value", "irr")):
        return None
    return pf


def calc_params(cfg, acc):
    key = (token_key(cfg), acc)
    hit = _calc_mem.get(key)
    if hit and time.time() - hit[0] < CALC_TTL:
        return hit[1]
    res = {"error": None}
    kr, path, kr_src, kr_est = None, [], "", True
    try:
        info = keyrate_forecast_info()
        kr = info.get("key_rate")
        path = [[p[0], p[1]] for p in info.get("path") or []]
        kr_src = info.get("source_name") or ""
        kr_est = info.get("source") == "none"
    except Exception:  # noqa: BLE001
        pass
    if kr is None:
        kr, kr_est = (path[0][1] if path else 16.0), True
        kr_src = kr_src or "нет данных (условное значение)"
    if not path:
        path = [[date.today().isoformat(), kr]]
    res["key_rate"] = {"current": kr, "source": kr_src, "estimate": kr_est, "path": path}
    infl = {"source": "none", "yearly": [], "estimate": True, "default": 4.0}
    try:
        i = inflation_forecast()
        if i.get("source") != "none" and i.get("yearly"):
            infl = {"source": i["source"], "as_of": i.get("as_of"), "yearly": [{"year": y["year"], "mid": y["mid"]} for y in i["yearly"]],
                    "estimate": False, "default": i["yearly"][-1]["mid"]}
    except Exception:  # noqa: BLE001
        pass
    res["inflation"] = infl
    segs = _calc_segments(kr)
    try:
        pf = _calc_portfolio(cfg, acc)
    except Exception:  # noqa: BLE001
        pf = None
    res["segments"] = segs
    ly, lest = None, True
    try:
        f = globals().get("bench_lqdt_yield")
        v = f() if f else None
        if isinstance(v, dict):
            v = v.get("yield")
        if v is not None and 0 < float(v) < 60:
            ly, lest = round(float(v), 2), False
    except Exception:  # noqa: BLE001
        pass
    if ly is None:
        ly = round(kr - 0.7, 2)
    res["lqdt"] = {"yield": ly, "estimate": lest, "spread": 0.7}
    res["deposit"] = {"spread": 1.5, "rate": round(max(kr - 1.5, 0.1), 2)}
    res["portfolio"] = pf
    res["updated"] = datetime.now().strftime("%H:%M")
    _calc_mem[key] = (time.time(), res)
    return res


# ═══════════════════ цель по пассивному доходу: сколько капитала и какое пополнение нужны ═══════════════════
# Упрощённая модель: весь капитал приносит доход по одной ставке, налог 13 % удерживается с дохода (реинвестируется остаток),
# взносы вносятся в конце каждого месяца и не индексируются. Не прогноз и не рекомендация.

GOAL_TAX = 0.13
GOAL_MAX_YEARS = 50


def goal_calc(monthly, months, yield_pct, value=0.0, infl_pct=0.0, real=False, income_now=None, tax=GOAL_TAX):
    """monthly — желаемый доход в месяц после налога, ₽; months — срок; yield_pct — доходность портфеля до налога, % годовых;
    value — текущий капитал; infl_pct — инфляция, % в год; real=True — цель задана в сегодняшних деньгах (к дате цели её нужно умножить на инфляцию).
    income_now — текущий доход в месяц (купоны и дивиденды) для оценки покрытия. Возвращает словарь с результатами."""
    monthly, value, months = max(0.0, float(monthly)), max(0.0, float(value)), int(months)
    if months < 1 or months > GOAL_MAX_YEARS * 12:
        raise ValueError("срок должен быть от 1 месяца до %d лет" % GOAL_MAX_YEARS)
    if not (0 < yield_pct < 100):
        raise ValueError("доходность должна быть больше 0 и меньше 100 %")
    y_net = yield_pct / 100.0 * (1.0 - tax)
    infl = infl_pct / 100.0 if real else 0.0
    f_inf = (1.0 + infl) ** (months / 12.0)
    goal_end = monthly * f_inf                         # желаемый доход в месяц в рублях на дату цели
    cap_today = monthly * 12.0 / y_net                # капитал, который даёт цель в сегодняшних ценах
    cap_end = goal_end * 12.0 / y_net                 # капитал на дату цели с учётом инфляции цели
    r = (1.0 + y_net) ** (1.0 / 12.0) - 1.0           # месячная ставка после налога с реинвестированием
    g = (1.0 + r) ** months
    grown = value * g
    need = max(0.0, cap_end - grown)
    contrib = need * r / (g - 1.0) if need > 0 else 0.0
    fv = lambda k, c: value * (1.0 + r) ** k + c * (((1.0 + r) ** k - 1.0) / r)
    step = 1 if months <= 60 else 3 if months <= 180 else 6
    ks = list(range(0, months + 1, step))
    if ks[-1] != months:
        ks.append(months)
    today = date.today()
    labels = []
    for k in ks:
        mm = today.month - 1 + k
        labels.append("%04d-%02d" % (today.year + mm // 12, mm % 12 + 1))
    out = {"months": months, "yield_net": round(y_net * 100.0, 3), "capital_today": cap_today, "capital_end": cap_end, "goal_end": goal_end,
           "inflation_factor": f_inf, "value": value, "value_grown": grown, "contribution": contrib, "contribution_total": contrib * months,
           "reached": need <= 0, "gap": need,
           "chart": {"labels": labels, "capital": [fv(k, contrib) for k in ks], "no_contrib": [fv(k, 0.0) for k in ks],
                     "target": [cap_today * (1.0 + infl) ** (k / 12.0) for k in ks]},
           "income_from_value": value * y_net / 12.0}
    if income_now is not None:
        out["coverage"] = {"income": income_now, "pct": (income_now / monthly * 100.0) if monthly > 0 else None}
    return out


def goal_months(q, today=None):
    """Срок в месяцах из параметров: date=ГГГГ-ММ-ДД или years (допустимы дробные)."""
    today = today or date.today()
    d = (q.get("date") or "").strip()
    if d:
        t = datetime.strptime(d, "%Y-%m-%d").date()
        if t <= today:
            raise ValueError("дата цели должна быть в будущем")
        return max(1, int(round((t - today).days / 30.4375)))
    return max(1, int(round(float(q.get("years") or 10) * 12)))


def _goal_float(q, k):
    v = (q.get(k) or "").strip().replace(",", ".")
    return float(v) if v != "" else None


def _goal_infl():
    hit = _calc_mem.get("goal_infl")
    if hit and time.time() - hit[0] < CALC_TTL:
        return hit[1]
    v = {"value": 4.0, "estimate": True, "source": "условное значение"}
    try:
        i = inflation_forecast()
        if i.get("source") != "none" and i.get("yearly"):
            v = {"value": i["yearly"][-1]["mid"], "estimate": False, "source": "прогноз Банка России"}
    except Exception:  # noqa: BLE001
        pass
    _calc_mem["goal_infl"] = (time.time(), v)
    return v


def goal_defaults(cfg, acc):
    """Что известно о портфеле: стоимость, средневзвешенная доходность облигаций, текущий доход в месяц (купоны и дивиденды за 12 мес.)."""
    d = {"value": None, "yield": None, "income_month": None, "income_src": None, "portfolio": False}
    if not cfg.get("token"):
        return d
    key = ("goal_pf", token_key(cfg), acc)
    hit = _calc_mem.get(key)
    if hit and time.time() - hit[0] < 300:
        return hit[1]
    try:
        pf = _calc_portfolio(cfg, acc)
    except Exception:  # noqa: BLE001
        pf = None
    if pf:
        d["portfolio"] = True
        d["value"] = pf.get("value")
        d["yield"] = pf.get("irr")
        if pf.get("coupons_12m"):
            d["income_month"], d["income_src"] = round(pf["coupons_12m"] / 12.0, 2), "купоны облигаций за 12 месяцев"
    try:
        end = (date.today() + timedelta(days=365)).isoformat()
        pays = [p for p in (build_bonds(cfg, acc).get("payments") or []) if p.get("kind") in ("coupon", "dividend") and p.get("date", "") <= end]
        if pays:
            d["income_month"], d["income_src"] = round(sum(p["amount"] for p in pays) / 12.0, 2), "купоны и дивиденды по графику на 12 месяцев"
    except Exception:  # noqa: BLE001
        pass
    _calc_mem[key] = (time.time(), d)
    return d


def calc_goal_get(cfg, acc, q, force=False):
    """GET /api/calc/goal?monthly=&years=|date=&yield=&value=&real=1&infl=  Ручные значения важнее данных портфеля; без токена работают только они."""
    out = {"defaults": goal_defaults(cfg, acc), "infl": _goal_infl(), "tax": GOAL_TAX, "result": None, "error": None}
    try:
        monthly = _goal_float(q, "monthly")
        if monthly is None or monthly <= 0:
            return out
        dfl = out["defaults"]
        y = _goal_float(q, "yield")
        y = dfl["yield"] if y is None else y
        if y is None:
            out["error"] = "Укажите ожидаемую доходность портфеля: данных по облигациям портфеля нет."
            return out
        v = _goal_float(q, "value")
        v = (dfl["value"] or 0.0) if v is None else v
        i = _goal_float(q, "infl")
        i = out["infl"]["value"] if i is None else i
        inc = _goal_float(q, "income")
        if inc is None:
            inc = dfl["income_month"] if dfl["income_month"] is not None else (v * y / 100.0 * (1 - GOAL_TAX) / 12.0 if v else None)
        real = (q.get("real") or "1") not in ("0", "false", "")
        out["result"] = goal_calc(monthly, goal_months(q), y, v, i, real, inc)
        out["result"].update(yield_pct=y, infl_pct=i, real=real, monthly=monthly)
    except (ValueError, TypeError) as e:
        out["error"] = str(e)
    return out


API_GET["/api/calc/goal"] = calc_goal_get
# ═══════════════════════════════ оферты и конструктор лесенки ═══════════════════════════════
# Справочные подсказки на данных Мосбиржи (bondization) и скринера; не индивидуальные инвестиционные рекомендации.
#
# Как Мосбиржа отдаёт оферты (проверено на ~540 выпусках с датой оферты, ноябрь 2026):
#  1. Список бумаг /iss/engines/stock/markets/bonds/securities[/{ISIN}].json содержит поля
#     PUTOPTIONDATE (ближайшая дата пут-оферты, право держателя; совпадает с OFFERDATE), CALLOPTIONDATE (ближайшая дата колл,
#     право эмитента), BUYBACKDATE/BUYBACKPRICE (ближайшая дата и цена выкупа, put или call — тип не различает).
#     Поля хранят только ОДНУ ближайшую дату каждого типа; пустая дата приходит как null или «0000-00-00».
#  2. bondization.json -> offers[] хранит все даты, но тип записи у него всего три значения offertype:
#     «Оферта» — пут-оферта (все будущие «Оферта» в выборке были put: совпадают с PUTOPTIONDATE или идут следующими
#     циклами, из-за этого у выпуска может быть несколько будущих put-дат);
#     «Оферта/Погашение» — досрочное погашение по усмотрению эмитента (call): дата совпадает с CALLOPTIONDATE, а запись с
#     пустой датой «0000-00-00» — просто погашение в срок, это не оферта;
#     «Оферта (состоялось)» — уже прошедшая оферта.
#     Период предъявления (offerdatestart/offerdateend) Мосбиржа публикует только перед самой офертой.
#  3. /iss/securities/{ISIN}.json (description) даёт лишь BUYBACKDATE, без типа — для классификации не нужен.
#  4. T-Invest API (Bond) отдаёт одну дату callDate без указания типа; поля даты put в API нет. Эта дата в приложении
#     считается колл, если Мосбиржа не знает такой даты как пут.
#  Среди выборки не нашлось выпуска с одновременными put и call, но код допускает обе записи (даже на одну дату).

OF_PRICE_EPS, OF_MARGIN = 0.1, 0.5      # допуск цены, п. п.; запас до медианы аналогов, п. п.
OF_CALL_WORDS = ("колл", "call", "досроч", "погашени", "усмотрен")     # право эмитента
OF_PUT_WORDS = ("put", "пут", "по требованию", "выкуп", "предъявлен")  # право держателя
OF_KIND_ORDER = {"put": 0, "call": 1, "unknown": 2}
OPT_URL = ("https://iss.moex.com/iss/engines/stock/markets/bonds/securities/%s.json?iss.meta=off&iss.only=securities"
           "&securities.columns=SECID,BOARDID,BUYBACKDATE,BUYBACKPRICE,CALLOPTIONDATE,PUTOPTIONDATE")


def moex_bond_options(isin):
    """Явные даты put/call выпуска из списка бумаг Мосбиржи: {'put': [даты], 'call': [даты], 'prices': {дата: цена}}.
    Кэш 24 ч; ошибка кэшируется на 1 ч, тогда None."""
    isin = (isin or "").strip().upper()
    if not isin or not re.match(r"^[A-Z0-9]{4,14}$", isin):
        return None
    st = store()
    key = "bopt1:" + isin
    v = st.get(key, ttl=BC_TTL)
    if v is not None:
        if v.get("ok"):
            return v
        if time.time() - v.get("ts", 0) < BC_ERR_TTL:
            return None
    try:
        rows = _bc_table(json.loads(http_text(OPT_URL % isin, 20)), "securities")
        out = {"ok": True, "ts": time.time(), "put": [], "call": [], "prices": {}}
        for r in rows:
            for fld, k in (("PUTOPTIONDATE", "put"), ("CALLOPTIONDATE", "call")):
                d = _of_date(r.get(fld))
                if d and d not in out[k]:
                    out[k].append(d)
            bd = _of_date(r.get("BUYBACKDATE"))
            if bd and r.get("BUYBACKPRICE"):
                out["prices"][bd] = r["BUYBACKPRICE"]
        out["put"].sort()
        out["call"].sort()
    except Exception:  # noqa: BLE001
        out = {"ok": False, "ts": time.time()}
    st.put(key, out)
    return out if out.get("ok") else None


OF_BROKER_NEAR = 21                                   # дней: дата брокера рядом с датой Мосбиржи — то же событие


def _of_text_kind(t, has_period):
    """Тип по тексту offertype: ('put'|'call'|'unknown', вывод сделан по слабому признаку)."""
    base = re.sub(r"\(.*?\)", "", t).strip().lower()
    if any(w in base for w in OF_CALL_WORDS):
        return "call", False
    if any(w in base for w in OF_PUT_WORDS):
        return "put", False
    if base == "оферта":                      # так Мосбиржа обозначает пут-оферту
        return "put", not has_period
    return "unknown", False


def offer_kinds(bz, opt, broker_call=None, today=None, with_done=False):
    """Все БУДУЩИЕ оферты выпуска из всех источников, без дублей по (дата, тип).
    Запись: {date, kind: put|call|unknown, source, price, period_start, period_end, status: scheduled|cancelled, inferred}.
    with_done=True добавляет и состоявшиеся оферты из bondization (status 'done'; нужно календарю за прошлые месяцы).
    Приоритет: явные поля PUTOPTIONDATE/CALLOPTIONDATE, затем тип записи bondization, затем дата брокера (присоединяется к близкой дате
    Мосбиржи, иначе 'unknown'). Одна дата может быть и put, и call — тогда две записи. Неопределимый тип — 'unknown'."""
    today = today or date.today().isoformat()
    recs = {}

    def add(d, kind, source, price=None, ps=None, pe=None, status="scheduled", inferred=False):
        if not d or d <= today:
            return
        r = recs.get((d, kind))
        if r is None:
            recs[(d, kind)] = {"date": d, "kind": kind, "source": source, "price": price, "period_start": ps,
                               "period_end": pe, "status": status, "inferred": inferred}
            return
        if source not in r["source"].split("+"):
            r["source"] += "+" + source
        for k, val in (("price", price), ("period_start", ps), ("period_end", pe)):
            if r[k] is None:
                r[k] = val
        if status == "cancelled":
            r["status"] = "cancelled"
        r["inferred"] = r["inferred"] and inferred
    prices = (opt or {}).get("prices") or {}
    for k in ("put", "call"):
        for d in (opt or {}).get(k) or []:
            add(d, k, "moex_" + k + "_field", prices.get(d))
    for o in (bz or {}).get("offers") or []:
        t = o.get("offertype") or ""
        d = _of_date(o.get("offerdate"))
        tl = t.lower()
        done = "состоял" in tl and "не состоял" not in tl
        if not d or "оферт" not in tl or (done and not with_done):
            continue
        ps, pe = _of_date(o.get("offerdatestart")), _of_date(o.get("offerdateend"))
        kind, weak = _of_text_kind(t, bool(ps and pe))
        cancelled = "отмен" in tl or "не состоял" in tl
        add(d, kind, "moex_offertype", o.get("price"), ps, pe, "cancelled" if cancelled else ("done" if done else "scheduled"), weak)
    bc = _of_date(broker_call)
    if bc and bc > today:
        # Брокер отдаёт одну дату без типа и нередко на несколько дней раньше даты Мосбиржи (например, 09.02 вместо пута 12.02):
        # близкую дату Мосбиржи считаем тем же событием, иначе честно пишем «тип не указан».
        near = [k for k in recs if abs(_of_days(bc, k[0])) <= OF_BROKER_NEAR]
        if near:
            r = recs[min(near, key=lambda k: abs(_of_days(bc, k[0])))]
            if "broker" not in r["source"].split("+"):
                r["source"] += "+broker"
        else:
            add(bc, "unknown", "broker")
    for d in {k[0] for k in recs if k[1] in ("put", "call")}:      # «неизвестный» на дату с известным типом — тот же факт
        recs.pop((d, "unknown"), None)
    return sorted(recs.values(), key=lambda x: (x["date"], OF_KIND_ORDER[x["kind"]]))


def offers_of_isin(isin, broker_call=None, today=None):
    """Будущие оферты выпуска по кэшированным данным Мосбиржи; без данных — только дата брокера."""
    bz = opt = None
    try:
        bz = moex_bondization(isin)
    except Exception:  # noqa: BLE001
        pass
    try:
        opt = moex_bond_options(isin)
    except Exception:  # noqa: BLE001
        pass
    return offer_kinds(bz or {}, opt, broker_call, today)


def offer_kind_on(offs, d):
    """Тип оферт на дату d: put | call | both | unknown (если даты нет в списке)."""
    live = [x for x in offs if x["status"] != "cancelled"]
    near = [x["date"] for x in live if abs(_of_days(d, x["date"])) <= OF_BROKER_NEAR]
    if near and d not in near:                     # дата брокера чуть сдвинута относительно Мосбиржи
        d = min(near, key=lambda x: abs(_of_days(d, x)))
    ks = {x["kind"] for x in live if x["date"] == d}
    return "both" if {"put", "call"} <= ks else (next(iter(ks)) if len(ks) == 1 else ("put" if "put" in ks else "unknown"))


def annotate_offer_kinds(rows, today=None):
    """Строкам с датой оферты/колл (r['call']) добавляет r['call_kind']: put | call | both | unknown."""
    today = today or date.today().isoformat()
    rows = [r for r in rows if r.get("isin") and r.get("call") and r["call"] > today]

    def one(r):
        try:
            return offer_kind_on(offers_of_isin(r["isin"], r["call"], today), r["call"])
        except Exception:  # noqa: BLE001
            return None
    for r, k in zip(rows, pool_map(one, rows)):
        r["call_kind"] = k


def offer_alert_text(kind, left, ds):
    """Текст тревоги «Мониторинга» по типу оферты; left — дней до даты, ds — дата дд.мм.гггг."""
    if kind == "put":
        return "Пут-оферта %s (через %d дн.): решите, предъявлять ли бумагу к выкупу" % (ds, left)
    if kind == "call":
        return "Колл-опцион %s (через %d дн.): эмитент может досрочно погасить выпуск, заявку подавать не нужно" % (ds, left)
    if kind == "both":
        return "Пут-оферта и колл-опцион %s (через %d дн.): проверьте условия в карточке выпуска" % (ds, left)
    return "Оферта %s (через %d дн.): тип не указан, проверьте условия в документах выпуска" % (ds, left)


OF_KIND_RU = {"put": "пут-оферта", "call": "колл-опцион эмитента", "unknown": "оферта (тип не указан)"}


def _of_days(a, b):
    return (datetime.strptime(b, "%Y-%m-%d") - datetime.strptime(a, "%Y-%m-%d")).days


def _of_med(xs):
    xs = sorted(xs)
    n = len(xs)
    return None if not n else (xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2.0)


def _of_date(s):
    return s if s and len(s) == 10 and not s.startswith("0000") else None


def _of_aci(bz, flows, d):
    """НКД на дату d на одну облигацию: линейно внутри купонного периода (по ближайшему будущему купону потоков)."""
    prev = [c["coupondate"] for c in bz["coupons"] if c.get("coupondate") and c["coupondate"] <= d]
    nxt = [(x[0], x[1]) for x in flows if x[0] > d and x[1] > 0]
    if not prev or not nxt:
        return 0.0
    p0, (n0, amt) = max(prev), min(nxt)
    span = _of_days(p0, n0)
    return amt * _of_days(p0, d) / span if span > 0 else 0.0


def _of_cut(bz, flows, face, od, op):
    """Потоки до оферты: покупатель по оферте получает op x остаток номинала и НКД на дату оферты."""
    head = [x for x in flows if x[0] < od]
    remain = face - sum(x[2] for x in head)
    c_od = sum(x[1] for x in flows if x[0] == od)
    acc = 0.0 if c_od else _of_aci(bz, flows, od)
    return head + [(od, c_od + acc, remain * op)], remain


def _of_peers(me, rating, floating, dur):
    """Медиана доходности и число аналогов: тот же рейтинг +/-1 ступень (если мало, +/-2), дюрация близка к dur."""
    if not dur or not rating or rating not in RATING_SCALE:
        return None, 0
    ri = RATING_SCALE.index(rating)
    uni = _bc_universe()
    for width in (1, 2):
        pool = []
        for e in uni:
            rt = e.get("_rt")
            if e["cur"] != "RUB" or not (0 < e["yield"] < 40) or not e.get("dur") or not rt or rt["v"] not in RATING_SCALE:
                continue
            if bool((e["_ci"] or {}).get("floating")) != bool(floating):
                continue
            if abs(RATING_SCALE.index(rt["v"]) - ri) > width or (me and e["_isin"] == me["_isin"]):
                continue
            if me and me.get("_iss") and e["_iss"] and e["_iss"] == me["_iss"]:
                continue
            if abs(e["dur"] - dur) > max(0.4, dur * 0.4):
                continue
            pool.append((abs(e["dur"] - dur) + 0.5 * abs(RATING_SCALE.index(rt["v"]) - ri), e["yield"]))
        if len(pool) >= 3:
            pool.sort()
            return _of_med([y for _, y in pool[:12]]), min(len(pool), 12)
    return None, 0


def _of_pct(x):
    return ("%.1f" % x).replace(".", ",")


def of_new_coupon(coupons, od, face, floating=False):
    """Купон на период после пут-оферты od по купонам Мосбиржи. Объявленным считается первый купон с датой ПОСЛЕ оферты,
    у которого указан размер (value или valueprc).
    -> {'status': 'announced'|'pending'|'formula', 'date', 'rate' (% годовых), 'value'};
    'pending' — эмитент ещё не объявил ставку; 'formula' — у флоатера размера нет: купон считается по формуле (ключевая ставка + спред)."""
    cps = sorted(((c.get("coupondate"), c.get("value"), c.get("valueprc")) for c in coupons or [] if c.get("coupondate")),
                 key=lambda x: x[0])
    nxt = next(((d, v, vp) for d, v, vp in cps if d > od), None)
    if nxt and (nxt[1] or nxt[2]):
        prev = max([d for d, _, _ in cps if d <= od] or [od])
        rate = nxt[2] if nxt[2] else nxt[1] / max(face, 1e-9) * 365.0 / max(_of_days(prev, nxt[0]), 1) * 100.0
        return {"status": "announced", "date": nxt[0], "rate": rate, "value": nxt[1]}
    return {"status": "formula" if floating else "pending", "date": nxt[0] if nxt else None, "rate": None, "value": None}


def of_outcome(hold_yield, peer_median, margin=None):
    """Сравнение доходности бумаги с новым купоном и медианы аналогов -> ('below'|'fair'|'above', разница в п. п.) или (None, None).
    below: ниже рынка больше чем на margin; above: выше рынка больше чем на margin; иначе fair (граница включается в fair)."""
    if hold_yield is None or peer_median is None:
        return None, None
    m = OF_MARGIN if margin is None else margin
    gap = hold_yield - peer_median
    return ("below" if gap < -m else "above" if gap > m else "fair"), gap


def _of_dm(d):
    return "%s.%s" % (d[8:10], d[5:7])


def of_helper(rec):
    """Помощник по пут-оферте (справочно): статус купона, итог сравнения с рынком, даты подачи заявки. rec — запись _of_one.
    Рекомендация появляется только когда эмитент объявил купон на период после оферты."""
    if rec.get("kind") != "put":
        return None
    ps, pe = rec.get("period_start"), rec.get("period_end")
    window = ("с %s по %s" % (_of_dm(ps), _of_dm(pe))) if ps and pe else None
    h = {"status": rec.get("coupon_status") or "pending", "outcome": None, "gap": None, "window": window, "title": "", "text": "",
         "numbers": "", "apply": "", "risk_notes": list(rec.get("risk_notes") or []), "kb": "offers",
         "disclaimer": "Справочная информация, не инвестиционная рекомендация."}
    if rec.get("period_status") == "closed":
        h.update(status="closed", title="Приём заявок закончился", text="Подать заявку уже нельзя: бумага останется у вас.")
        return h
    h["apply"] = ("Подать заявку через брокера %s (дата выкупа %s)." % (window, _of_dm(rec["date"]))) if window else \
        ("Период приёма заявок пока не опубликован. Дата выкупа по оферте: %s." % _of_dm(rec["date"]))
    if h["status"] == "pending":
        h.update(title="Новый купон ещё не объявлен",
                 text="Новый купон ещё не объявлен. Обычно его публикуют примерно за день до открытия приёма заявок — тогда здесь появится подсказка.")
        if window:
            h["text"] += " Ожидаемый приём заявок: %s." % window
        return h
    if h["status"] == "formula":
        h.update(title="Купон по формуле",
                 text="Купон по формуле: плавающая ставка зависит от ключевой ставки, отдельного объявления нет. Сравнение с рынком здесь "
                      "не строится; решайте по условиям выпуска и своим целям.")
        return h
    nr, hy, med = rec.get("new_rate"), rec.get("hold_yield"), rec.get("peer_median")
    h["numbers"] = "Новый купон %s %% годовых" % _of_pct(nr or 0)
    if hy is not None:
        h["numbers"] += "; доходность при текущей цене %s %%" % _of_pct(hy)
    if med is not None:
        h["numbers"] += "; медиана похожих выпусков %s %% (%d шт.)" % (_of_pct(med), rec.get("peers_n") or 0)
    code, gap = of_outcome(hy, med)
    h["outcome"], h["gap"] = code, gap
    if code == "below":
        h.update(title="Купон ниже рынка на %s п. п. — разумно предъявить к оферте" % _of_pct(-gap),
                 text="Деньги по оферте (%s %% номинала) можно вложить в бумагу с более высокой доходностью." % _of_pct(rec["offer_price"]))
    elif code == "above":
        h.update(title="Купон выше рынка — оставить выгоднее",
                 text="Доходность выше медианы похожих выпусков на %s п. п.: предъявлять нет смысла, если деньги не нужны." % _of_pct(gap))
    elif code == "fair":
        h.update(title="Купон в рынке — можно оставить", text="Доходность в пределах %s п. п. от медианы похожих выпусков." % _of_pct(OF_MARGIN))
    else:
        h.update(title="Купон объявлен", text="Сравнить с рынком не с чем: подходящих аналогов мало. Оцените ставку сами.")
    if rec.get("price") is not None and rec["price"] > rec["offer_price"] + OF_PRICE_EPS:
        h["text"] += " Но рыночная цена (%s %%) выше цены выкупа (%s %%): на бирже получите больше, чем по оферте." % (
            _of_pct(rec["price"]), _of_pct(rec["offer_price"]))
    return h


def _of_one(r, bz, offs, today, flags):
    """Оферты одной позиции (все будущие, put и call отдельными записями) -> список записей для страницы."""
    face = r.get("nominal") or 1000.0
    offs = [o for o in offs if o.get("status") != "cancelled"]
    if not offs:
        return []
    fl_ = bool(r.get("floating"))
    bz = bz or {"coupons": [], "amort": [], "offers": []}
    try:
        flows, _k, _e = bond_flows(bz, today, face, mode="maturity", floating=fl_)
    except Exception:  # noqa: BLE001
        flows = None
    cps = sorted((c["coupondate"], c.get("value"), c.get("valueprc")) for c in bz["coupons"] if c.get("coupondate"))
    rt = (r.get("rating") or {})
    rv = rt.get("v")
    me = next((e for e in _bc_universe() if e["_isin"] == r.get("isin")), None) if any(o["kind"] == "put" for o in offs) else None
    outlooks = " ".join((x.get("outlook") or "") for x in rt.get("all") or []).lower()
    risk_notes = []
    if flags.get("default"):
        risk_notes.append("по данным Мосбиржи, у выпуска был дефолт")
    elif flags.get("tech"):
        risk_notes.append("по данным Мосбиржи, у выпуска был технический дефолт")
    if "негатив" in outlooks:
        risk_notes.append("у рейтинга негативный прогноз")
    if "наблюден" in outlooks:
        risk_notes.append("рейтинг взят под наблюдение")
    price_pct = r.get("price_pct")
    out = []
    for o in offs:
        od, kind = o["date"], o["kind"]
        days = _of_days(today, od)
        ps, pe = o.get("period_start"), o.get("period_end")
        price = o.get("price") or 100.0
        status, days_left = "unknown", None
        if ps and pe:
            days_left = _of_days(today, pe)
            status = "open" if ps <= today <= pe else ("upcoming" if today < ps else "closed")
        urgent = kind == "put" and (status == "open" or (status == "upcoming" and days_left is not None and days_left <= 7) or
                                    (status == "unknown" and days <= 7))
        rec = {"isin": r.get("isin"), "uid": r.get("uid"), "name": r["name"], "logo": r.get("logo"), "color": r.get("color"),
               "qty": r.get("qty"), "value_rub": r.get("value_rub"), "rating": rv, "floating": fl_,
               "kind": kind, "source": o.get("source"), "inferred": bool(o.get("inferred")), "date": od, "days": days,
               "period_start": ps, "period_end": pe,
               "period_status": status, "period_days_left": days_left, "urgent": urgent, "offer_price": price,
               "price_known": bool(o.get("price")),
               "price": price_pct, "ytm_now": r.get("ytm"), "to_offer_rub": (r.get("qty") or 0) * face * price / 100.0,
               "risk_notes": risk_notes, "yield_to_offer": None, "coupon_known": False, "coupon_status": None, "new_rate": None,
               "hold_yield": None, "peer_median": None, "peers_n": 0, "threshold": None}
        if kind != "put":
            rec["to_offer_rub"] = None
        after_cut = None
        try:
            if flows:
                cut, remain = _of_cut(bz, flows, face, od, price / 100.0)
                aci_now = _of_aci(bz, flows, today)
                if price_pct:
                    dirty = price_pct / 100.0 * face + aci_now
                    y = cf_ytm(dirty, cut, today)
                    rec["yield_to_offer"] = y * 100 if y is not None else None
                after = [x for x in flows if x[0] > od]
                if after and kind == "put":
                    after_cut = (after, remain, _of_aci(bz, flows, od))
        except Exception:  # noqa: BLE001
            after_cut = None
        if kind != "put":
            rec["hint"] = _of_hint_other(rec)
            out.append(rec)
            continue
        nc = of_new_coupon(bz["coupons"], od, face, fl_)
        known = nc["status"] == "announced"
        rec["coupon_known"], rec["coupon_status"], rec["new_rate"] = known, nc["status"], nc["rate"]
        mac = None
        if after_cut:
            after, remain, aci_od = after_cut
            y2 = cf_ytm(remain + aci_od, after, od)
            if y2 is not None:
                mac, _m, _c = cf_risk(after, od, y2)
                if known:
                    rec["hold_yield"] = y2 * 100          # запасной вариант: если оставить бумагу, а деньги по оферте вложить по номиналу
        if known and flows and price_pct:
            try:                                           # основной: доходность к погашению при ТЕКУЩЕЙ цене с новым купоном
                yn = cf_ytm(price_pct / 100.0 * face + _of_aci(bz, flows, today), flows, today)
                if yn is not None and 0 < yn * 100 < 100:
                    rec["hold_yield"] = yn * 100
            except Exception:  # noqa: BLE001
                pass
        med, n = _of_peers(me, rv, fl_, mac)
        if med is not None:
            rec["peer_median"], rec["peers_n"], rec["threshold"] = med, n, med - OF_MARGIN
        rec["hint"] = _of_hint(rec, risk_notes)
        rec["helper"] = of_helper(rec)
        out.append(rec)
    return out


def _of_hint_other(rec):
    """Подсказка для колл-опциона эмитента и для оферты неуказанного типа."""
    y = rec.get("yield_to_offer")
    if rec["kind"] == "call":
        yt = (" Доходность к этой дате при текущей цене — %s %% годовых (выкуп по %s)." % (
            _of_pct(y), "%s %%" % _of_pct(rec["offer_price"]) if rec.get("price_known") else "номиналу")) if y is not None and y <= 100 else ""
        src = (" Дата получена от брокера, на Мосбирже условия не найдены — уточните их в проспекте выпуска."
               if rec.get("source") == "broker" else "")
        return {"code": "call", "title": "Эмитент может погасить досрочно",
                "text": "Это право эмитента, а не ваше: заявку подавать не нужно. Если ставки к тому времени упадут, эмитент "
                        "может погасить выпуск и вам придётся вкладывать деньги под меньший доход (риск реинвестирования), "
                        "поэтому ориентируйтесь на доходность к этой дате, а не к погашению.%s%s" % (yt, src)}
    if rec.get("source") == "broker":
        return {"code": "unknown", "title": "Тип оферты не указан",
                "text": "Эту дату сообщает брокер, а на Мосбирже оферта по выпуску не опубликована. Чаще всего так выглядит право "
                        "эмитента досрочно погасить выпуск (call) — тогда делать ничего не нужно. Но это может быть и put: "
                        "проверьте условия в решении о выпуске или у брокера, прежде чем полагаться на эту дату."}
    return {"code": "unknown", "title": "Тип оферты не указан",
            "text": "Мосбиржа не сообщает, кто решает: держатель (put) или эмитент (call). Не подавайте заявку, пока не проверите "
                    "условия в документах выпуска или у брокера."}


def _of_hint(rec, risk_notes):
    price, op, med = rec["price"], rec["offer_price"], rec["peer_median"]
    hy, thr = rec["hold_yield"], rec["threshold"]
    how = ("Заявку на выкуп подаёт брокер; обычно он принимает поручения на несколько дней раньше окончания периода "
           "предъявления — уточните сроки у брокера.")
    if rec["period_status"] == "closed":
        return {"code": "closed", "title": "Период предъявления закончился",
                "text": "Принимать заявки на выкуп уже поздно: бумага останется у вас, условия после оферты определяет эмитент."}
    if price is not None and price > op + OF_PRICE_EPS:
        return {"code": "sell_market", "title": "Выгоднее продать на бирже",
                "text": "Рыночная цена (%s %%) выше цены выкупа (%s %%): на бирже получите больше, чем по оферте. "
                        "Предъявлять бумаги не нужно." % (_of_pct(price), _of_pct(op))}
    if risk_notes:
        low = (" Рыночная цена (%s %%) заметно ниже цены выкупа: рынок сомневается, что эмитент выкупит бумаги." % _of_pct(price)
               if price is not None and price < op - 10 else "")
        return {"code": "put", "title": "Рассмотрите предъявление",
                "text": "Есть признаки повышенного риска эмитента: %s. Предъявление к выкупу по %s %% вернёт деньги по номиналу "
                        "до того, как условия могут измениться.%s %s" % ("; ".join(risk_notes), _of_pct(op), low, how)}
    if rec["floating"] and not rec["coupon_known"]:
        return {"code": "hold", "title": "Можно держать",
                "text": "Купон плавающий и следует за ключевой ставкой, поэтому после оферты он обычно остаётся на уровне рынка. "
                        "Предъявлять нужно, только если вам нужны деньги."}
    if rec["coupon_known"] and hy is not None:
        code = of_outcome(hy, med)[0]
        if code == "below":
            return {"code": "put", "title": "Рассмотрите предъявление",
                    "text": "Новый купон (%s %% годовых) даёт доходность %s %% против %s %% у похожих выпусков (%d шт.): ниже "
                            "рынка больше чем на 0,5 п. п. Деньги по оферте (%s %%) можно вложить в бумагу с более высокой "
                            "доходностью. %s" % (_of_pct(rec["new_rate"] or 0), _of_pct(hy), _of_pct(med), rec["peers_n"],
                                                 _of_pct(op), how)}
        if med is None:
            return {"code": "hold", "title": "Можно держать",
                    "text": "Новый купон известен (%s %% годовых), доходность после оферты %s %%. Сравнить с рынком не с чем: "
                            "подходящих аналогов мало. Оцените ставку сами." % (_of_pct(rec["new_rate"] or 0), _of_pct(hy))}
        return {"code": "hold", "title": "Можно держать",
                "text": "Новый купон (%s %% годовых) даёт доходность %s %% против %s %% у похожих выпусков (%d шт.): %s. "
                        "Предъявлять нет смысла, если деньги не нужны." % (_of_pct(rec["new_rate"] or 0), _of_pct(hy), _of_pct(med),
                                                                            rec["peers_n"], "выше рынка" if code == "above" else "на уровне рынка")}
    t = "Новый купон ещё не объявлен: дождитесь объявления ставки."
    if rec["urgent"]:
        t += " Срок предъявления близко. " + how
    return {"code": "wait", "title": "Дождитесь объявления ставки", "text": t}


def offers_payload(cfg, acc):
    rep = build_bonds(cfg, acc)
    today = date.today().isoformat()
    rows = [r for r in rep["rows"] if r.get("isin") and r.get("qty")]

    def one(r):
        try:
            bz = moex_bondization(r["isin"])
            offs = offer_kinds(bz or {}, moex_bond_options(r["isin"]), r.get("call"), today)
            if not any(o["status"] != "cancelled" for o in offs):
                return [], None
            return _of_one(r, bz, offs, today, _mon_flags(r["isin"])), None
        except Exception as e:  # noqa: BLE001
            return [], "%s: %s" % (r.get("name"), str(e)[:100])
    res = pool_map(one, rows, workers=8)
    items = sorted([x for lst, _ in res for x in lst], key=lambda x: (x["date"], OF_KIND_ORDER[x["kind"]], x["name"]))
    errs = [e for _, e in res if e]
    puts = [x for x in items if x["kind"] == "put"]
    calls = [x for x in items if x["kind"] == "call"]
    by_isin = defaultdict(set)
    for x in items:
        by_isin[x["isin"]].add(x["kind"])
    return {"account": acc, "today": today, "items": items, "count": len(items), "put_count": len(puts),
            "call_count": len(calls), "unknown_count": len(items) - len(puts) - len(calls),
            "both_count": sum(1 for v in by_isin.values() if {"put", "call"} <= v),
            "urgent_count": sum(1 for x in puts if x["urgent"]),
            "value_rub": sum(x["value_rub"] or 0 for x in items), "to_offer_rub": sum(x["to_offer_rub"] or 0 for x in puts),
            "bonds_count": len(rows), "errors": errs,
            "empty_text": "По облигациям портфеля будущих оферт нет: выпуски погашаются по графику.",
            "notes": ["PUT — право держателя предъявить бумагу эмитенту к выкупу по заранее известной цене (обычно 100 % номинала). "
                      "Если вы ничего не делаете, бумага остаётся у вас, но купон после оферты эмитент может изменить.",
                      "CALL — право эмитента досрочно погасить или выкупить выпуск. Решение принимает эмитент, заявку подавать не "
                      "нужно; для вас это риск реинвестирования: деньги вернутся, когда ставки, возможно, уже ниже. Поэтому у такой "
                      "бумаги смотрят доходность к дате колл, а не к погашению.",
                      "У одного выпуска может быть несколько дат и оба типа сразу — каждая показана отдельной строкой. Тип берётся из "
                      "данных Мосбиржи (поля дат put/call и тип записи оферты); если определить его не удалось, строка помечена "
                      "«тип не указан». Дата от брокера без подтверждения Мосбиржи тоже помечена «тип не указан». "
                      "Период предъявления Мосбиржа публикует незадолго до оферты."]}


# ═══════════════════ конструктор лесенки облигаций ═══════════════════

LD_MAX_BONDS, LD_YTM_MAX, LD_NOTCH, LD_SPREAD_MAX = 20, 40.0, 0.5, 9.0      # максимум бумаг, предел доходности (аномалии), штраф за ступень рейтинга, п. п.


def _ld_int(v, lo, hi, d):
    try:
        x = int(float(str(v).replace(",", ".")))
    except (TypeError, ValueError):
        return d
    return max(lo, min(hi, x))


def _ld_flag(v, d):
    return d if v in (None, "") else str(v).lower() in ("1", "true", "on", "yes")


def _ld_add(d, years):
    return (datetime.strptime(d, "%Y-%m-%d") + timedelta(days=round(years * 365.25))).strftime("%Y-%m-%d")


def _ld_months(bz, today):
    """Месяцы (1-12), в которые бумага платит купон (по ближайшим 14 месяцам графика)."""
    lim = _ld_add(today, 14 / 12.0)
    return sorted({int(c["coupondate"][5:7]) for c in bz["coupons"] if c.get("coupondate") and today < c["coupondate"] <= lim})


_LD_IDS = {}


def _ld_bz(isin):
    """Потоки выпуска: по ISIN, а если пусто (так бывает у ОФЗ) — по коду бумаги на Мосбирже."""
    bz = _safe_call(moex_bondization, isin)
    sid = _LD_IDS.get(isin)
    if not bz and sid and sid != isin:
        bz = _safe_call(moex_bondization, sid)
    return bz


def _ld_cands(q_min_rating, floaters, amort, min_turn, today):
    """Вселенная -> кандидаты лесенки: (запись, рейтинг, дата окончания, вид окончания, годы до окончания)."""
    mi = RATING_SCALE.index(q_min_rating)
    out = []
    for e in _bc_universe():
        ci = e.get("_ci") or {}
        if e["cur"] != "RUB" or not (0 < e["yield"] <= LD_YTM_MAX) or not e.get("mat") or e["mat"] <= today:
            continue
        if ci.get("perpetual") or ci.get("subordinated") or e.get("sub") and "суборд" in str(e.get("sub")).lower():
            continue
        if bool(ci.get("floating")) and not floaters or bool(ci.get("amort")) and not amort:
            continue
        if (e.get("turn") or 0) < min_turn:
            continue
        if e.get("spread") is not None and e["spread"] > LD_SPREAD_MAX:      # слишком щедрая доходность — признак ловушки
            continue
        _LD_IDS[e["_isin"]] = e["id"]
        rt = e.get("_rt")
        rv = rt["v"] if rt else ("AAA" if e["kind"] == "ofz" else None)
        if rv not in RATING_SCALE or RATING_SCALE.index(rv) > mi:
            continue
        out.append({"e": e, "rv": rv, "end": e["mat"], "kind": "maturity", "t": _of_days(today, e["mat"]) / 365.25, "offs": []})
    # Срок до даты оферты только для ПУТ (решает держатель). Колл (решает эмитент) и «тип не указан» срок не меняют:
    # ступень стоит на погашении, а доходность считается к худшему (см. _ld_eval).
    wo = [c for c in out if c["e"].get("offer") and today < c["e"]["offer"] < c["e"]["mat"]]
    for c, offs in zip(wo, pool_map(lambda c: _safe_call(offers_of_isin, c["e"]["_isin"], c["e"]["offer"], today) or [], wo, workers=8)):
        c["offs"] = [o for o in offs if o["status"] != "cancelled"]
        pd = min([o["date"] for o in c["offs"] if o["kind"] == "put" and today < o["date"] < c["e"]["mat"]] or [""])
        if pd:
            c["end"], c["kind"], c["t"] = pd, "offer", _of_days(today, pd) / 365.25
    return out


def _ld_eval(c, bz, today):
    """Потоки и доходности кандидата с учётом типа оферты. None, если графика выплат нет.
    flows — потоки лесенки: до пут-оферты для пута, иначе до погашения; ytm (%) — доходность для отбора и показа:
    YTP для пута, YTW для колла, для «тип не указан» — меньшая из доходности к дате оферты и к погашению."""
    e = c["e"]
    fl_ = bool((e.get("_ci") or {}).get("floating"))
    face = float(e.get("nominal") or 1000.0)
    full = (_safe_call(bond_flows, bz, today, face, "maturity", fl_) or (None,))[0] if bz else None
    if not full:
        return None
    dirty = e["price"] / 100.0 * face + _of_aci(bz, full, today)
    yk = yields_by_kind(bz, today, face, dirty, c.get("offs") or [], floating=fl_)
    if not yk:
        return None
    b = yk["basis"]
    y = {"put": yk["ytp"], "call": yk["ytw"], "unknown": min([v for v in (yk["yto"], yk["ytm"]) if v is not None], default=None)}.get(b, yk["ytm"])
    put = b == "put"
    return {"face": face, "dirty": dirty, "yk": yk, "basis": b, "y": y, "flows": yk["flows"] if put else full,
            "end": yk["end"] if put else yk["maturity"], "kind": "offer" if put else "maturity"}


def ladder_payload(cfg, q=None):
    q = q or {}
    if q.get("mode") == "portfolio":
        return ladder_portfolio(cfg, q.get("account", "all") or "all")
    today = date.today().isoformat()
    total = _fnum(q.get("sum"), 1000.0, 1e10, 500000.0)
    years = _ld_int(q.get("years"), 1, 10, 5)
    rungs_n = _ld_int(q.get("rungs"), 1, 12, years) if q.get("rungs") not in (None, "") else years
    mr = (q.get("min_rating") or "A").upper()
    mr = mr if mr in RATING_SCALE else "A"
    floaters, amort = _ld_flag(q.get("floaters"), False), _ld_flag(q.get("amort"), True)
    monthly = _ld_flag(q.get("monthly"), False)
    cap = _fnum(q.get("max_issuer"), 1.0, 100.0, max(5, round(100.0 / rungs_n / 2)))
    min_turn = _fnum(q.get("min_turnover"), 0.0, 1e12, 1000000.0)
    par = {"sum": total, "years": years, "rungs": rungs_n, "min_rating": mr, "floaters": floaters, "amort": amort,
           "max_issuer": cap, "min_turnover": min_turn, "monthly": monthly}
    warnings, notes = [], []
    cands = _ld_cands(mr, floaters, amort, min_turn, today)
    step = years / float(rungs_n)
    per_rung = total / rungs_n
    k_cap = int(-(-100.0 // (rungs_n * cap)))              # сколько бумаг на ступень нужно, чтобы доля эмитента не превысила лимит
    k = max(1, k_cap)
    if rungs_n * k > LD_MAX_BONDS:
        k = max(1, LD_MAX_BONDS // rungs_n)
        warnings.append("Лимит доли эмитента %s %% при таком числе ступеней потребовал бы больше %d бумаг; взято по %d на ступень, "
                        "доля одного эмитента может быть выше лимита." % (("%g" % cap).replace(".", ","), LD_MAX_BONDS, k))
    k = min(k, 3 if rungs_n * 3 <= LD_MAX_BONDS else k)
    if per_rung / k < 3000 and k > 1:
        k = max(1, int(per_rung // 3000))
    if per_rung < 1500:
        warnings.append("Сумма слишком мала для %d ступеней: на ступень приходится около %d ₽, а облигация стоит около 1 000 ₽ "
                        "и больше. Уменьшите число ступеней." % (rungs_n, round(per_rung)))
    win = []
    for i in range(rungs_n):
        mid = step * (i + 1)
        win.append((max(0.25, mid - step / 2.0), mid + step / 2.0 if i < rungs_n - 1 else min(mid + step / 2.0, years + 0.5), mid))
    # кандидаты по окнам; для «ровного дохода» подгружаем график купонов у лучших в каждом окне
    pools = []
    for lo, hi, mid in win:
        pl = [c for c in cands if lo <= c["t"] <= hi]
        for c in pl:
            ri = RATING_SCALE.index(c["rv"])
            c["score"] = c["e"]["yield"] - LD_NOTCH * ri - 0.3 * abs(c["t"] - mid) / max(step / 2.0, 0.25)
        pl.sort(key=lambda c: -c["score"])
        pools.append(pl)
    bzs = {}
    if monthly:
        want = [c["e"]["_isin"] for pl in pools for c in pl[:10]]
        for isin, bz in zip(want, pool_map(lambda x: _ld_bz(x), want, workers=8)):
            bzs[isin] = bz
    # колл и «тип не указан»: для отбора берём доходность к худшему, а не доходность Мосбиржи (она может быть к дате колла)
    risky = [c for pl in pools for c in pl[:12] if c["offs"] and c["kind"] != "offer"]
    need_ = sorted({c["e"]["_isin"] for c in risky if c["e"]["_isin"] not in bzs})
    for isin, bz in zip(need_, pool_map(lambda x: _ld_bz(x), need_, workers=8)):
        bzs[isin] = bz
    for c in risky:
        ev = _ld_eval(c, bzs.get(c["e"]["_isin"]), today)
        if ev and ev["y"] is not None:
            c["score"] += ev["y"] * 100.0 - c["e"]["yield"]
    for pl in pools:
        pl.sort(key=lambda c: -c["score"])
    chosen = [[] for _ in range(rungs_n)]
    used_iss, iss_share, covered = set(), defaultdict(float), set()

    def iss_key(c):
        e = c["e"]
        return e["_isin"] if e["kind"] == "ofz" or not e.get("_iss") else tuple(sorted(e["_iss"]))
    order = sorted(range(rungs_n), key=lambda i: len(pools[i]))        # сначала ступени с наименьшим выбором
    share = 100.0 / (rungs_n * k)
    for i in order:
        pl = pools[i]
        for strict in (True, False):
            while len(chosen[i]) < k:
                best = None
                for c in pl:
                    ik = iss_key(c)
                    if c in chosen[i] or any(iss_key(x) == ik for x in chosen[i]):
                        continue
                    if strict and ik in used_iss:
                        continue
                    if not strict and iss_share[ik] + share > cap + 1e-9:
                        continue
                    sc = c["score"]
                    if monthly and bzs.get(c["e"]["_isin"]):
                        c["months"] = _ld_months(bzs[c["e"]["_isin"]], today)
                        sc += 0.25 * len(set(c["months"]) - covered) + 0.0
                    if best is None or sc > best[0]:
                        best = (sc, c)
                if not best:
                    break
                c = best[1]
                chosen[i].append(c)
                used_iss.add(iss_key(c))
                iss_share[iss_key(c)] += share
                if monthly and c.get("months"):
                    covered |= set(c["months"])
            if len(chosen[i]) >= k:
                break
    # проверка дефолтных флагов у выбранных; замена на следующих в окне
    flat = [(i, c) for i in range(rungs_n) for c in chosen[i]]
    flg = dict(zip([c["e"]["_isin"] for _, c in flat], pool_map(lambda x: _mon_flags(x[1]["e"]["_isin"]), flat, workers=8)))
    for i in range(rungs_n):
        bad_ = [c for c in chosen[i] if (flg.get(c["e"]["_isin"]) or {}).get("default") or (flg.get(c["e"]["_isin"]) or {}).get("tech")]
        for c in bad_:
            chosen[i].remove(c)
            warnings.append("%s исключена: по данным Мосбиржи у выпуска был дефолт." % c["e"]["name"])
            have = {iss_key(x) for x in chosen[i]}
            for c2 in pools[i]:
                if c2 not in chosen[i] and c2 is not c and iss_key(c2) not in have and iss_key(c2) not in used_iss:
                    f2_ = _mon_flags(c2["e"]["_isin"])
                    if not (f2_.get("default") or f2_.get("tech")):
                        chosen[i].append(c2)
                        used_iss.add(iss_key(c2))
                        break
    sel = [c for i in range(rungs_n) for c in chosen[i]]
    for c in sel:
        if c["e"]["_isin"] not in bzs:
            bzs[c["e"]["_isin"]] = None
    need = [c["e"]["_isin"] for c in sel if bzs.get(c["e"]["_isin"]) is None]
    for isin, bz in zip(need, pool_map(lambda x: _ld_bz(x), need, workers=8)):
        bzs[isin] = bz
    # потоки и цена с НКД; бумаги без потоков отбрасываем, на их место ставим следующих кандидатов окна
    def prep(c):
        e = c["e"]
        bz = bzs.get(e["_isin"])
        if bz is None and e["_isin"] not in bzs:
            bz = bzs[e["_isin"]] = _ld_bz(e["_isin"])
        ev = _ld_eval(c, bz, today)
        if not ev:
            return "%s пропущена: нет данных о графике выплат." % e["name"]
        yk, y = ev["yk"], ev["y"]
        if y is not None and y * 100.0 > LD_YTM_MAX:
            return "%s пропущена: расчётная доходность выглядит аномальной." % e["name"]
        live = [o for o in c["offs"] if o["status"] != "cancelled"]
        c.update(flows=ev["flows"], face=ev["face"], dirty=ev["dirty"], ytm=(y * 100.0 if y is not None else e["yield"]),
                 end=ev["end"], kind=ev["kind"], months=_ld_months(bz, today), ybasis=ev["basis"],
                 ytm_mat=yk["ytm"] * 100.0 if yk["ytm"] is not None else None,
                 call_dates=sorted({o["date"] for o in live if o["kind"] == "call" and o["date"] < yk["maturity"]}),
                 unk_date=min([o["date"] for o in live if o["kind"] == "unknown" and o["date"] < yk["maturity"]] or [None], key=lambda x: x or "9"))
        return None
    for i in range(rungs_n):
        keep = []
        for c in chosen[i]:
            er = prep(c)
            if er:
                warnings.append(er)
            else:
                keep.append(c)
        if keep and len(keep) < k or (not keep and chosen[i]):
            have = {iss_key(x) for x in keep}
            tried = 0
            for c2 in pools[i]:
                if len(keep) >= k or tried >= 8:
                    break
                if c2 in chosen[i] or iss_key(c2) in have or iss_key(c2) in used_iss:
                    continue
                f2_ = _mon_flags(c2["e"]["_isin"])
                if f2_.get("default") or f2_.get("tech"):
                    continue
                tried += 1
                if not prep(c2):
                    keep.append(c2)
                    have.add(iss_key(c2))
                    used_iss.add(iss_key(c2))
        chosen[i] = keep
    # покупка: целые лоты, остаток — свободные деньги
    free = total
    for i in range(rungs_n):
        if not chosen[i]:
            continue
        tgt = per_rung / len(chosen[i])
        for c in chosen[i]:
            c["target"] = tgt
            c["lots"] = int(tgt // c["dirty"])
            free -= c["lots"] * c["dirty"]
    allc = [c for i in range(rungs_n) for c in chosen[i]]
    while allc:
        opts = [c for c in allc if c["dirty"] <= free + 1e-9 and c["target"] - c["lots"] * c["dirty"] + 0.5 * c["dirty"] > 0]
        if not opts:
            break
        c = max(opts, key=lambda c: c["target"] - c["lots"] * c["dirty"])
        c["lots"] += 1
        free -= c["dirty"]
    for i in range(rungs_n):
        if not chosen[i]:
            warnings.append("На ступень «около %s» не нашлось подходящих бумаг (рейтинг не ниже %s, оборот от %s ₽/день): "
                            "деньги ступени остались свободными. Смягчите рейтинг или ликвидность."
                            % (_ld_when(win[i][2]), mr, "{:,}".format(int(min_turn)).replace(",", " ")))
        elif len(chosen[i]) < k:
            warnings.append("На ступень «около %s» нашлось только %d из %d нужных бумаг." % (_ld_when(win[i][2]), len(chosen[i]), k))
    zero = [c for c in allc if c["lots"] <= 0]
    for c in zero:
        warnings.append("%s не куплена: цена лота выше выделенной суммы." % c["e"]["name"])
    allc = [c for c in allc if c["lots"] > 0]
    invested = sum(c["lots"] * c["dirty"] for c in allc)
    # денежный поток
    mon = defaultdict(lambda: [0.0, 0.0])
    agg = defaultdict(float)
    cp12 = 0.0
    lim12 = _ld_add(today, 1)
    for c in allc:
        for d, cp, pr in c["flows"]:
            mon[d[:7]][0] += cp * c["lots"]
            mon[d[:7]][1] += pr * c["lots"]
            agg[d] += (cp + pr) * c["lots"]
            if d <= lim12:
                cp12 += cp * c["lots"]
    cfm = []
    if mon:
        y0, m0 = int(today[:4]), int(today[5:7])
        last = max(mon)
        ym = "%04d-%02d" % (y0, m0)
        while ym <= last:
            v = mon.get(ym, [0.0, 0.0])
            cfm.append({"month": ym, "coupons": v[0], "principal": v[1]})
            yy, mm = int(ym[:4]), int(ym[5:7])
            ym = "%04d-%02d" % (yy + (mm == 12), mm % 12 + 1)
    yld = dur = None
    if invested > 0 and agg:
        fl_ = [(d, a, 0.0) for d, a in sorted(agg.items())]
        yv = cf_ytm(invested, fl_, today)
        if yv is not None:
            yld = yv * 100.0
            dur = cf_risk(fl_, today, yv)[0]
    rows = []
    for i in range(rungs_n):
        bl = []
        for c in chosen[i]:
            if c["lots"] <= 0:
                continue
            e = c["e"]
            bl.append({"isin": e["_isin"], "name": e["name"], "rating": c["rv"], "ytm": c["ytm"], "end_date": c["end"],
                       "end_kind": c["kind"], "yield_basis": c.get("ybasis"), "ytm_mat": c.get("ytm_mat"),
                       "call_dates": c.get("call_dates") or [], "unk_date": c.get("unk_date"), "price": e["price"], "price_dirty": c["dirty"], "lots": c["lots"],
                       "cost": c["lots"] * c["dirty"], "coupon_months": c["months"], "floating": bool((e["_ci"] or {}).get("floating")),
                       "amort": bool((e["_ci"] or {}).get("amort")), "share": c["lots"] * c["dirty"] / total * 100.0})
        rows.append({"target_date": _ld_add(today, win[i][2]), "target_years": win[i][2], "window": [_ld_add(today, win[i][0]), _ld_add(today, win[i][1])],
                     "bonds": bl, "cost": sum(b["cost"] for b in bl)})
    issuers = {iss_key(c) for c in allc}
    big = max([(iss_share_ := sum(c["lots"] * c["dirty"] for c in allc if iss_key(c) == ik) / total * 100.0) for ik in issuers] or [0])
    if big > cap + 0.5:
        warnings.append("Доля крупнейшего эмитента %s %% выше лимита %s %%: не хватило разных эмитентов." %
                        (("%.1f" % big).replace(".", ","), ("%g" % cap).replace(".", ",")))
    if any(c["kind"] == "offer" for c in allc):
        notes.append("Если у выпуска есть пут-оферта, срок считается до неё: к этой дате вы предъявляете бумагу эмитенту по цене выкупа "
                     "(обычно 100 %). Заявку подаёт брокер. Доходность таких бумаг — к пут-оферте.")
    callable_ = [c for c in allc if c.get("call_dates") or c.get("unk_date")]
    if any(c.get("call_dates") for c in callable_):
        notes.append("У части выпусков есть колл-опцион: эмитент может досрочно погасить бумагу. Ступень стоит на дате погашения, "
                     "а доходность показана к худшему (меньшая из доходности к погашению и к дате колла): если выпуск погасят раньше, "
                     "деньги вернутся раньше и их придётся реинвестировать.")
    if any(c.get("unk_date") and not c.get("call_dates") for c in callable_):
        notes.append("У части выпусков есть оферта, тип которой не указан. Консервативно ступень стоит на погашении, "
                     "доходность — меньшая из доходности к дате оферты и к погашению.")
    notes.append("Бумаги гасятся по очереди: деньги возвращаются каждый год, и их можно вложить по новой ставке. Если ставки "
                 "вырастут, вы реинвестируете дороже, если упадут, длинные ступени уже зафиксировали высокую доходность.")
    if monthly:
        notes.append("Включён ровный ежемесячный доход: при выборе бумаг учитывается, в какие месяцы они платят купоны.")
    if any(b["floating"] for r_ in rows for b in r_["bonds"]):
        notes.append("Купоны флоатеров оценены по прогнозу ключевой ставки Банка России: фактические выплаты могут отличаться.")
    if any(b["rating"] == "AAA" and next((c for c in allc if c["e"]["_isin"] == b["isin"]), {}).get("e", {}).get("kind") == "ofz"
           for r_ in rows for b in r_["bonds"]):
        notes.append("ОФЗ рейтинга не имеют; для отбора приравнены к AAA как государственный долг.")
    return {"params": par, "today": today, "rungs": rows,
            "totals": {"invested": invested, "free": total - invested, "ytm": yld, "dur": dur, "bonds": len(allc),
                       "issuers": len(issuers), "rungs_filled": sum(1 for r_ in rows if r_["bonds"]),
                       "callable_cost": sum(c["lots"] * c["dirty"] for c in callable_),
                       "callable_share": sum(c["lots"] * c["dirty"] for c in callable_) / invested * 100.0 if invested > 0 else 0.0,
                       "callable_bonds": len(callable_),
                       "coupon_12m": cp12, "monthly_avg": cp12 / 12.0, "max_issuer": big,
                       "months_with_coupon": sum(1 for m in cfm[:12] if m["coupons"] > 0)},
            "cashflow_by_month": cfm, "notes": notes, "warnings": warnings}


def _ld_when(y):
    return ("%.1f" % y).replace(".", ",") + " г."


def _safe_call(fn, *a):
    try:
        return fn(*a)
    except Exception:  # noqa: BLE001
        return None


# ───── лесенка текущего портфеля: сколько денег и когда возвращается ─────

LD_HEAVY = 1.5            # период «перегружен», если сумма больше среднего во столько раз
LD_QUARTERS_UNTIL = 1     # кварталами показываем текущий и следующий календарные годы, дальше — годами


def _ld_qkey(d):
    return "%s-Q%d" % (d[:4], (int(d[5:7]) - 1) // 3 + 1)


def _ld_pkey(d, today, gran):
    if gran == "quarter" and int(d[:4]) <= int(today[:4]) + LD_QUARTERS_UNTIL:
        return _ld_qkey(d)
    return d[:4]


def _ld_plabel(key):
    return ("%s кв. %s" % (key[6], key[:4])) if "-Q" in key else key


def _ld_pspan(today, gran, keys):
    """Все периоды от первого до последнего непрерывно: кварталы текущего и следующего года, затем годы."""
    if not keys:
        return []
    y0 = int(today[:4])
    out = []
    if gran == "quarter":
        q0 = (int(today[5:7]) - 1) // 3
        for y in range(y0, y0 + LD_QUARTERS_UNTIL + 1):
            for q in range(q0 if y == y0 else 0, 4):
                out.append("%d-Q%d" % (y, q + 1))
        last_y = max(int(k[:4]) for k in keys)
        last_q = max([k for k in keys if "-Q" in k] or [""])
        if last_y <= y0 + LD_QUARTERS_UNTIL:                       # хвост без событий не показываем
            out = [k for k in out if k <= last_q] or out[:1]
        out += [str(y) for y in range(y0 + LD_QUARTERS_UNTIL + 1, last_y + 1)]
        return out
    ys = sorted(int(k[:4]) for k in keys)
    return [str(y) for y in range(ys[0], ys[-1] + 1)]


def ld_buckets(items, today, gran="year"):
    """items: [{isin, name, ytm, events: [{date, type, amount}]}] -> периоды лесенки.
    Период: {key, label, kind, total, share, flag ('heavy'|'gap'|None), by_type, items}.
    heavy — сумма больше LD_HEAVY * среднего по периодам того же размера (между первым и последним непустым), gap — пустой период внутри."""
    grp = defaultdict(list)
    for it in items:
        for ev in it["events"]:
            if ev["date"] > today and ev["amount"] > 0:
                grp[_ld_pkey(ev["date"], today, gran)].append((it, ev))
    grand = sum(ev["amount"] for v in grp.values() for _, ev in v)
    periods = []
    for key in _ld_pspan(today, gran, list(grp)):
        rows, by, called = {}, {"redemption": 0.0, "offer": 0.0, "amort": 0.0}, 0.0
        for it, ev in grp.get(key, []):
            r = rows.setdefault((it["isin"], ev["type"]), {"isin": it["isin"], "name": it["name"], "date": ev["date"], "type": ev["type"],
                                                           "amount": 0.0, "n": 0, "ytm": it.get("ytm"), "call": None, "call_kind": None, "call_amount": 0.0})
            r["amount"] += ev["amount"]
            if ev.get("call"):                       # возможен досрочный возврат по колл (решает эмитент)
                r["call"], r["call_kind"] = ev["call"], ev.get("call_kind")
                r["call_amount"] += ev["amount"]
                called += ev["amount"]
            r["n"] += 1
            r["date"] = min(r["date"], ev["date"])
            by[ev["type"]] += ev["amount"]
        lst = sorted(rows.values(), key=lambda r: (r["date"], r["name"]))
        tot = sum(r["amount"] for r in lst)
        for r in lst:
            r["pct"] = r["amount"] / grand * 100.0 if grand else 0.0
        periods.append({"key": key, "label": _ld_plabel(key), "kind": "q" if "-Q" in key else "y", "total": tot,
                        "share": tot / grand * 100.0 if grand else 0.0, "flag": None, "by_type": by, "callable": called, "items": lst})
    first_any = next((i for i, p in enumerate(periods) if p["total"] > 0), len(periods))
    for kind in ("q", "y"):
        ps = [p for p in periods if p["kind"] == kind]
        nz = [i for i, p in enumerate(ps) if p["total"] > 0]
        if len(nz) < 1:
            continue
        span = ps[nz[0]:nz[-1] + 1]
        avg = sum(p["total"] for p in span) / float(len(span)) if span else 0.0
        for i, p in enumerate(ps):
            if p["total"] <= 0:
                if nz[0] < i < nz[-1] or (kind == "y" and first_any < periods.index(p) and i < nz[-1]):
                    p["flag"] = "gap"
            elif len(span) >= 3 and p["total"] > LD_HEAVY * avg:
                p["flag"] = "heavy"
    return periods


def ld_summary(items, today, years):
    """Плашки: средний срок (по сумме возврата), ближайшая выплата, самый тяжёлый год, пустые годы."""
    evs = [(ev["date"], ev["amount"], it["name"]) for it in items for ev in it["events"] if ev["date"] > today and ev["amount"] > 0]
    tot = sum(a for _, a, _ in evs)
    avg = sum(_of_days(today, d) / 365.25 * a for d, a, _ in evs) / tot if tot else None
    nxt = None
    if evs:
        d0 = min(d for d, _, _ in evs)
        nxt = {"date": d0, "amount": sum(a for d, a, _ in evs if d == d0), "names": sorted({n for d, _, n in evs if d == d0})}
    heavy = max([p for p in years if p["total"] > 0], key=lambda p: p["total"], default=None)
    cal = [(ev["amount"], ev.get("call_kind")) for it in items for ev in it["events"] if ev["date"] > today and ev["amount"] > 0 and ev.get("call")]
    callable_ = {"amount": sum(a for a, _ in cal), "share": sum(a for a, _ in cal) / tot * 100.0 if tot else 0.0,
                 "count": len({it["isin"] for it in items for ev in it["events"] if ev["date"] > today and ev.get("call")}),
                 "unknown_amount": sum(a for a, k in cal if k == "unknown")}
    return {"total": tot, "avg_years": avg, "next": nxt, "callable": callable_,
            "heavy": {"label": heavy["label"], "share": heavy["share"], "total": heavy["total"], "flag": heavy["flag"]} if heavy else None,
            "gaps": [p["label"] for p in years if p["flag"] == "gap"]}


def ld_events(maturity, call, nominal, qty, k, amort, today, use_offer):
    """События возврата денег по одной бумаге: амортизации + погашение, либо + оферта вместо погашения. Суммы в рублях.
    call — дата ПУТ-оферты (колл сюда не передаётся: эмитент может не воспользоваться правом, ступень стоит на погашении)."""
    cut = call if use_offer and call and today < call and (not maturity or call < maturity) else None
    end = cut or maturity
    if not end or end <= today:
        return []
    out, paid = [], 0.0
    for ad, av in sorted(amort or []):
        if not ad or not av or ad <= today or ad >= end:
            continue
        paid += av
        out.append({"date": ad, "type": "amort", "amount": av * qty * k})
    out.append({"date": end, "type": "offer" if cut else "redemption", "amount": max(nominal - paid, 0.0) * qty * k})
    return out


def ladder_portfolio(cfg, acc="all"):
    rep = build_bonds(cfg, acc)
    today = date.today().isoformat()
    rows = [r for r in rep.get("rows", []) if r.get("qty") and r.get("nominal") and (r.get("maturity") or r.get("call"))]
    value = sum(r.get("value_rub") or 0.0 for r in rep.get("rows", []))
    if not rows:
        return {"today": today, "empty": True, "value": value, "variants": {}, "has_offers": False, "has_calls": False, "undated": []}

    def bz_of(r):
        return _safe_call(moex_bondization, r["isin"]) if r.get("isin") else None
    bzs = pool_map(bz_of, rows, workers=8)
    has_offers, has_calls, undated, built = False, False, [], {"offer": [], "maturity": []}
    for r, bz in zip(rows, bzs):
        k = 1.0
        if (r.get("face_cur") or "rub") != "rub":                     # номинал в валюте -> рубли по курсу, выведенному из оценки позиции
            pp = r.get("price_pct")
            k = (r.get("value_rub") or 0.0) / (r["qty"] * pp / 100.0 * r["nominal"]) if pp else 0.0
            if k <= 0:
                continue
        am = [(a.get("amortdate"), a.get("value")) for a in (bz or {}).get("amort") or []]
        call = r.get("put_date") if r.get("put_date") and r["put_date"] > today else None       # срок до оферты — только пут
        if call and r.get("maturity") and call < r["maturity"]:
            has_offers = True
        cds = sorted(d for d in r.get("call_dates") or [] if d > today and (not r.get("maturity") or d < r["maturity"]))
        cflag = (cds[0], "call") if cds else ((r["unk_date"], "unknown") if r.get("unk_date") and r["unk_date"] > today else None)
        for v, use in (("offer", True), ("maturity", False)):
            if not use and not r.get("maturity"):
                if v == "maturity":
                    undated.append(r["name"])
                continue
            ev = ld_events(r.get("maturity"), call, r["nominal"], r["qty"], k, am, today, use)
            if ev and cflag and ev[-1]["date"] > cflag[0]:
                ev[-1]["call"], ev[-1]["call_kind"] = cflag
                has_calls = True
            if ev:
                built[v].append({"isin": r.get("isin") or r.get("ticker") or "", "name": r["name"], "ytm": r.get("ytm"), "events": ev})
    variants = {}
    for v, its in built.items():
        yr = ld_buckets(its, today, "year")
        variants[v] = {"year": yr, "quarter": ld_buckets(its, today, "quarter"), "summary": ld_summary(its, today, yr), "bonds": len(its)}
    return {"today": today, "empty": not any(built.values()), "value": value, "variants": variants, "has_offers": has_offers,
            "has_calls": has_calls, "undated": sorted(set(undated))}
# ═══════════════════════════════ эмитенты: отчётность, скоринг ═══════════════════════════════
# Источники (публичные, наружу уходят только ИНН/ISIN эмитентов, ничего о портфеле):
#   • Мосбиржа ISS: ISIN -> EMITTER_ID -> ИНН, список выпусков эмитента, флаги дефолта;
#   • ГИР БО ФНС (bo.nalog.gov.ru): бухгалтерская отчётность по РСБУ (отдельной компании, не группы).
# Суммы в отчётности — в тысячах рублей; в ответах API хранятся в млн ₽.

ISS_FNS = "https://bo.nalog.gov.ru"
ISS_FNS_TTL, ISS_FNS_NF_TTL = 7 * DAY, DAY
ISS_CODES_FR = ("2110", "2200", "2300", "2320", "2330", "2400")
ISS_CODES_BS = ("1200", "1240", "1250", "1300", "1410", "1500", "1510", "1600")
_iss_fns_lock = threading.Lock()
_iss_fns_last = [0.0]
_iss_jobs = {}
_iss_jobs_lock = threading.Lock()


def _iss_json(url, timeout=25):
    return json.loads(http_text(url, timeout=timeout))


def _iss_fns_get(path):
    """Запрос к ФНС: не чаще ~2 в секунду на всё приложение."""
    with _iss_fns_lock:
        wait = 0.5 - (time.time() - _iss_fns_last[0])
        if wait > 0:
            time.sleep(wait)
        _iss_fns_last[0] = time.time()
    return _iss_json(ISS_FNS + path, timeout=30)


def _iss_n(x, d=1):
    return "—" if x is None else ("%.*f" % (d, x)).replace(".", ",")


# ── эмитент по ISIN ──

def issuer_of(isin):
    """ISIN -> {emitter_id, inn, title, short} (кэш навсегда) или None, если определить не удалось."""
    isin = (isin or "").strip().upper()
    if not re.fullmatch(r"[A-Z0-9]{6,14}", isin):
        return None
    key = "iss_emit_v1_" + isin
    hit = store().get(key)
    if hit:
        return hit
    try:
        j = _iss_json("https://iss.moex.com/iss/securities/%s.json?iss.meta=off&iss.only=description" % isin, 20)
        d = {r[0]: r[2] for r in j["description"]["data"]}
        if not d:
            return None
        eid = d.get("EMITTER_ID")
        out = {"emitter_id": int(eid) if eid else None, "inn": None, "title": d.get("ISSUENAME") or isin, "short": None}
        if eid:
            ek = "iss_emitter_v1_%s" % eid
            em = store().get(ek)
            if not em:
                e = _iss_json("https://iss.moex.com/iss/emitters/%s.json?iss.meta=off&iss.only=emitter" % eid, 15)
                row = dict(zip(e["emitter"]["columns"], (e["emitter"]["data"] or [[]])[0]))
                em = {"inn": str(row.get("INN") or "").strip() or None, "title": row.get("TITLE"), "short": row.get("SHORT_TITLE")}
                if row:
                    store().put(ek, em)
            out.update(inn=em.get("inn"), title=em.get("title") or out["title"], short=em.get("short"))
    except Exception:  # noqa: BLE001
        return None
    store().put(key, out)
    return out


# ── отчётность РСБУ из ГИР БО ──

def _iss_pick(rep, kind, code, off):
    """Значение строки code из отчёта: off 0 = текущий год, 1 = предыдущий, 2 = позапрошлый (только баланс)."""
    blk = rep.get(kind) or {}
    pre = ("current", "previous", "beforePrevious")[off]
    v = blk.get(pre + code)
    return float(v) if isinstance(v, (int, float)) else None


def _iss_parse_bfo(lst):
    """Список отчётов ФНС -> {год: {код: значение в тыс. ₽}}; свой год приоритетнее пересчитанных значений из следующих отчётов."""
    reps = []
    for y in lst or []:
        try:
            per = int(y.get("period"))
        except (TypeError, ValueError):
            continue
        tcs = y.get("typeCorrections") or []
        cor = None
        for tc in tcs:
            c = (tc or {}).get("correction")
            if isinstance(c, dict) and (c.get("balance") or c.get("financialResult")):
                cor = c
                if (c.get("periodType") in (12, None)):
                    break
        if cor:
            reps.append((per, cor))
    years = {}
    prio = {}
    for per, c in reps:
        for off in (0, 1, 2):
            yr = per - off
            for kind, codes in (("financialResult", ISS_CODES_FR), ("balance", ISS_CODES_BS)):
                if kind == "financialResult" and off == 2:
                    continue
                for code in codes:
                    v = _iss_pick(c, kind, code, off)
                    if v is None:
                        continue
                    k = (yr, code)
                    if k not in prio or off < prio[k]:
                        prio[k] = off
                        years.setdefault(yr, {})[code] = v
    return years


def _iss_ratio(a, b):
    return a / b if a is not None and b not in (None, 0) else None


def _iss_year_row(y, v, prev):
    g = v.get
    rev, np_, ebt, int_ = g("2110"), g("2400"), g("2300"), g("2330")
    int_ = abs(int_) if int_ is not None else None
    if ebt is not None:
        ebit = ebt + (int_ or 0)
    else:
        ebit = g("2200")
    parts = [g("1410"), g("1510")]
    debt = None if all(p is None for p in parts) else sum(p or 0 for p in parts)
    cp = [g("1250"), g("1240")]
    cash = None if all(p is None for p in cp) else sum(p or 0 for p in cp)
    nd = None if debt is None else debt - (cash or 0)
    eq, assets = g("1300"), g("1600")
    r = lambda x: None if x is None else round(x / 1000.0, 1)      # noqa: E731  тыс. ₽ -> млн ₽
    row = {"y": y, "rev": r(rev), "ebit": r(ebit), "interest": r(int_), "net": r(np_), "debt": r(debt), "cash": r(cash),
           "net_debt": r(nd), "equity": r(eq), "assets": r(assets),
           "cover": None, "nd_ebit": None, "cur_liq": _iss_ratio(g("1200"), g("1500")),
           "eq_ratio": _iss_ratio(eq, assets), "margin": _iss_ratio(ebit, rev), "growth": None, "debt_eq": None}
    if ebit is not None and int_ and int_ > 0:
        row["cover"] = ebit / int_
    if nd is not None and ebit is not None and ebit > 0:
        row["nd_ebit"] = nd / ebit
    if debt is not None and eq is not None and eq > 0:
        row["debt_eq"] = debt / eq
    if prev and prev.get("2110") and rev is not None:
        row["growth"] = rev / prev["2110"] - 1
    for k in ("cover", "nd_ebit", "cur_liq", "eq_ratio", "margin", "growth", "debt_eq"):
        if row[k] is not None:
            row[k] = round(row[k], 4)
    # годовая выручка 0/пустая и нет баланса — строка бесполезна
    row["has"] = any(row[k] is not None for k in ("rev", "assets", "equity"))
    return row


def issuer_fin(inn, name=""):
    """Отчётность эмитента по ИНН: {status, years:[...], org_id, name, note}. Кэш 7 суток (ненайденные — 1 сутки)."""
    inn = re.sub(r"\D", "", inn or "")
    if len(inn) not in (10, 12):
        return {"status": "noinn", "years": [], "note": "ИНН эмитента неизвестен (возможно, иностранный эмитент или государство)."}
    key = "iss_fin_v1_" + inn
    hit = store().get(key)
    if hit and time.time() - hit.get("ts", 0) < (ISS_FNS_TTL if hit.get("status") == "ok" else ISS_FNS_NF_TTL):
        return hit
    res = {"status": "nf", "years": [], "inn": inn, "ts": time.time(), "org_id": None, "name": name or ""}
    s = _iss_fns_get("/advanced-search/organizations/search?query=%s&page=0" % inn)
    org = None
    for it in s.get("content") or []:
        if re.sub(r"<[^>]+>", "", str(it.get("inn") or "")).strip() == inn:
            org = it
            if it.get("bfo"):
                break
    nm = (org or {}).get("shortName") or name or ""
    res["name"] = nm
    if not org:
        res["note"] = _iss_nodata_note(nm or name, "Организация не найдена в ГИР БО ФНС (с 2022 года часть компаний вправе не раскрывать отчётность).")
        store().put(key, res)
        return res
    res["org_id"] = org.get("id")
    if not org.get("bfo"):
        res["status"] = "nobfo"
        res["note"] = _iss_nodata_note(nm, "В ГИР БО нет бухгалтерской отчётности этой организации.")
        store().put(key, res)
        return res
    lst = _iss_fns_get("/nbo/organizations/%s/bfo/" % org["id"])
    ys = _iss_parse_bfo(lst if isinstance(lst, list) else [])
    rows = []
    for y in sorted(ys):
        row = _iss_year_row(y, ys[y], ys.get(y - 1))
        if row["has"]:
            rows.append(row)
    res["years"] = rows[-5:]
    if rows:
        res["status"] = "ok"
    else:
        res["status"] = "nobfo"
        res["note"] = _iss_nodata_note(nm, "Отчётность в ГИР БО пустая или в нестандартной форме.")
    store().put(key, res)
    return res


def _iss_nodata_note(name, base):
    if re.search(r"банк|страхов|\bНКО\b|кредитн\w+ организац", name or "", re.I):
        return "Нет данных по РСБУ: банки и страховые компании сдают отчётность в Банк России (формы 0409806 и др.), в ГИР БО её нет."
    return base + " Возможные причины: новая компания, отчётность не публикуется, нестандартная форма."


# ── скоринг ──
# Шесть показателей последнего года, каждый даёт баллы от 0 до максимума линейно между «плохо» и «хорошо»:
#   покрытие процентов EBIT/проценты   25 б.:  ≤ 1,5 — 0,  ≥ 4 — полный балл
#   чистый долг / EBIT                 25 б.:  ≥ 4 — 0,    ≤ 2 — полный (нет чистого долга — полный; EBIT ≤ 0 при долге — 0)
#   доля капитала в активах            15 б.:  ≤ 5 % — 0,  ≥ 30 % — полный
#   текущая ликвидность                10 б.:  ≤ 0,8 — 0,  ≥ 1,5 — полный
#   рентабельность по EBIT             10 б.:  ≤ 0 — 0,    ≥ 12 % — полный
#   рост выручки                       15 б.:  ≤ −15 % — 0, ≥ +5 % — полный
# Для лизинга и прочих финансовых компаний долг — это «сырьё» бизнеса, поэтому вместо чистого долга/EBIT
# берётся долг/капитал (≥ 8 — 0, ≤ 3 — полный), капитал/активы: 5 % — 0, 15 % — полный, ликвидность не считается.
# Итог = набранные баллы / максимум по доступным показателям × 100, затем штрафы:
#   убыток по итогам года −8 (два года подряд ещё −7), отрицательный капитал −15, отчётность старше двух лет −10.
# Метки: ≥ 70 устойчивое, 50–69 среднее, 30–49 слабое, < 30 тревожное.
ISS_FIN_RE = re.compile(r"лизинг|факторинг|финанс|микрофин|МФК|МКК|кредитн|ипотечн|коллектор|ломбард", re.I)
ISS_LABELS = [(70, "strong", "устойчивое"), (50, "mid", "среднее"), (30, "weak", "слабое"), (-1, "alarm", "тревожное")]


def _iss_t(x, bad, good):
    if x is None:
        return None
    return max(0.0, min(1.0, (x - bad) / float(good - bad)))


def _iss_label(sc):
    for lim, k, t in ISS_LABELS:
        if sc >= lim:
            return k, t
    return "alarm", "тревожное"


def _iss_grade(t):
    return "good" if t >= 0.75 else "mid" if t >= 0.35 else "bad"


def iss_score_fin(fin, is_fin=False):
    """Скоринг по готовой отчётности (issuer_fin). Возвращает {ok, score, key, label, year, parts, penalties, note}."""
    yrs = (fin or {}).get("years") or []
    if not yrs:
        return {"ok": False, "reason": (fin or {}).get("note") or "Нет отчётности."}
    c = yrs[-1]
    prev = yrs[-2] if len(yrs) > 1 and yrs[-2]["y"] == c["y"] - 1 else None
    parts = []

    def add(pid, name, w, t, value, text):
        if t is not None:
            parts.append({"id": pid, "name": name, "max": w, "pts": round(w * t, 1), "grade": _iss_grade(t), "value": value, "text": text})

    ebit, intr = c.get("ebit"), c.get("interest")
    if intr is not None and intr > 0:
        if ebit is not None and ebit > 0 and c.get("cover") is not None:
            add("cover", "Покрытие процентов", 25, _iss_t(c["cover"], 1.5, 4.0), c["cover"], "прибыль покрывает проценты в %s раза" % _iss_n(c["cover"], 1))
        elif ebit is not None:
            add("cover", "Покрытие процентов", 25, 0.0, None, "операционной прибыли нет, проценты платятся из других источников")
    elif ebit is not None and ebit > 0 and c.get("debt") is not None and c["debt"] <= 0.02 * (c.get("assets") or 1e18):
        add("cover", "Покрытие процентов", 25, 1.0, None, "заёмных средств практически нет")
    nd, ebit_ok = c.get("net_debt"), ebit is not None and ebit > 0
    if is_fin:
        if c.get("debt") is not None and c.get("equity") is not None:
            if c["equity"] <= 0:
                add("lev", "Долг / капитал", 25, 0.0, None, "капитал отрицательный")
            elif c.get("debt_eq") is not None:
                add("lev", "Долг / капитал", 25, _iss_t(c["debt_eq"], 8, 3), c["debt_eq"], "долг в %s раза больше капитала" % _iss_n(c["debt_eq"], 1))
    elif nd is not None:
        if nd <= 0:
            add("lev", "Чистый долг / EBIT", 25, 1.0, None, "денег больше, чем долга")
        elif not ebit_ok:
            add("lev", "Чистый долг / EBIT", 25, 0.0, None, "есть чистый долг, а операционной прибыли нет")
        else:
            add("lev", "Чистый долг / EBIT", 25, _iss_t(c["nd_ebit"], 4, 2), c["nd_ebit"], "чистый долг = %s годовой прибыли" % _iss_n(c["nd_ebit"], 1))
    if c.get("eq_ratio") is not None:
        hi = 0.15 if is_fin else 0.30
        add("eq", "Доля капитала", 15, _iss_t(c["eq_ratio"], 0.05, hi), c["eq_ratio"], "капитал — %s %% активов" % _iss_n(c["eq_ratio"] * 100, 0))
    if c.get("cur_liq") is not None and not is_fin:
        add("liq", "Текущая ликвидность", 10, _iss_t(c["cur_liq"], 0.8, 1.5), c["cur_liq"], "оборотные активы = %s× краткосрочных обязательств" % _iss_n(c["cur_liq"], 2))
    holding = c.get("margin") is not None and c["margin"] > 1.0       # EBIT больше выручки: доход в основном от дивидендов и финансовых вложений
    if c.get("margin") is not None and not holding:
        add("margin", "Рентабельность по EBIT", 10, _iss_t(c["margin"], 0.0, 0.12), c["margin"], "EBIT — %s %% выручки" % _iss_n(c["margin"] * 100, 1))
    if c.get("growth") is not None:
        add("growth", "Динамика выручки", 15, _iss_t(c["growth"], -0.15, 0.05), c["growth"], "выручка %s на %s %%" % ("выросла" if c["growth"] >= 0 else "упала", _iss_n(abs(c["growth"]) * 100, 0)))
    mx = sum(p["max"] for p in parts)
    if mx < 40:
        return {"ok": False, "reason": "Слишком мало показателей для оценки (в отчётности не хватает строк)."}
    base = sum(p["pts"] for p in parts) / mx * 100
    pen = []
    if c.get("net") is not None and c["net"] < 0:
        pen.append({"name": "Убыток по итогам года", "pts": -8})
        if prev and prev.get("net") is not None and prev["net"] < 0:
            pen.append({"name": "Убыток второй год подряд", "pts": -7})
    if c.get("equity") is not None and c["equity"] < 0:
        pen.append({"name": "Отрицательный капитал", "pts": -15})
    if c["y"] < date.today().year - 2:
        pen.append({"name": "Отчётность старше двух лет (%d)" % c["y"], "pts": -10})
    sc = max(0, min(100, int(round(base + sum(p["pts"] for p in pen)))))
    k, t = _iss_label(sc)
    return {"ok": True, "score": sc, "key": k, "label": t, "year": c["y"], "base": round(base, 1), "parts": parts, "penalties": pen,
            "n_years": len(yrs), "fin_mode": bool(is_fin),
            "holding": holding,
            "note": ("Есть отчётность только за один год: динамику оценить нельзя. " if len(yrs) == 1 else "")
            + ("Прибыль до налогов больше выручки: компания, судя по всему, холдинговая (доход — дивиденды и проценты от дочерних структур). "
               "Её отдельная отчётность плохо отражает группу, оценка ориентировочная." if holding else "")}


def _iss_is_fin(title, sector=None):
    return bool(ISS_FIN_RE.search(title or "")) or sector == "financial"


def issuer_score(isin):
    """Публичная функция для других модулей: скоринг эмитента облигации по ISIN.
    Возвращает {ok, score 0–100, key (strong/mid/weak/alarm), label, year, parts, penalties, issuer, inn, basis, rsbu, ifrs} или {ok: False, reason}.
    basis = "ifrs" (консолидированная отчётность группы по smart-lab, если нашлась) или "rsbu" (отдельная компания, ГИР БО);
    s["rsbu"] — скоринг РСБУ, s["ifrs"] — скоринг МСФО (или None)."""
    try:
        em = issuer_of(isin)
        if not em or not em.get("inn"):
            return {"ok": False, "reason": "Не удалось определить эмитента (нет ИНН)."}
        fin = issuer_fin(em["inn"], em.get("title") or "")
        ci = tcat_info(isin) or {}
        rs = iss_score_fin(fin, _iss_is_fin(em.get("title"), ci.get("sector")))
        try:
            ib = ifrs_bundle(isin, em)
        except Exception:  # noqa: BLE001
            ib = None
        if ib and ib["score"].get("ok"):
            s = dict(ib["score"])
            s["ifrs"] = dict(ib["score"], ticker=ib["ticker"], how=ib["how"])
        else:
            s = dict(rs)
            s["ifrs"] = None
        s["basis"] = "ifrs" if s["ifrs"] else "rsbu"
        s["rsbu"] = rs
        s["issuer"], s["inn"] = em.get("short") or em.get("title"), em["inn"]
        return s
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "reason": "Ошибка получения отчётности: %s" % str(e)[:100]}


# ── сопоставление с рынком ──

_ISS_SPREAD_PTS = [(0, 92), (1, 80), (2.5, 65), (4.5, 45), (7, 28), (12, 10), (25, 0)]
_ISS_RATING_PTS = [(0, 92), (3, 82), (5, 72), (8, 55), (11, 40), (14, 25), (16, 12), (19, 0)]


def _iss_interp(x, pts):
    if x <= pts[0][0]:
        return float(pts[0][1])
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if x <= x1:
            return y0 + (y1 - y0) * (x - x0) / float(x1 - x0)
    return float(pts[-1][1])


def iss_market(score, spread, rating):
    """Сравнивает «баллы по отчётности» с тем, что закладывает рынок (спред к КБД) и рейтинговые агентства."""
    out = {"spread": spread, "rating": rating, "market_score": None, "rating_score": None, "key": None, "text": ""}
    if spread is not None:
        out["market_score"] = round(_iss_interp(max(0.0, spread), _ISS_SPREAD_PTS))
    if rating in RATING_SCALE:
        out["rating_score"] = round(_iss_interp(RATING_SCALE.index(rating), _ISS_RATING_PTS))
    if score is None:
        out["text"] = "Для сопоставления нужна отчётность эмитента."
        return out
    refs = [x for x in (out["market_score"], out["rating_score"]) if x is not None]
    if not refs:
        out["text"] = "Нет ни спреда к КБД, ни рейтинга — сопоставить с рынком нечего."
        return out
    ref = out["market_score"] if out["market_score"] is not None else out["rating_score"]
    diff = score - ref
    src = "спред к КБД %s п.п." % _iss_n(spread, 1) if out["market_score"] is not None else "рейтинг %s" % rating
    if diff >= 20:
        out["key"] = "mkt_higher"
        out["text"] = ("Рынок оценивает риск выше, чем следует из отчётности (%s). Либо облигации недооценены, либо есть риски, которых "
                       "не видно в РСБУ: долги группы, зависимость от одного заказчика, корпоративные события." % src)
    elif diff <= -20:
        out["key"] = "mkt_lower"
        out["text"] = ("Рынок оценивает риск ниже, чем следует из отчётности (%s). Возможно, закладывается поддержка владельца или государства, "
                       "либо слабые места отчётности пока не замечены. Стоит присмотреться внимательнее." % src)
    else:
        out["key"] = "match"
        out["text"] = "Оценка рынка (%s) в целом соответствует отчётности." % src
    return out


# ── кредитная история эмитента ──

def _iss_bonds_of(inn):
    """Все выпуски облигаций эмитента, известные Мосбирже (в обращении и погашенные), кэш сутки."""
    key = "iss_bonds_v1_" + inn
    hit = store().get(key, ttl=DAY)
    if hit is not None:
        return hit
    out, seen = [], set()
    for start in (0, 100, 200, 300):
        j = _iss_json("https://iss.moex.com/iss/securities.json?iss.meta=off&q=%s&limit=100&start=%d" % (inn, start), 25)
        rows = _iss_table(j, "securities")
        for r in rows:
            if str(r.get("emitent_inn") or "") != inn or r.get("group") != "stock_bonds":
                continue
            k = r.get("isin") or r.get("secid")
            if k in seen:
                continue
            seen.add(k)
            out.append({"isin": k, "secid": r.get("secid"), "name": r.get("shortname") or r.get("name"), "traded": bool(r.get("is_traded"))})
        if len(rows) < 100:
            break
    store().put(key, out)
    return out


def iss_history(inn):
    """Выпуски эмитента и флаги дефолта/технического дефолта (проверяется до 30 выпусков, сначала торгуемые)."""
    bonds = _iss_bonds_of(inn)
    order = sorted(bonds, key=lambda b: (not b["traded"], b["name"] or ""))
    chk = [b for b in order if b["isin"] and str(b["isin"]).startswith("RU")][:30]
    fl = pool_map(lambda b: _mon_flags(b["isin"]), chk, workers=5)
    items = []
    for b, f in zip(chk, fl):
        items.append({"isin": b["isin"], "name": b["name"], "traded": b["traded"], "default": bool(f.get("default")), "tech": bool(f.get("tech"))})
    nd = sum(1 for x in items if x["default"])
    nt = sum(1 for x in items if x["tech"] and not x["default"])
    if nd:
        verdict = "В истории эмитента есть дефолт по облигациям (%d из %d проверенных выпусков)." % (nd, len(items))
    elif nt:
        verdict = "Был технический дефолт (%d из %d проверенных выпусков): выплата задержана, но затем произведена." % (nt, len(items))
    elif items:
        verdict = "Дефолтов и технических дефолтов по проверенным выпускам не отмечено."
    else:
        verdict = "Выпусков эмитента на Мосбирже не найдено."
    return {"total": len(bonds), "traded": sum(1 for b in bonds if b["traded"]), "checked": len(items), "defaults": nd, "tech": nt,
            "items": items, "verdict": verdict}


# ── карточка эмитента ──

def _iss_market_bonds(inn, isin):
    """Выпуски эмитента, торгуемые в скринере: список для карточки, спред и рейтинг выбранной бумаги."""
    uni = {e["_isin"]: e for e in _bc_universe()}
    out = []
    for b in _iss_bonds_of(inn):
        e = uni.get(b["isin"])
        if e and e.get("cur") == "RUB":
            rt = e.get("_rt")
            out.append({"isin": e["_isin"], "name": e["name"], "yield": e.get("yield"), "spread": e.get("spread"), "dur": e.get("dur"),
                        "rating": rt["v"] if rt else None, "mat": e.get("mat"), "turn": e.get("turn"), "me": e["_isin"] == isin})
    out.sort(key=lambda x: (x["dur"] or 0))
    return out


def _iss_pick_spread(own, others):
    """Спред для сопоставления с отчётностью: собственный, а если он выброс (< −5 или > 40 п.п.: флоатеры, короткие выпуски
    у оферты) — медиана остальных выпусков эмитента. Если все выбросы — спреда нет, сравнение идёт по рейтингу."""
    ok = lambda v: v is not None and -5 <= v <= 40      # noqa: E731
    if ok(own):
        return own
    sp = sorted(v for v in others if ok(v))
    if sp:
        return sp[len(sp) // 2]
    return None


def _iss_spread_rating(mb, isin):
    me = next((x for x in mb if x["me"]), None)
    spread = _iss_pick_spread(me.get("spread") if me else None, [x.get("spread") for x in mb if x is not me])
    rts = [x["rating"] for x in mb if x.get("rating") in RATING_SCALE]
    rating = (me or {}).get("rating") or (max(rts, key=RATING_SCALE.index) if rts else None)
    return spread, rating


def issuer_card(isin):
    isin = (isin or "").strip().upper()
    card = {"ok": False, "isin": isin, "errors": []}
    em = issuer_of(isin)
    if not em:
        card["errors"].append("Не удалось определить эмитента по ISIN (Мосбиржа недоступна или бумага не найдена).")
        return card
    card["issuer"] = {"title": em.get("title"), "short": em.get("short") or em.get("title"), "inn": em.get("inn"), "emitter_id": em.get("emitter_id")}
    inn = em.get("inn")
    if not inn:
        card["errors"].append("У эмитента нет ИНН в справочнике Мосбиржи (иностранный эмитент, государство).")
        card["fin"] = {"status": "noinn", "years": []}
        card["score"] = {"ok": False, "reason": "ИНН эмитента неизвестен."}
        return card

    def run(fn):
        try:
            return fn(), None
        except Exception as e:  # noqa: BLE001
            return None, str(e)[:120]
    (fin, e1), (hist, e2), (mb, e3), (ifr, e4) = pool_map(run, [lambda: issuer_fin(inn, em.get("title") or ""), lambda: iss_history(inn),
                                                                lambda: _iss_market_bonds(inn, isin), lambda: ifrs_bundle(isin, em)], workers=4)
    for lab, er in (("отчётность ФНС", e1), ("история выпусков", e2), ("рыночные данные", e3), ("отчётность МСФО", e4)):
        if er:
            card["errors"].append("%s: %s" % (lab, er))
    ci = tcat_info(isin) or {}
    card["fin"] = fin or {"status": "err", "years": [], "note": "Отчётность временно недоступна."}
    card["score"] = iss_score_fin(fin, _iss_is_fin(em.get("title"), ci.get("sector"))) if fin else {"ok": False, "reason": "Отчётность недоступна."}
    card["ifrs"] = ifr                       # {ticker, how, group, kind, fin, score, url} или None
    card["basis"] = "ifrs" if ifr and ifr["score"].get("ok") else "rsbu"
    main_sc = ifr["score"] if card["basis"] == "ifrs" else card["score"]
    card["history"] = hist
    card["bonds"] = mb or []
    spread, rating = _iss_spread_rating(card["bonds"], isin)
    if not rating:
        try:
            rt = best_rating(isin, em.get("title") or "")
            rating = rt["v"] if rt else None
        except Exception:  # noqa: BLE001
            rating = None
    card["market"] = iss_market(main_sc.get("score") if main_sc.get("ok") else None, spread, rating)
    card["ok"] = True
    return card


# ── эмитенты портфеля ──

def _iss_portfolio(cfg, acc, job):
    rep_ = build_bonds(cfg, acc)
    rows = [r for r in rep_.get("rows", []) if r.get("isin") and r.get("value_rub")]
    gov = [r for r in rows if r.get("sector") == "government"]
    work = [r for r in rows if r.get("sector") != "government"]
    job["total"] = len(work)
    # 1) эмитент по ISIN (кэш навсегда), 2) группировка по ИНН
    ems = pool_map(lambda r: issuer_of(r["isin"]), work, workers=4)
    groups = {}
    for r, em in zip(work, ems):
        k = (em or {}).get("inn") or ("isin:" + r["isin"])
        g = groups.setdefault(k, {"inn": (em or {}).get("inn"), "emitter_id": (em or {}).get("emitter_id"), "title": (em or {}).get("short") or (em or {}).get("title") or r.get("name"),
                                  "full": (em or {}).get("title"), "rows": [], "known": bool(em)})
        g["rows"].append(r)
    glist = list(groups.values())
    job["total"] = len(glist)
    uni = {}
    try:
        uni = {e["_isin"]: e for e in _bc_universe()}
    except Exception:  # noqa: BLE001
        pass

    def one(g):
        try:
            rs = sorted(g["rows"], key=lambda r: -(r.get("value_rub") or 0))
            top = rs[0]
            val = sum(r.get("value_rub") or 0 for r in rs)
            res = {"inn": g["inn"], "title": g["title"], "full": g["full"], "isin": top["isin"], "logo": top.get("logo"), "color": top.get("color"),
                   "value_rub": val, "share": sum(r.get("share") or 0 for r in rs), "n_bonds": len(rs), "bonds": [r["name"] for r in rs][:4]}
            ci = tcat_info(top["isin"]) or {}
            rts = []
            for r in rs:
                try:
                    b = r.get("rating") if isinstance(r.get("rating"), dict) else None   # рейтинг уже найден в отчёте по облигациям
                    b = b or best_rating(r["isin"], r.get("name") or "")
                    if b and b.get("v") in RATING_SCALE:
                        rts.append(b["v"])
                except Exception:  # noqa: BLE001
                    pass
            rating = max(rts, key=RATING_SCALE.index) if rts else None
            sps = [uni[r["isin"]].get("spread") for r in rs if r["isin"] in uni]
            spread = _iss_pick_spread(None, sps)
            res["rating"] = rating
            res["spread"] = spread
            if not g["inn"]:
                res.update(status="noinn", note="ИНН эмитента неизвестен.", score=None)
                return res
            fin = issuer_fin(g["inn"], g["full"] or "")
            try:
                ib = ifrs_bundle(top["isin"], {"emitter_id": g.get("emitter_id"), "inn": g["inn"], "title": g["full"], "short": g["title"]})
            except Exception:  # noqa: BLE001
                ib = None
            res["status"] = fin["status"]
            res["note"] = fin.get("note")
            sc = iss_score_fin(fin, _iss_is_fin(g["full"] or g["title"], ci.get("sector")))
            res["fin_mode"] = bool(sc.get("fin_mode"))
            res["rsbu_score"] = sc["score"] if sc.get("ok") else None
            if ib:
                res["ifrs_ticker"], res["ifrs_how"] = ib["ticker"], ib["how"]
                res["ifrs_score"] = ib["score"]["score"] if ib["score"].get("ok") else None
                if not ib["score"].get("ok"):
                    res["ifrs_note"] = ib["score"].get("reason")
            if ib and ib["score"].get("ok"):
                isc = ib["score"]
                c_ = ib["fin"].get("ltm") or ib["fin"]["years"][-1]
                res.update(basis="ifrs", score=isc["score"], key=isc["key"], label=isc["label"], year=isc["year"], period=isc["period"], holding=False,
                           fin_mode=False, bank=isc.get("bank"), nd_ebit=c_.get("nd_ebitda"), cover=c_.get("cover"), eq_ratio=c_.get("eq_ratio"),
                           rev=c_.get("rev"), net_debt=c_.get("net_debt"), debt_eq=None)
                res["market"] = iss_market(isc["score"], spread, rating)
            elif sc.get("ok"):
                res["basis"] = "rsbu"
                last = fin["years"][-1]
                res.update(score=sc["score"], key=sc["key"], label=sc["label"], year=sc["year"], holding=sc.get("holding"),
                           nd_ebit=last.get("nd_ebit"), cover=last.get("cover"), eq_ratio=last.get("eq_ratio"), cur_liq=last.get("cur_liq"),
                           rev=last.get("rev"), net_debt=last.get("net_debt"), debt_eq=last.get("debt_eq"))
                res["market"] = iss_market(sc["score"], spread, rating)
            else:
                res.update(score=None, note=sc.get("reason") or res.get("note"))
            return res
        except Exception as e:  # noqa: BLE001
            return {"inn": g["inn"], "title": g["title"], "isin": g["rows"][0]["isin"], "value_rub": sum(r.get("value_rub") or 0 for r in g["rows"]),
                    "share": sum(r.get("share") or 0 for r in g["rows"]), "n_bonds": len(g["rows"]), "score": None, "status": "err",
                    "note": "Ошибка: %s" % str(e)[:100]}
        finally:
            job["done"] += 1
    out = pool_map(one, glist, workers=4)
    out.sort(key=lambda x: -(x.get("value_rub") or 0))
    scored = [x for x in out if x.get("score") is not None]
    sh_s = sum(x["share"] for x in scored)
    bad = sum(x["share"] for x in scored if x["key"] in ("weak", "alarm"))
    dist = {k: sum(1 for x in scored if x["key"] == k) for _, k, _t in ISS_LABELS}
    return {"rows": out, "n": len(out), "n_scored": len(scored), "share_scored": sh_s, "share_bad": bad,
            "avg_score": (sum(x["score"] * x["share"] for x in scored) / sh_s) if sh_s else None, "dist": dist,
            "gov_share": sum(r.get("share") or 0 for r in gov), "gov_n": len(gov), "updated": datetime.now().strftime("%H:%M")}


def issuers_payload(cfg, acc, q, force):
    key = (token_key(cfg), acc)
    with _iss_jobs_lock:
        job = _iss_jobs.get(key)
        fresh = job and job["state"] == "done" and time.time() - job["t"] < 1800
        if job and job["state"] == "run":
            return {"pending": True, "done": job["done"], "total": job["total"]}
        if fresh and not force:
            return job["res"]
        job = {"state": "run", "done": 0, "total": 0, "t": time.time(), "res": None}
        _iss_jobs[key] = job

    def work():
        try:
            job["res"] = _iss_portfolio(cfg, acc, job)
            job["state"] = "done"
        except Exception as e:  # noqa: BLE001
            job["res"] = {"error": str(e)[:200] or "Не удалось собрать эмитентов"}
            job["state"] = "done"
        job["t"] = time.time()
    threading.Thread(target=work, daemon=True).start()
    return {"pending": True, "done": 0, "total": 0}


def _iss_api_one(cfg, acc, q, force):
    isin = (q.get("isin") or "").strip().upper()
    key = "iss_card_v3_" + isin
    if not force:
        hit = store().get(key, ttl=6 * 3600)
        if hit:
            return hit
    c = issuer_card(isin)
    if c.get("ok") and not c["errors"]:
        store().put(key, c)
    return c


