# ═══════════════════════════════ календарь событий ═══════════════════════════════

EV_KINDS = {"cbr": "Заседание ЦБ", "coupon": "Купон", "redemption": "Погашение", "amort": "Амортизация", "dividend": "Дивиденд",
            "offer": "Оферта", "primary": "Размещение", "w_coupon": "Купон (наблюдение)", "w_redemption": "Погашение (наблюдение)",
            "w_offer": "Оферта (наблюдение)"}
CBR_CAL_URL = "https://www.cbr.ru/dkp/cal_mp/"
CBR_CAL_KEY = "cbr_cal_v1"
_RU_MONTHS = {"января": 1, "февраля": 2, "марта": 3, "апреля": 4, "мая": 5, "июня": 6, "июля": 7, "августа": 8, "сентября": 9,
              "октября": 10, "ноября": 11, "декабря": 12}


def cbr_meetings():
    """Даты заседаний Совета директоров Банка России по ключевой ставке: {"dates": [...], "ok": bool, "error": str}. Кэш 1 день."""
    st = store()
    hit = st.get(CBR_CAL_KEY, ttl=DAY)
    if hit and hit.get("dates"):
        return hit
    try:
        s = http_text(CBR_CAL_URL, timeout=30)
        s = s.replace("&nbsp;", " ").replace("\xa0", " ")
        parts = re.split(r'<div class="date[^"]*">', s)
        dates = set()
        for p in parts[1:]:
            m = re.match(r"\s*(\d{1,2})\s+([а-яё]+)\s+(\d{4})", p)
            if not m or m.group(2) not in _RU_MONTHS:
                continue
            head = p[:1500]
            nxt = head.find('class="date')
            body = head if nxt < 0 else head[:nxt]
            if re.search(r"Заседание Совета директоров", body):
                dates.add(date(int(m.group(3)), _RU_MONTHS[m.group(2)], int(m.group(1))).isoformat())
        if not dates:
            raise ValueError("на странице ЦБ не найдено заседаний")
        out = {"dates": sorted(dates), "ok": True}
        st.put(CBR_CAL_KEY, out)
        return out
    except Exception as e:  # noqa: BLE001
        old = st.get(CBR_CAL_KEY)
        if old and old.get("dates"):
            return dict(old, stale=True)
        return {"dates": [], "ok": False, "error": str(e)[:160]}


def _ev(d, kind, title, isin=None, amount=None, note="", **kw):
    e = {"date": d, "kind": kind, "title": title, "isin": isin or None, "amount": amount, "note": note}
    e.update(kw)
    return e


EV_BADGE = {"put": "PUT", "call": "CALL", "unknown": "тип не указан"}


def _ru_pct(x):
    return str(x).replace(".", ",")


def offer_events(offs, name, isin, frm, to, pref=""):
    """События по офертам выпуска (offs — результат offer_kinds) в окне [frm, to]. У каждого есть badge (PUT / CALL / тип не указан)
    и label. PUT: открытие приёма заявок, последний день подачи, дата выкупа; CALL: возможное досрочное погашение; тип неизвестен: оферта."""
    out = []
    kind = pref + "offer"
    for o in offs:
        if o.get("status") == "cancelled":
            continue
        k, d = o["kind"], o["date"]
        badge = EV_BADGE.get(k, EV_BADGE["unknown"])
        price = (" по цене %s%% от номинала" % _ru_pct(o["price"])) if o.get("price") else ""
        ps, pe = o.get("period_start"), o.get("period_end")
        win = ("; приём заявок %s – %s" % (_dmy(ps), _dmy(pe))) if ps and pe else ""
        if k == "put":
            if ps and frm <= ps <= to:
                out.append(_ev(ps, kind, name, isin, None, "Открыт приём заявок по пут-оферте; выкуп %s%s" % (_dmy(d), price),
                               badge=badge, label="Открыт приём заявок по пут-оферте", sub="put_open"))
            if pe and frm <= pe <= to:
                out.append(_ev(pe, kind, name, isin, None, "Последний день подачи заявки (через брокера); выкуп %s%s" % (_dmy(d), price),
                               badge=badge, label="Последний день подачи заявки", sub="put_close"))
            if frm <= d <= to:
                out.append(_ev(d, kind, name, isin, None, "Дата выкупа по оферте%s%s" % (price, win),
                               badge=badge, label="Дата выкупа по оферте", sub="put_buyback"))
        elif frm <= d <= to:
            if k == "call":
                out.append(_ev(d, kind, name, isin, None, "Возможное досрочное погашение (колл): решает эмитент, заявку подавать не нужно%s" % price,
                               badge=badge, label="Возможное досрочное погашение (колл)", sub="call"))
            else:
                out.append(_ev(d, kind, name, isin, None, "Оферта%s: тип не указан, проверьте условия в документах выпуска%s" % (price, win),
                               badge=badge, label="Оферта (тип не указан)", sub="unknown"))
    return out


def _dmy(d):
    return "%s.%s.%s" % (d[8:10], d[5:7], d[:4]) if d and len(d) == 10 else (d or "")


def _bz_events(isin, name, today, horizon, pref, held=None):
    """События выпуска из данных Мосбиржи: купоны, амортизации, погашение (последняя выплата), оферты."""
    bz = moex_bondization(isin)
    if not bz:
        return []
    out = []
    pay = [(c["coupondate"], c) for c in bz.get("coupons") or [] if c.get("coupondate")]
    am = [(a["amortdate"], a) for a in bz.get("amort") or [] if a.get("amortdate")]
    last_am = max([d for d, _ in am] or [""])
    last_cp = max([d for d, _ in pay] or [""])
    mat = max(last_am, last_cp)
    for d, c in pay:
        if today <= d <= horizon:
            v = c.get("value")
            out.append(_ev(d, pref + "coupon", name, isin, (v * held) if (v and held) else None,
                           ("купон %s на бумагу" % ("%.2f" % v).replace(".", ",") + " " + ("₽" if (c.get("faceunit") or "SUR") in ("SUR", "RUB") else c.get("faceunit") or "")) if v
                           else "размер купона ещё не объявлен"))
    for d, a in am:
        if today <= d <= horizon:
            if d == mat:
                out.append(_ev(d, pref + "redemption", name, isin, None, "погашение выпуска"))
            elif not pref:
                v = a.get("value")
                out.append(_ev(d, "amort", name, isin, (v * held) if (v and held) else None, "частичное погашение номинала"))
    if mat and today <= mat <= horizon and mat not in [d for d, _ in am]:
        out.append(_ev(mat, pref + "redemption", name, isin, None, "погашение выпуска"))
    try:
        opt = moex_bond_options(isin)
    except Exception:  # noqa: BLE001
        opt = None
    out += offer_events(offer_kinds(bz, opt, None, _day_add(today, -1), with_done=True), name, isin, today, horizon, pref)
    return out


def events_payload(cfg, acc, q):
    today = date.today().isoformat()
    frm = (q.get("from") or "").strip() or today[:8] + "01"
    if not re.match(r"^\d{4}-\d\d-\d\d$", frm):
        raise ApiError("Даты нужно указывать в формате ГГГГ-ММ-ДД.", 400)
    to = (q.get("to") or "").strip() or _day_add(frm, 92)
    if not re.match(r"^\d{4}-\d\d-\d\d$", to):
        raise ApiError("Даты нужно указывать в формате ГГГГ-ММ-ДД.", 400)
    kinds = [k for k in (q.get("kinds") or "").split(",") if k]
    events, warn, src = [], [], {}
    # 1. заседания Банка России
    cb = cbr_meetings()
    src["cbr"] = bool(cb.get("ok"))
    if not cb.get("ok"):
        warn.append("Календарь заседаний Банка России не удалось получить с сайта cbr.ru (%s). Остальные события показаны." % cb.get("error", "нет связи"))
    for d in cb.get("dates") or []:
        if frm <= d <= to:
            events.append(_ev(d, "cbr", "Заседание Банка России по ключевой ставке", None, None,
                              "решение по ключевой ставке объявляется в 13:30 по Москве"))
    # 2. выплаты и оферты по портфелю
    held = set()
    try:
        rep = build_bonds(cfg, acc)
        src["portfolio"] = True
        by_tk = {r.get("ticker"): r for r in rep["rows"] if r.get("ticker")}
        for p in rep.get("payments") or []:
            if not (frm <= p["date"] <= to):
                continue
            r = by_tk.get(p.get("ticker")) or {}
            isin = r.get("isin") if p["kind"] != "dividend" else None
            note = {"coupon": "купонная выплата", "redemption": "погашение облигации", "dividend": "дивиденд"}.get(p["kind"], p["kind"])
            if p.get("est"):
                note += " (оценка)"
            events.append(_ev(p["date"], p["kind"], p["name"], isin, round(p["amount"], 2), note))
        for r in rep["rows"]:
            if r.get("isin") and r.get("qty"):
                held.add(r["isin"])
        rows = [r for r in rep["rows"] if r.get("isin") and r.get("qty")]

        def one(r):
            try:
                bz = moex_bondization(r["isin"])
                try:
                    opt = moex_bond_options(r["isin"])
                except Exception:  # noqa: BLE001
                    opt = None
                offs = offer_kinds(bz or {}, opt, r.get("call"), _day_add(frm, -1), with_done=True)
                out = offer_events(offs, r["name"], r["isin"], frm, to)
                for a in (bz or {}).get("amort") or []:
                    d = a.get("amortdate")
                    if d and frm <= d <= to and a.get("value") and d != max([x.get("amortdate") or "" for x in bz["amort"]] + [""]):
                        out.append(_ev(d, "amort", r["name"], r["isin"], round(a["value"] * r["qty"], 2), "частичное погашение номинала"))
                return out
            except Exception:  # noqa: BLE001
                return []
        have_am = {(e["isin"], e["date"]) for e in events if e["kind"] == "amort"}
        for lst in pool_map(one, rows, workers=8):
            for e in lst:
                if e["kind"] == "amort" and (e["isin"], e["date"]) in have_am:
                    continue
                events.append(e)
    except Exception as e:  # noqa: BLE001
        src["portfolio"] = False
        warn.append("Выплаты и оферты по портфелю не загружены: %s" % str(e)[:140])
    # 3. объявленные размещения
    try:
        for r in primary_rows():
            d = r.get("start")
            if d and frm <= d <= to:
                events.append(_ev(d, "primary", r.get("short") or r.get("issuer"), r.get("isin") or None, None,
                                  ((r.get("desc") or "") + ((" · книга заявок: " + r["book"]) if r.get("book") else "")).strip(" ·") or "начало размещения"))
        src["primary"] = True
    except Exception as e:  # noqa: BLE001
        src["primary"] = False
        warn.append("Размещения не загружены: %s" % str(e)[:100])
    # 4. список наблюдения
    fn = globals().get("watch_isins")
    if fn:
        try:
            ws = [x for x in (fn() or []) if x]
            items = []
            for x in ws:
                if isinstance(x, dict):
                    items.append((x.get("isin"), x.get("name") or x.get("isin")))
                else:
                    items.append((str(x), str(x)))
            items = [(i, n) for i, n in items if i and i not in held][:60]

            def wone(it):
                try:
                    nm = it[1]
                    if nm == it[0]:
                        ci = tcat_info(it[0]) if globals().get("tcat_info") else None
                        nm = (ci or {}).get("name") or it[0]
                    return _bz_events(it[0], nm, frm, to, "w_")
                except Exception:  # noqa: BLE001
                    return []
            for lst in pool_map(wone, items, workers=8):
                events += lst
            src["watch"] = len(items)
        except Exception as e:  # noqa: BLE001
            warn.append("Список наблюдения не загружен: %s" % str(e)[:100])
    if kinds:
        events = [e for e in events if e["kind"] in kinds]
    seen, uniq = {}, []
    for e in sorted(events, key=lambda e: (e["date"], e["kind"], e["title"])):
        k = (e["date"], e["kind"], e["title"], e.get("isin"), e.get("sub"))
        if k in seen:
            if e.get("amount") is not None and seen[k]["amount"] is not None and e["kind"] in ("coupon", "dividend", "redemption", "amort"):
                seen[k]["amount"] = round(seen[k]["amount"] + e["amount"], 2)
            continue
        seen[k] = e
        uniq.append(e)
    return {"account": acc, "from": frm, "to": to, "events": uniq, "kinds": EV_KINDS, "warnings": warn, "sources": src, "today": today}


# ── iCalendar (RFC 5545) ──

def _ics_esc(t):
    return str(t if t is not None else "").replace("\\", "\\\\").replace(";", "\\;").replace(",", "\\,").replace("\r\n", "\n").replace("\r", "\n").replace("\n", "\\n")


def _ics_fold(line):
    """Строки длиннее 75 октетов переносятся (CRLF + пробел), многобайтные символы не режутся."""
    b = line.encode("utf-8")
    if len(b) <= 75:
        return line
    out, cur, n = [], "", 0
    for ch in line:
        w = len(ch.encode("utf-8"))
        if n + w > (75 if not out else 74):
            out.append(cur)
            cur, n = "", 0
        cur += ch
        n += w
    out.append(cur)
    return "\r\n ".join(out)


def build_ics(events):
    now = datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")
    lines = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//T-Invest Analytics//Calendar//RU", "CALSCALE:GREGORIAN", "METHOD:PUBLISH",
             "X-WR-CALNAME:T-Invest Analytics: события", "X-WR-TIMEZONE:Europe/Moscow"]
    for e in events:
        try:
            d0 = datetime.strptime(e["date"], "%Y-%m-%d")
        except ValueError:
            continue
        d1 = d0 + timedelta(days=1)
        uid = hashlib.sha1(("%s|%s|%s|%s%s" % (e["date"], e["kind"], e.get("isin") or "", e["title"], ("|" + e["sub"]) if e.get("sub") else "")).encode("utf-8")).hexdigest()[:24] + "@tinvest-analytics"
        summ = "%s: %s" % (e.get("label") or EV_KINDS.get(e["kind"], e["kind"]), e["title"])
        if e.get("badge"):
            summ += " [%s]" % e["badge"]
        desc = e.get("note") or ""
        if e.get("amount") is not None:
            desc += ("; " if desc else "") + "сумма ≈ %s ₽" % ("{:,.2f}".format(e["amount"]).replace(",", " ").replace(".", ","))
        if e.get("isin"):
            desc += ("; " if desc else "") + "ISIN " + e["isin"]
        lines += ["BEGIN:VEVENT", "UID:" + uid, "DTSTAMP:" + now, "DTSTART;VALUE=DATE:" + d0.strftime("%Y%m%d"),
                  "DTEND;VALUE=DATE:" + d1.strftime("%Y%m%d"), "SUMMARY:" + _ics_esc(summ), "DESCRIPTION:" + _ics_esc(desc),
                  "TRANSP:TRANSPARENT", "END:VEVENT"]
    lines.append("END:VCALENDAR")
    return ("\r\n".join(_ics_fold(l) for l in lines) + "\r\n").encode("utf-8")


def _api_events(cfg, acc, q, force):
    return events_payload(cfg, acc, q)


def _api_events_ics(cfg, acc, q, force):
    q = dict(q)
    q.setdefault("from", date.today().isoformat())
    q.setdefault("to", _day_add(q["from"], 366))
    q["kinds"] = q.get("kinds", "")
    p = events_payload(cfg, acc, q)
    return (200, build_ics(p["events"]), "text/calendar; charset=utf-8",
            {"Content-Disposition": 'attachment; filename="tinvest_events.ics"'})


API_GET["/api/events"] = _api_events
API_GET["/api/events.ics"] = _api_events_ics
# ═══════════════════════════════ список наблюдения, заметки, уведомления в Telegram ═══════════════════════════════
# Список наблюдения и дневник хранятся только в локальной базе. Уведомления в Telegram идут через сервер данных
# (POST /v1/notify с ключом из бота) и общий бот: наружу уходят только тексты уведомлений, токен Т-Инвестиций — никогда.
# Прежний «личный бот» (tg_token, tg_chat) удалён; старые значения стираются из настроек при запуске.

WATCH_KEY, NOTES_KEY, TG_SENT_KEY, TG_STATE_KEY = "watch_v1", "notes_v1", "tg_sent_v1", "tg_state_v1"
TG_DEFAULTS = {"tg_enabled": False, "tg_on_mon": True, "tg_on_watch": True, "tg_pay_days": 0, "tg_digest": False, "tg_digest_time": "10:00"}
TG_LEGACY_KEYS = ("tg_token", "tg_chat")
_watch_lock = threading.Lock()
_tg_lock = threading.Lock()


def _isin_ok(s):
    s = str(s or "").strip().upper()
    return s if re.fullmatch(r"[A-Z0-9]{6,16}", s) else ""


def _num(x):
    try:
        v = float(str(x).replace(",", ".").replace(" ", ""))
        return v if v == v and abs(v) < 1e9 else None
    except (TypeError, ValueError):
        return None


def watch_items():
    return [dict(x) for x in (store().get(WATCH_KEY) or []) if isinstance(x, dict) and x.get("isin")]


def watch_isins():
    """ISIN бумаг из списка наблюдения (для других модулей)."""
    return [x["isin"] for x in watch_items()]


def _scr_by_isin():
    out = {}
    try:
        for s in screener_rows():
            out[s.get("isin") or s["id"]] = s
    except Exception:  # noqa: BLE001
        pass
    return out


def _bond_name(isin, sec=None):
    s = (sec or {}).get(isin)
    if s and s.get("name"):
        return s["name"]
    try:
        ci = tcat_info(isin)
        if ci and ci.get("name"):
            return ci["name"]
    except Exception:  # noqa: BLE001
        pass
    return isin


def watch_post(cfg, body):
    act = str(body.get("action") or "")
    isin = _isin_ok(body.get("isin"))
    if not isin:
        raise ApiError("Укажите ISIN бумаги.", 400)
    with _watch_lock:
        items = watch_items()
        cur = next((x for x in items if x["isin"] == isin), None)
        if act == "toggle":
            act = "remove" if cur else "add"
        if act == "add":
            if not cur:
                cur = {"isin": isin, "added": date.today().isoformat()}
                items.append(cur)
        elif act == "remove":
            items = [x for x in items if x["isin"] != isin]
        elif act == "update":
            if not cur:
                raise ApiError("Бумаги нет в списке наблюдения.", 404)
        else:
            raise ApiError("Неизвестное действие.", 400)
        if act in ("add", "update") and cur is not None:
            for k in ("target_yield", "target_price"):
                if k in body:
                    v = _num(body[k]) if str(body[k]).strip() != "" else None
                    if v is not None and v <= 0:
                        v = None
                    if v is None:
                        cur.pop(k, None)
                    else:
                        cur[k] = round(v, 4)
            if "note" in body:
                n = str(body["note"] or "").strip()[:300]
                if n:
                    cur["note"] = n
                else:
                    cur.pop("note", None)
        store().put(WATCH_KEY, items)
    mem_clear_watch()
    return {"ok": True, "isins": [x["isin"] for x in items], "in_watch": any(x["isin"] == isin for x in items)}


def mem_clear_watch():
    with _mem_lock:
        for k in [k for k in _mem if isinstance(k, tuple) and k and k[0] == "monitor_for"]:
            _mem.pop(k, None)


def watch_search(cfg, acc, q, force):
    s = str((q or {}).get("q") or "").strip().lower()
    if len(s) < 2:
        return {"rows": []}
    have = set(watch_isins())
    out = []
    for r in screener_rows():
        isin = r.get("isin") or r["id"]
        if s in (r.get("name") or "").lower() or s in isin.lower() or s in (r.get("full") or "").lower() or s in (r.get("id") or "").lower():
            out.append({"isin": isin, "name": r.get("name"), "yield": r.get("yield"), "mat": r.get("mat"), "in_watch": isin in have,
                        "turn": r.get("turn") or 0})
    out.sort(key=lambda x: (not x["name"].lower().startswith(s) if x["name"] else True, -x["turn"]))
    return {"rows": out[:12]}


# ── дневник ──

def notes_all():
    return [dict(x) for x in (store().get(NOTES_KEY) or []) if isinstance(x, dict) and x.get("id")]


def notes_get(cfg, acc, q, force):
    isin = _isin_ok((q or {}).get("isin"))
    sec = _scr_by_isin()
    rows = [n for n in notes_all() if not isin or n["isin"] == isin]
    for n in rows:
        n["name"] = _bond_name(n["isin"], sec)
    rows.sort(key=lambda n: (n.get("date") or "", n["id"]), reverse=True)
    return {"rows": rows}


def notes_post(cfg, body):
    act = str(body.get("action") or "")
    with _watch_lock:
        items = notes_all()
        if act == "add":
            isin = _isin_ok(body.get("isin"))
            text = str(body.get("text") or "").strip()[:2000]
            if not isin or not text:
                raise ApiError("Укажите бумагу и текст заметки.", 400)
            n = {"id": "n%d%03d" % (int(time.time() * 1000), len(items) % 1000), "isin": isin,
                 "date": date.today().isoformat(), "text": text}
            d = _num(body.get("remind_days"))
            if d is not None and 0 < d <= 3650:
                n["remind_on"] = (date.today() + timedelta(days=int(d))).isoformat()
            items.append(n)
        elif act == "delete":
            items = [x for x in items if x["id"] != body.get("id")]
        elif act == "done":
            for x in items:
                if x["id"] == body.get("id"):
                    x.pop("remind_on", None)
        else:
            raise ApiError("Неизвестное действие.", 400)
        store().put(NOTES_KEY, items)
    mem_clear_watch()
    return {"ok": True}


# ── данные раздела «Наблюдение» и тревоги ──

def watch_payload(cfg, acc=None, q=None, force=False):
    items = watch_items()
    isins = [x["isin"] for x in items]
    sec = _scr_by_isin()
    mon = build_monitor_for(cfg, isins) if isins else {"alerts": [], "rows": [], "notes": []}
    mrow = {r["isin"]: r for r in mon.get("rows") or []}
    today = date.today().isoformat()
    rows, alerts = [], list(mon.get("alerts") or [])
    for it in items:
        isin = it["isin"]
        s = sec.get(isin)
        m = mrow.get(isin) or {}
        try:
            ci = tcat_info(isin) or {}
            rt = best_rating(isin, ci.get("name") or (s or {}).get("name") or "")
        except Exception:  # noqa: BLE001
            ci, rt = {}, None
        row = dict(it, name=_bond_name(isin, sec), in_market=bool(s), rating=rt["v"] if rt else None,
                   sector=ci.get("sector"), price=(s or {}).get("price"), yield_=(s or {}).get("yield"),
                   spread=(s or {}).get("spread"), dur=(s or {}).get("dur"), turn=(s or {}).get("turn"),
                   mat=(s or {}).get("mat") or ci.get("maturity"), offer=(s or {}).get("offer"), cur=(s or {}).get("cur"),
                   coupon=(s or {}).get("coupon"), chg5=m.get("chg5"), chg30=m.get("chg30"), spread_chg30=m.get("spread_chg30"),
                   spark=m.get("spark"), flags=m.get("flags") or [], rating_state=m.get("rating"))
        base = {"isin": isin, "isins": [isin], "name": row["name"], "bonds": [row["name"]]}
        ty, tp = it.get("target_yield"), it.get("target_price")
        if s and ty is not None and s.get("yield") is not None and s["yield"] >= ty:
            alerts.append(dict(base, id="gy|%s|%s" % (isin, ty), severity="medium", kind="goal", date=today,
                               message="Цель достигнута: доходность %s %% (цель — от %s %%)" % (_f2(s["yield"]), _f2(ty)), url=""))
        if s and tp is not None and s.get("price") is not None and s["price"] <= tp:
            alerts.append(dict(base, id="gp|%s|%s" % (isin, tp), severity="medium", kind="goal", date=today,
                               message="Цель достигнута: цена %s %% (цель — не выше %s %%)" % (_f2(s["price"]), _f2(tp)), url=""))
        if not s:
            row["flags"] = row["flags"] + ["нет данных Мосбиржи"]
        rows.append(row)
    for n in notes_all():
        if n.get("remind_on") and n["remind_on"] <= today:
            nm = _bond_name(n["isin"], sec)
            alerts.append({"isin": n["isin"], "isins": [n["isin"]], "name": nm, "bonds": [nm], "id": "rm|" + n["id"], "severity": "medium",
                           "kind": "reminder", "date": n["remind_on"], "note_id": n["id"], "url": "",
                           "message": "Напоминание из дневника от %s: %s" % (n["date"][8:] + "." + n["date"][5:7], n["text"][:160])})
    alerts.sort(key=lambda a: (_SEV[a["severity"]], _neg(a["date"])))
    for a in alerts:
        for r in rows:
            if r["isin"] in (a.get("isins") or []):
                r["n_" + a["severity"]] = r.get("n_" + a["severity"], 0) + 1
    return {"items": rows, "alerts": alerts, "notes": mon.get("notes") or [],
            "summary": {s_: sum(1 for a in alerts if a["severity"] == s_) for s_ in _SEV}, "updated": time.time()}


def _f2(x):
    return ("%.2f" % x).replace(".", ",")


def watch_isins_get(cfg, acc, q, force):
    return {"isins": watch_isins()}


