def _ifrs_num(s):
    """'11 674' -> 11674.0; '-364.0' -> -364.0; '31.4%' -> 0.314; '' / '—' / мусор -> None."""
    if s is None:
        return None
    t = re.sub(r"<[^>]+>", "", str(s)).replace("&nbsp;", " ").replace("−", "-")
    t = re.sub(r"[\s  ]+", "", t).replace(",", ".")
    if not t or t in ("-", "—", "–"):
        return None
    pct = t.endswith("%")
    if pct:
        t = t[:-1]
    try:
        v = float(t)
    except ValueError:
        return None
    if v != v or v in (float("inf"), float("-inf")):
        return None
    return v / 100.0 if pct else v


def ifrs_parse(html):
    """HTML страницы smart-lab -> {labels: ['2021', ..., 'LTM'], rows: {поле: [значения по меткам, строки для текста]}} или None."""
    if not html or "field=" not in html:
        return None
    m = re.search(r"<tr[^>]*class=\"[^\"]*header_row[^\"]*\"[^>]*>(.*?)</tr>", html, re.S)
    if not m:
        return None
    labels = [x.strip() for x in re.findall(r"<strong>\s*([^<]+?)\s*</strong>", m.group(1))]
    labels = [x for x in labels if re.fullmatch(r"\d{4}|LTM", x)]
    if not labels:
        return None
    rows, bad = {}, 0
    for fm in re.finditer(r"<tr[^>]*\bfield=\"([A-Za-z0-9_]+)\"[^>]*>(.*?)</tr>", html, re.S):
        cells = []
        for am, body in re.findall(r"<td([^>]*)>(.*?)</td>", fm.group(2), re.S):
            if "chartrow" in am or "ltm_spc" in am:
                continue
            cells.append(re.sub(r"<[^>]+>", "", body).replace("&nbsp;", " ").strip())
        if len(cells) != len(labels):
            bad += 1
            continue
        rows[fm.group(1)] = cells
    if not rows or bad > len(rows):
        return None
    return {"labels": labels, "rows": rows}


_IFRS_BANK_KEYS = ("bank_assets", "net_interest_income", "net_operating_income")


def _ifrs_val(rows, key, i, scale=1.0):
    r = rows.get(key)
    if not r or i >= len(r):
        return None
    v = _ifrs_num(r[i])
    return None if v is None else v * scale


def _ifrs_period(rows, i, bank, y):
    """Один столбец (год или LTM) -> словарь показателей; суммы в млн ₽, доли — числами (0.25 = 25 %)."""
    g = lambda k, sc=1.0: _ifrs_val(rows, k, i, sc)   # noqa: E731
    M = 1000.0                                           # млрд -> млн
    p = {"y": y}
    if bank:
        p.update(rev=g("net_operating_income", M), net=g("net_income", M), assets=g("bank_assets", M), equity=g("capital", M),
                 nii=g("net_interest_income", M), roe=g("roe"), cost_risk=g("cost_of_risk_ratio"), npl=g("share_of_non_performing_loans"),
                 car=g("total_capital_adequacy_ratio"), nim=g("net_intertest_margin") if "net_intertest_margin" in rows else g("net_interest_margin"),
                 cti=g("cost_to_income"), ltd=g("loan_to_deposit_ratio"))
        if p["equity"] is not None and p["assets"]:
            p["eq_ratio"] = p["equity"] / p["assets"]
        return p
    p.update(rev=g("revenue", M), op_income=g("operating_income", M), ebitda=g("ebitda", M), net=g("net_income", M), interest=g("interest_expenses", M),
             debt=g("debt", M), cash=g("cash", M), net_debt=g("net_debt", M), assets=g("assets", M), ocf=g("ocf", M), capex=g("capex", M),
             roe=g("roe"))
    eq = g("net_assets", M)
    p["equity"] = eq if eq is not None else g("book_value", M)
    if p["net_debt"] is None and p["debt"] is not None and p["cash"] is not None:
        p["net_debt"] = p["debt"] - p["cash"]
    if p["ocf"] is not None and p["capex"] is not None:
        p["fcf"] = p["ocf"] - abs(p["capex"])
    else:
        p["fcf"] = g("fcf", M)
    e, nd, it, rv = p["ebitda"], p["net_debt"], p["interest"], p["rev"]
    p["nd_ebitda"] = nd / e if (nd is not None and e is not None and e > 0) else None
    p["cover"] = e / it if (e is not None and it is not None and it > 0) else None
    p["margin_ebitda"] = e / rv if (e is not None and rv) else None
    p["net_margin"] = p["net"] / rv if (p["net"] is not None and rv) else None
    p["eq_ratio"] = p["equity"] / p["assets"] if (p["equity"] is not None and p["assets"]) else None
    return p


def ifrs_build(parsed, ticker):
    """Результат ifrs_parse -> структура ifrs_fin (без сети; для тестов)."""
    labels, rows = parsed["labels"], parsed["rows"]
    bank = any(k in rows for k in _IFRS_BANK_KEYS) and "revenue" not in rows
    ccy = rows.get("currency") or []
    last_ccy = next((c for c in reversed(ccy) if c), "RUB")
    out = {"status": "ok", "ticker": ticker, "bank": bank, "url": IFRS_BASE % ticker, "currency": last_ccy, "years": [], "ltm": None,
           "as_of": None, "fetched": time.time()}
    if last_ccy.upper() not in ("RUB", "RUR"):
        out.update(status="notrub", note="Отчётность группы в валюте %s — сравнить с рублёвыми показателями нельзя." % last_ccy)
        return out
    dates = rows.get("date") or []
    prev_y = None
    for i, lab in enumerate(labels):
        if lab == "LTM":
            p = _ifrs_period(rows, i, bank, "LTM")
            if any(p.get(k) is not None for k in ("rev", "ebitda", "net")):
                out["ltm"] = p
                out["as_of"] = dates[i] if i < len(dates) and dates[i] else None
            continue
        y = int(lab)
        p = _ifrs_period(rows, i, bank, y)
        if not any(p.get(k) is not None for k in ("rev", "ebitda", "net", "assets")):
            continue
        out["years"].append(p)
    for k, p in enumerate(out["years"]):
        pv = out["years"][k - 1] if k else None
        p["growth"] = None
        if pv and pv["y"] == p["y"] - 1 and p.get("rev") is not None and pv.get("rev") and pv["rev"] > 0:
            p["growth"] = p["rev"] / pv["rev"] - 1
    if out["years"] and not out["as_of"]:
        i = labels.index(str(out["years"][-1]["y"]))
        out["as_of"] = dates[i] if i < len(dates) and dates[i] else None
    if not out["years"]:
        out.update(status="nodata", note="На smart-lab нет данных МСФО по этому тикеру.")
    return out


def _ifrs_http(url):
    with _ifrs_lock:                                   # не чаще одного запроса в секунду на всё приложение
        wait = 1.0 - (time.time() - _ifrs_last[0])
        if wait > 0:
            time.sleep(wait)
        _ifrs_last[0] = time.time()
    return ext_open(url, headers=IFRS_UA, timeout=20)[1].decode("utf-8", "replace")


_ifrs_fetch_lock = threading.Lock()


def ifrs_fin(ticker):
    """Тикер -> {status ok|nodata|notrub|parse|err, ticker, years, ltm, bank, url, as_of, ...}; кэш 7 дней (нет данных — сутки). Не бросает исключений."""
    ticker = (ticker or "").strip().upper()
    if not re.fullmatch(r"[A-Z0-9]{1,12}", ticker):
        return {"status": "nodata", "ticker": ticker, "years": [], "ltm": None, "bank": False, "url": None}
    key = "ifrs_fin_v1_" + ticker
    with _ifrs_fetch_lock:
        hit = store().get(key)
        if hit:
            age = time.time() - (hit.get("fetched") or 0)
            if age < (IFRS_TTL if hit.get("status") == "ok" else IFRS_ERR_TTL if hit.get("status") == "err" else IFRS_NF_TTL):
                return hit
        try:
            html = _ifrs_http(IFRS_BASE % ticker)
            parsed = ifrs_parse(html)
            if parsed is None:
                res = {"status": "parse", "ticker": ticker, "years": [], "ltm": None, "bank": False, "url": IFRS_BASE % ticker, "fetched": time.time(),
                       "note": "Страница smart-lab в неожиданном формате."}
            else:
                res = ifrs_build(parsed, ticker)
        except urllib.error.HTTPError as e:
            st = "nodata" if e.code == 404 else "err"
            res = {"status": st, "ticker": ticker, "years": [], "ltm": None, "bank": False, "url": IFRS_BASE % ticker, "fetched": time.time(),
                   "note": "На smart-lab нет страницы МСФО." if e.code == 404 else "smart-lab временно недоступен (HTTP %s)." % e.code}
        except Exception as e:  # noqa: BLE001
            res = {"status": "err", "ticker": ticker, "years": [], "ltm": None, "bank": False, "url": IFRS_BASE % ticker, "fetched": time.time(),
                   "note": "smart-lab недоступен: %s" % str(e)[:80]}
        try:
            store().put(key, res)
        except Exception:  # noqa: BLE001
            pass
        return res


# ── сопоставление эмитента с тикером ──

def _ifrs_emitter_shares(eid):
    """Список бумаг эмитента на Мосбирже, у которых есть акции: [{secid, type, traded}] (кэш 30 дней)."""
    key = "ifrs_emsec_v1_%s" % eid
    hit = store().get(key, ttl=IFRS_MAP_TTL)
    if hit is not None:
        return hit
    j = _iss_json("https://iss.moex.com/iss/emitters/%s/securities.json?iss.meta=off" % eid, 20)
    cols = j["securities"]["columns"]
    out = []
    for r in j["securities"]["data"]:
        d = dict(zip(cols, r))
        if d.get("TYPE") in ("common_share", "preferred_share") and d.get("SECID"):
            out.append({"secid": d["SECID"], "type": d["TYPE"], "traded": bool(d.get("IS_TRADED")), "board": d.get("PRIMARY_BOARDID")})
    store().put(key, out)
    return out


def ifrs_ticker_for(isin, em=None):
    """ISIN облигации -> {ticker, group, kind: 'own'|'group', how} или None, если листингового родителя не нашли."""
    try:
        em = em or issuer_of(isin)
        if not em:
            return None
        eid = em.get("emitter_id")
        if eid:
            sh = [s for s in _ifrs_emitter_shares(eid) if s["traded"]]
            sh.sort(key=lambda s: (s["type"] != "common_share", s["board"] != "TQBR"))
            if sh:
                t = sh[0]["secid"]
                return {"ticker": t, "group": em.get("short") or em.get("title"), "kind": "own",
                        "how": "эмитент — сама компания (акции %s на Мосбирже), показана отчётность группы по МСФО" % t}
        hit = IFRS_BY_INN.get(str(em.get("inn") or ""))
        if not hit:
            title = em.get("title") or ""
            for rx, t, g in IFRS_BY_NAME:
                if re.search(rx, title, re.I):
                    hit = (t, g)
                    break
        if hit:
            return {"ticker": hit[0], "group": hit[1], "kind": "group",
                    "how": "эмитент входит в группу «%s» (акции %s), показана консолидированная отчётность группы" % (hit[1], hit[0])}
    except Exception:  # noqa: BLE001
        return None
    return None


# ── скоринг ──

IFRS_FIN_RE = re.compile(r"лизинг|факторинг|микрофин|МФК|МКК|коллектор|ломбард", re.I)


def iss_score_ifrs(fin, is_fin=False):
    """Скоринг по МСФО (ifrs_fin). Форма результата как у iss_score_fin: {ok, score, key, label, year, parts, penalties, note, basis}.
    is_fin — лизинг, МФО и прочие небанковские финансовые компании: долг для них — «сырьё» бизнеса, поэтому вместо
    чистого долга/EBITDA, покрытия, маржи и FCF (отрицательный при росте портфеля — норма) смотрим
    долг/капитал (≥ 8 — 0, ≤ 3 — полный, 25 б.), капитал/активы (5 % — 0, 15 % — полный, 20 б.), ROE (0 — 0, ≥ 15 % — полный, 20 б.)."""
    if not fin or fin.get("status") != "ok" or not fin.get("years"):
        return {"ok": False, "reason": (fin or {}).get("note") or "Нет отчётности МСФО."}
    yrs = fin["years"]
    ltm = fin.get("ltm")
    c = ltm or yrs[-1]
    last = yrs[-1]
    prev = yrs[-2] if len(yrs) > 1 and yrs[-2]["y"] == last["y"] - 1 else None
    bank = bool(fin.get("bank"))
    parts = []

    def add(pid, name, w, t, value, text):
        if t is not None:
            parts.append({"id": pid, "name": name, "max": w, "pts": round(w * t, 1), "grade": _iss_grade(t), "value": value, "text": text})
    growth = last.get("growth")
    if bank:
        if c.get("eq_ratio") is not None:
            add("eq", "Капитал / активы", 20, _iss_t(c["eq_ratio"], 0.06, 0.12), c["eq_ratio"], "капитал — %s %% активов" % _iss_n(c["eq_ratio"] * 100, 1))
        roe = c.get("roe") if (c.get("equity") is None or c["equity"] > 0) else None
        if roe is None and c.get("net") is not None and c.get("equity") and c["equity"] > 0:
            roe = c["net"] / c["equity"]
        if roe is not None:
            add("roe", "Рентабельность капитала (ROE)", 20, _iss_t(roe, 0.0, 0.15), roe, "ROE %s %%" % _iss_n(roe * 100, 1))
        if c.get("cost_risk") is not None:
            add("crisk", "Стоимость риска", 15, _iss_t(c["cost_risk"], 0.03, 0.01), c["cost_risk"], "резервы съедают %s %% кредитов в год" % _iss_n(c["cost_risk"] * 100, 1))
        if c.get("npl") is not None:
            add("npl", "Неработающие кредиты", 15, _iss_t(c["npl"], 0.10, 0.04), c["npl"], "%s %% кредитов с просрочкой" % _iss_n(c["npl"] * 100, 1))
        if c.get("car") is not None:
            add("car", "Достаточность капитала", 15, _iss_t(c["car"], 0.105, 0.14), c["car"], "общая достаточность %s %%" % _iss_n(c["car"] * 100, 1))
        if growth is not None:
            add("growth", "Динамика доходов", 10, _iss_t(growth, -0.15, 0.05), growth, "чистые операционные доходы %s на %s %%" % ("выросли" if growth >= 0 else "упали", _iss_n(abs(growth) * 100, 0)))
    elif is_fin:
        debt, eq = c.get("debt"), c.get("equity")
        if debt is None and c.get("net_debt") is not None and c.get("cash") is not None:
            debt = c["net_debt"] + c["cash"]
        if debt is None:
            debt = c.get("net_debt")
        if eq is not None and eq <= 0:
            add("lev", "Долг / капитал", 25, 0.0, None, "капитал отрицательный")
        elif debt is not None and eq:
            de = debt / eq
            add("lev", "Долг / капитал", 25, _iss_t(de, 8, 3), de, "долг в %s раза больше капитала" % _iss_n(de, 1))
        if c.get("eq_ratio") is not None:
            add("eq", "Доля капитала", 20, _iss_t(c["eq_ratio"], 0.05, 0.15), c["eq_ratio"], "капитал — %s %% активов" % _iss_n(c["eq_ratio"] * 100, 0))
        roe = c.get("roe") if (eq is None or eq > 0) else None   # при отрицательном капитале ROE бессмысленна
        if roe is None and c.get("net") is not None and eq and eq > 0:
            roe = c["net"] / eq
        if roe is not None:
            add("roe", "Рентабельность капитала (ROE)", 20, _iss_t(roe, 0.0, 0.15), roe, "ROE %s %%" % _iss_n(roe * 100, 1))
        if growth is not None:
            add("growth", "Динамика выручки", 15, _iss_t(growth, -0.15, 0.05), growth, "выручка %s на %s %%" % ("выросла" if growth >= 0 else "упала", _iss_n(abs(growth) * 100, 0)))
    else:
        e, it, nd = c.get("ebitda"), c.get("interest"), c.get("net_debt")
        if it is not None and it > 0:
            if e is not None and e > 0:
                add("cover", "Покрытие процентов", 25, _iss_t(c["cover"], 2.0, 6.0), c["cover"], "EBITDA покрывает проценты в %s раза" % _iss_n(c["cover"], 1))
            elif e is not None:
                add("cover", "Покрытие процентов", 25, 0.0, None, "EBITDA не положительна, проценты платятся из других источников")
        elif c.get("debt") is not None and c.get("assets") and c["debt"] <= 0.02 * c["assets"]:
            add("cover", "Покрытие процентов", 25, 1.0, None, "заёмных средств практически нет")
        if nd is not None:
            if nd <= 0:
                add("lev", "Чистый долг / EBITDA", 25, 1.0, None, "денег больше, чем долга")
            elif e is None or e <= 0:
                add("lev", "Чистый долг / EBITDA", 25, 0.0, None, "есть чистый долг, а EBITDA не положительна")
            else:
                add("lev", "Чистый долг / EBITDA", 25, _iss_t(c["nd_ebitda"], 4.5, 1.5), c["nd_ebitda"], "чистый долг = %s годовой EBITDA" % _iss_n(c["nd_ebitda"], 1))
        if c.get("eq_ratio") is not None:
            add("eq", "Доля капитала", 15, _iss_t(c["eq_ratio"], 0.10, 0.40), c["eq_ratio"], "капитал — %s %% активов" % _iss_n(c["eq_ratio"] * 100, 0))
        if c.get("margin_ebitda") is not None:
            add("margin", "Рентабельность по EBITDA", 10, _iss_t(c["margin_ebitda"], 0.05, 0.25), c["margin_ebitda"], "EBITDA — %s %% выручки" % _iss_n(c["margin_ebitda"] * 100, 1))
        f = c.get("fcf")
        if f is not None:
            if f >= 0:
                add("fcf", "Свободный денежный поток", 10, 1.0, f, "положительный: операционный поток покрывает инвестиции")
            elif e is not None and e > 0:
                add("fcf", "Свободный денежный поток", 10, _iss_t(f / e, -0.5, 0.0), f, "отрицательный: %s %% от EBITDA" % _iss_n(abs(f) / e * 100, 0))
            else:
                add("fcf", "Свободный денежный поток", 10, 0.0, f, "отрицательный при слабой EBITDA")
        if growth is not None:
            add("growth", "Динамика выручки", 15, _iss_t(growth, -0.15, 0.05), growth, "выручка %s на %s %%" % ("выросла" if growth >= 0 else "упала", _iss_n(abs(growth) * 100, 0)))
    mx = sum(p["max"] for p in parts)
    if mx < 40:
        return {"ok": False, "reason": "Слишком мало показателей МСФО для оценки%s." % (" (банк: не хватает данных)" if bank else "")}
    base = sum(p["pts"] for p in parts) / mx * 100
    pen = []
    net = last.get("net")
    if net is not None and net < 0:
        pen.append({"name": "Убыток по итогам года", "pts": -8})
        if prev and prev.get("net") is not None and prev["net"] < 0:
            pen.append({"name": "Убыток второй год подряд", "pts": -7})
    if c.get("equity") is not None and c["equity"] < 0:
        pen.append({"name": "Отрицательный капитал", "pts": -15})
    if last["y"] < date.today().year - 2:
        pen.append({"name": "Отчётность старше двух лет (%d)" % last["y"], "pts": -10})
    sc = max(0, min(100, int(round(base + sum(p["pts"] for p in pen)))))
    k, t = _iss_label(sc)
    per = ("LTM на %s" % fin["as_of"]) if ltm and fin.get("as_of") else ("LTM" if ltm else "%d г." % last["y"])
    return {"ok": True, "score": sc, "key": k, "label": t, "year": last["y"], "period": per, "base": round(base, 1), "parts": parts, "penalties": pen,
            "n_years": len(yrs), "fin_mode": bool(is_fin and not bank), "holding": False, "bank": bank, "basis": "ifrs",
            "note": "Консолидированная отчётность группы (МСФО) по данным агрегатора smart-lab; может отличаться от официальной."}


def ifrs_bundle(isin, em=None):
    """Всё для интеграции: {ticker, how, group, kind, fin, score, url} или None, если МСФО-тикера нет."""
    mp = ifrs_ticker_for(isin, em)
    if not mp:
        return None
    fin = ifrs_fin(mp["ticker"])
    # для групп «финансовой» считаем только лизинг/МФО/факторинг: в названиях холдингов («АФК Система») слово «финансовая» не про бизнес
    nm = (em or {}).get("title") or mp.get("group") or ""
    sc = iss_score_ifrs(fin, bool(IFRS_FIN_RE.search(nm)))
    return {"ticker": mp["ticker"], "how": mp["how"], "group": mp["group"], "kind": mp["kind"], "fin": fin, "score": sc, "url": fin.get("url") or IFRS_BASE % mp["ticker"]}
# ═══════════════════════════════ Данные на компьютере (раздел «Настройки») ═══════════════════════════════
# Размер и состав папки данных, открытие папки, очистка кэша и полное удаление данных.
# Все пути строятся только от APP_DIR; символические ссылки никогда не разворачиваются (удаляется сама ссылка).

LD_DB_NAMES = ("data.db", "data.db-wal", "data.db-shm")


def _ld_size(path):
    """Размер файла или папки в байтах без перехода по символическим ссылкам."""
    try:
        st = os.lstat(path)
    except OSError:
        return 0
    if not os.path.isdir(path) or os.path.islink(path):
        return st.st_size
    total = 0
    for root, dirs, files in os.walk(path, followlinks=False):
        for n in files + [d for d in dirs if os.path.islink(os.path.join(root, d))]:
            try:
                total += os.lstat(os.path.join(root, n)).st_size
            except OSError:
                pass
    return total


def local_data_info(app_dir=None):
    """Состав папки данных: общий размер и разбивка по частям."""
    base = app_dir or APP_DIR
    names = set()
    try:
        names = set(os.listdir(base))
    except OSError:
        pass
    parts = [("db", "data.db", "База операций и кэш", [n for n in names if n == "data.db" or n.startswith("data.db-")]),
             ("cache", "cache/", "Кэш", ["cache"]),
             ("logos", "logos/", "Логотипы", ["logos"]),
             ("app", "app/", "Скачанная программа", ["app"]),
             ("window", "window/", "Данные окна приложения", ["window", "window.json"]),
             ("config", "config.json", "Настройки, токен и ключ", ["config.json"])]
    used, rows = set(), []
    for key, name, title, files in parts:
        used.update(files)
        rows.append({"key": key, "name": name, "title": title,
                     "bytes": sum(_ld_size(os.path.join(base, f)) for f in files if f in names)})
    rest = sorted(names - used)
    if rest:
        rows.append({"key": "other", "name": "прочее", "title": "Прочие файлы",
                     "bytes": sum(_ld_size(os.path.join(base, f)) for f in rest)})
    return {"dir": base, "total": sum(r["bytes"] for r in rows), "parts": rows, "windows": platform.system() == "Windows"}


def _ld_remove(path):
    """Удаляет файл, ссылку или папку целиком; ссылки не разворачивает."""
    try:
        if os.path.islink(path) or not os.path.isdir(path):
            os.unlink(path)
        else:
            shutil.rmtree(path)
    except FileNotFoundError:
        pass
    except OSError:
        pass


def _ld_empty_dir(path):
    """Очищает содержимое папки (саму папку оставляет)."""
    try:
        if os.path.islink(path) or not os.path.isdir(path):
            return
        for n in os.listdir(path):
            _ld_remove(os.path.join(path, n))
    except OSError:
        pass


def _ld_protected_keys():
    """Ключи таблицы kv с вашими данными или накопленной историей: очистка кэша их не трогает."""
    names = ("WATCH_KEY", "NOTES_KEY", "TG_SENT_KEY", "TG_STATE_KEY", "TAX_SETTINGS_KEY", "SIG_HIST_KEY", "RT_LOG_KEY",
             "MKT_HIST_KEY", "MKT_HIST2_KEY", "MON_SNAP_KEY")
    keys = {"backup_status"}
    for n in names:
        v = globals().get(n)
        if isinstance(v, str):
            keys.add(v)
    return keys


def clear_local_cache(app_dir=None):
    """Удаляет кэш (cache/, logos/, кэш-записи и свечи в data.db). Операции, настройки, список наблюдения и заметки остаются."""
    base = app_dir or APP_DIR
    before = local_data_info(base)["total"]
    st = store()
    keys = sorted(_ld_protected_keys())
    with st.wlock:
        c = st.conn()
        c.execute("DELETE FROM kv WHERE k NOT LIKE 'imports%%' AND k NOT IN (%s)" % ",".join("?" * len(keys)), keys)
        c.execute("DELETE FROM candles")
        c.commit()
        try:
            c.execute("PRAGMA wal_checkpoint(TRUNCATE)")
            c.execute("VACUUM")
        except sqlite3.Error:
            pass
    for d in ("cache", "logos"):
        _ld_empty_dir(os.path.join(base, d))
    mem_clear()
    after = local_data_info(base)["total"]
    return {"ok": True, "freed": max(0, before - after), "info": local_data_info(base)}


def delete_all_local_data(app_dir=None):
    """Удаляет настройки (токен, ключ), базу, кэш и логотипы. Папка app/ остаётся, чтобы программа продолжала работать."""
    global STORE
    base = app_dir or APP_DIR
    if STORE is not None and os.path.abspath(base) == os.path.abspath(APP_DIR):
        try:
            with STORE.wlock:
                c = STORE.conn()
                for t in ("kv", "ops", "candles", "snaps"):
                    c.execute("DELETE FROM " + t)
                c.commit()
                c.execute("PRAGMA wal_checkpoint(TRUNCATE)")
                c.close()
                STORE.local.c = None
        except sqlite3.Error:
            pass
        STORE = None
    for n in LD_DB_NAMES + ("config.json", "window.json", "data.db.before-restore"):
        _ld_remove(os.path.join(base, n))
    for n in ("cache", "logos", "window"):
        _ld_remove(os.path.join(base, n))
    try:
        for n in os.listdir(base):
            if n.startswith("backup.") and n.endswith(".tmp"):
                _ld_remove(os.path.join(base, n))
    except OSError:
        pass
    mem_clear()
    ds_reset()
    return {"ok": True, "info": local_data_info(base)}


def open_data_dir():
    """Открывает папку данных в Finder / Проводнике / файловом менеджере. Путь не принимается извне."""
    os.makedirs(APP_DIR, exist_ok=True)
    sysname = platform.system()
    if sysname == "Windows":
        os.startfile(APP_DIR)           # noqa: S606  (только на Windows)
    elif sysname == "Darwin":
        subprocess.Popen(["open", APP_DIR])
    else:
        subprocess.Popen(["xdg-open", APP_DIR])


def ld_info_get(cfg, acc, q, f):
    return local_data_info()


def ld_open_post(cfg, body):
    try:
        open_data_dir()
    except (OSError, AttributeError) as e:
        raise ApiError("Не удалось открыть папку: %s. Путь: %s" % (e, APP_DIR), 500)
    return {"ok": True}


def ld_clear_post(cfg, body):
    return clear_local_cache()


def ld_wipe_post(cfg, body):
    if body.get("confirm") != "delete-all":
        raise ApiError("Нужно подтверждение удаления.", 400)
    return delete_all_local_data()


API_GET["/api/localdata"] = ld_info_get
API_POST["/api/localdata/open"] = ld_open_post
API_POST["/api/localdata/clear"] = ld_clear_post
API_POST["/api/localdata/wipe"] = ld_wipe_post
# ═══════════════════════════════ «Сегодня»: дневная сводка на «Обзоре» ═══════════════════════════════
# Выплаты на 7 дней, ближайшие оферты, рейтинговые действия за неделю и число тревог мониторинга.
# Чистые функции (td_*) не ходят в сеть; сеть и кэши трогает только td_build/today_get. Кэш 10 минут.

TD_PAY_DAYS, TD_OFFER_DAYS, TD_RATING_DAYS, TD_TTL = 7, 30, 7, 600
TD_PAY_KINDS = ("coupon", "dividend", "amortization")


def td_add_days(d, n):
    return (datetime.strptime(d, "%Y-%m-%d") + timedelta(days=n)).strftime("%Y-%m-%d")


def td_payments(pays, today, days=TD_PAY_DAYS):
    """Купоны, дивиденды и амортизации в окне [today, today+days]: сумма, число, разбивка по видам и 5 ближайших."""
    end = td_add_days(today, days)
    sel = sorted((p for p in pays or [] if p.get("kind") in TD_PAY_KINDS and today <= (p.get("date") or "") <= end and p.get("amount")),
                 key=lambda p: (p["date"], -(p.get("amount") or 0)))
    by = {}
    for p in sel:
        by[p["kind"]] = by.get(p["kind"], 0) + p["amount"]
    return {"count": len(sel), "sum": sum(p["amount"] for p in sel), "days": days, "by_kind": by,
            "next_date": sel[0]["date"] if sel else None,
            "items": [{"date": p["date"], "kind": p["kind"], "name": p.get("name"), "amount": p["amount"]} for p in sel[:5]]}


def td_offer_status(o, today):
    """Статус оферты: open (идёт приём заявок) | upcoming (приём ещё не начался) | closed | unknown (период не опубликован)."""
    ps, pe = o.get("period_start"), o.get("period_end")
    if ps and pe:
        return "open" if ps <= today <= pe else ("upcoming" if today < ps else "closed")
    return "unknown"


def td_offers(pairs, today, days=TD_OFFER_DAYS):
    """pairs: [(строка облигации, список оферт offer_kinds)]. Оферты в ближайшие days дней, без отменённых, по возрастанию даты."""
    end = td_add_days(today, days)
    out = []
    for r, offs in pairs or []:
        for o in offs or []:
            if o.get("status") == "cancelled" or not (today <= (o.get("date") or "") <= end):
                continue
            st = td_offer_status(o, today) if o["kind"] == "put" else "unknown"
            if st == "closed":
                continue
            out.append({"isin": r.get("isin"), "name": r.get("name"), "kind": o["kind"], "date": o["date"],
                        "days": (datetime.strptime(o["date"], "%Y-%m-%d") - datetime.strptime(today, "%Y-%m-%d")).days,
                        "status": st, "period_start": o.get("period_start"), "period_end": o.get("period_end")})
    out.sort(key=lambda x: (x["date"], {"put": 0, "call": 1}.get(x["kind"], 2), x["name"] or ""))
    return {"count": len(out), "days": days, "put": sum(1 for x in out if x["kind"] == "put"),
            "call": sum(1 for x in out if x["kind"] == "call"), "items": out[:5]}


def td_ratings(events, rows_keys, today, days=TD_RATING_DAYS):
    """Рейтинговые действия за days дней по эмитентам портфеля (та же логика, что у тревог монитора)."""
    al = _mon_rating_alerts(rows_keys, events or [], td_add_days(today, -days))
    return {"count": len(al), "days": days, "negative": sum(1 for a in al if a["severity"] in ("high", "medium")),
            "items": [{"date": a["date"], "name": a["name"], "message": a["message"], "severity": a["severity"]} for a in al[:5]]}


def td_digest(pays, pairs, events, rows_keys, today, alerts=None):
    """Собирает сводку; пустые разделы выбрасываются, empty=True — показывать карточку нечего."""
    d = {"today": today, "payments": td_payments(pays, today), "offers": td_offers(pairs, today),
         "ratings": td_ratings(events, rows_keys, today)}
    if alerts is not None:
        d["alerts"] = {"count": sum(1 for a in alerts if a.get("severity") in ("high", "medium")),
                       "high": sum(1 for a in alerts if a.get("severity") == "high")}
    for k in ("payments", "offers", "ratings", "alerts"):
        if k in d and not d[k]["count"]:
            del d[k]
    d["empty"] = not any(k in d for k in ("payments", "offers", "ratings", "alerts"))
    return d


def td_empty():
    return {"today": date.today().isoformat(), "empty": True}


def _td_warm_monitor(cfg, acc):
    try:
        build_monitor(cfg, acc)
    except Exception:  # noqa: BLE001
        pass


def td_build(cfg, acc):
    today = date.today().isoformat()
    rep = build_bonds(cfg, acc)
    rows = [r for r in rep.get("rows") or [] if r.get("isin") and r.get("qty")]

    def one(r):
        try:
            return r, offers_of_isin(r["isin"], r.get("call"), today)
        except Exception:  # noqa: BLE001
            return r, []
    pairs = pool_map(one, rows, workers=8)
    events = (store().get(RT_LOG_KEY) or {}).get("events") or []
    rows_keys = [(r, _mon_issuer_keys(r)) for r in rows]
    alerts = None
    try:                                  # мониторинг тяжёлый: берём только готовый результат, а прогрев запускаем в фоне
        th = mon_thresholds(cfg)
        mon = mem_get(("monitor", token_key(cfg), acc, tuple(sorted(th.items()))), 900)
        if mon is not None:
            alerts = mon.get("alerts") or []
        else:
            threading.Thread(target=_td_warm_monitor, args=(cfg, acc), daemon=True).start()
    except Exception:  # noqa: BLE001
        alerts = None
    return td_digest(rep.get("payments") or [], pairs, events, rows_keys, today, alerts)


def today_get(cfg, acc, q, force):
    if not cfg.get("token") and not imports_list():
        return td_empty()
    key = ("today", token_key(cfg), acc)
    if not force:
        hit = mem_get(key, TD_TTL)
        if hit:
            return hit
    try:
        res = td_build(cfg, acc)
    except Exception:  # noqa: BLE001
        return td_empty()
    return mem_put(key, res)


API_GET["/api/today"] = today_get
# ═══════════════════════════════ HTTP-сервер ═══════════════════════════════

_ping = [0.0]


class Handler(BaseHTTPRequestHandler):
    server_version = "TInvestAnalytics/3.0"

    def log_message(self, *a):
        pass

    def send(self, code, body, ctype="application/json; charset=utf-8", headers=None):
        if isinstance(body, (dict, list)):
            body = json.dumps(body, ensure_ascii=False, separators=(",", ":"), default=str).encode()
        elif isinstance(body, str):
            body = body.encode()
        gz = len(body) > 2048 and ctype.startswith(("application/json", "text/")) and \
            "gzip" in (self.headers.get("Accept-Encoding") or "")
        if gz:
            body = gzip.compress(body, 5)
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "max-age=604800" if ctype == "image/png" else "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Content-Security-Policy",
                         "default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data:")
        if gz:
            self.send_header("Content-Encoding", "gzip")
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        try:
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def ok_host(self):
        port = self.server.server_address[1]
        return self.headers.get("Host", "") in ("127.0.0.1:%d" % port, "localhost:%d" % port)

    def guard(self, fn):
        try:
            fn()
        except ApiError as e:
            self.send(e.status if 400 <= e.status < 600 else 502, {"error": str(e)})
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception as e:  # noqa: BLE001
            import traceback
            traceback.print_exc()
            self.send(500, {"error": "%s: %s" % (type(e).__name__, e)})

    def _reply(self, res):
        if isinstance(res, tuple):
            code, body = res[0], res[1]
            ctype = res[2] if len(res) > 2 and res[2] else "application/json; charset=utf-8"
            return self.send(code, body, ctype, res[3] if len(res) > 3 else None)
        return self.send(200, res)

    def do_GET(self):
        if not self.ok_host():
            return self.send(403, {"error": "forbidden"})
        u = urlparse(self.path)
        q = {k: v[0] for k, v in parse_qs(u.query).items()}

        def run():
            if u.path == "/":
                return self.send(200, PAGE, "text/html; charset=utf-8")
            if u.path.startswith("/logo/"):
                data = logo_bytes(unquote(u.path[6:]))
                return self.send(200, data, "image/png") if data else self.send(404, {"error": "no logo"})
            if u.path == "/api/ping":
                _ping[0] = time.time()
                return self.send(200, {"ok": True})
            cfg = load_config()
            f = q.get("force") == "1"
            acc = q.get("account", "all") or "all"
            if u.path == "/api/config":
                pub = {k: v for k, v in cfg.items() if k not in SECRET_KEYS}
                pub["secret_set"] = {k: bool(cfg.get(k)) for k in SECRET_KEYS if k != "token"}
                pub.update(token_set=bool(cfg["token"]), token_hint=("…" + cfg["token"][-4:]) if cfg["token"] else "",
                           imports=imports_list(), data_dir=APP_DIR, version=APP_VERSION)
                return self.send(200, pub)
            if u.path == "/api/summary":
                return self.send(200, build_summary(cfg, acc, q.get("period", "all"), f))
            if u.path == "/api/bonds":
                return self.send(200, build_bonds(cfg, acc, f))
            if u.path == "/api/history":
                return self.send(200, build_history_for(cfg, acc, f))
            if u.path == "/api/operations.csv":
                data = build_summary(cfg, acc, q.get("period", "all"))
                return self.send(200, operations_csv(data), "text/csv; charset=utf-8",
                                 {"Content-Disposition": 'attachment; filename="operations.csv"'})
            if u.path == "/api/screener":
                return self.send(200, screener_payload())
            if u.path == "/api/bond":
                return self.send(200, bond_card(q.get("isin", "")))
            if u.path == "/api/primary":
                return self.send(200, primary_payload())
            if u.path == "/api/ratings":
                return self.send(200, ratings_status())
            if u.path == "/api/keyrate":
                return self.send(200, keyrate_brief() or {"source": "none", "name": "", "yearly": []})
            if u.path == "/api/risk":
                return self.send(200, build_risk(cfg, acc, q))
            if u.path == "/api/signals":
                return self.send(200, signals_payload(cfg, acc, q))
            if u.path == "/api/monitor":
                return self.send(200, build_monitor(cfg, acc))
            if u.path == "/api/bench":
                return self.send(200, bench_payload(cfg, acc, q))
            if u.path == "/api/calc":
                return self.send(200, calc_params(cfg, acc))
            if u.path == "/api/offers":
                return self.send(200, offers_payload(cfg, acc))
            if u.path == "/api/ladder":
                return self.send(200, ladder_payload(cfg, q))
            if u.path == "/api/rates":
                return self.send(200, rates_payload(q.get("days", "365")))
            if u.path == "/api/backup":
                return self.send(200, make_backup(), "application/zip",
                                 {"Content-Disposition": 'attachment; filename="tinvest_backup_%s.zip"' % date.today().isoformat()})
            if u.path == "/api/import/template.csv":
                return self.send(200, TEMPLATE_CSV.encode("utf-8-sig"), "text/csv; charset=utf-8",
                                 {"Content-Disposition": 'attachment; filename="import_template.csv"'})
            fn = API_GET.get(u.path)
            if fn:
                return self._reply(fn(cfg, acc, q, f))
            self.send(404, {"error": "not found"})
        self.guard(run)

    def do_POST(self):
        if not self.ok_host() or "application/json" not in (self.headers.get("Content-Type") or ""):
            return self.send(403, {"error": "forbidden"})
        path = urlparse(self.path).path

        def run():
            n = int(self.headers.get("Content-Length") or 0)
            if n > 80 * 1024 * 1024:
                raise ApiError("Файл слишком большой (больше 60 МБ).", 400)
            body = json.loads(self.rfile.read(n) or b"{}") if n else {}
            cfg = load_config()
            if path == "/api/config":
                if body.get("token"):
                    cfg["token"] = "".join(str(body["token"]).split())
                if body.get("clear_token"):
                    cfg["token"] = ""
                for k in ("sandbox", "verify_ssl"):
                    if k in body:
                        cfg[k] = bool(body[k])
                if "ca_file" in body:
                    cfg["ca_file"] = str(body["ca_file"]).strip()
                if body.get("theme") in ("auto", "dark", "light"):
                    cfg["theme"] = body["theme"]
                if isinstance(body.get("targets"), dict):
                    tg = {}
                    for k, v in body["targets"].items():
                        try:
                            x = float(v)
                        except (TypeError, ValueError):
                            continue
                        if 0 < x <= 100:
                            tg[str(k)[:24]] = round(x, 2)
                    cfg["targets"] = tg
                if body.get("keyrate_mode") in KR_MODES:
                    cfg["keyrate_mode"] = body["keyrate_mode"]
                if "notify_days" in body:
                    try:
                        cfg["notify_days"] = max(0, min(60, int(body["notify_days"])))
                    except (TypeError, ValueError):
                        pass
                for k, lo, hi in (("mon_drop5", 0.1, 50), ("mon_drop30", 0.1, 90), ("mon_spread30", 0.1, 50),
                                  ("mon_sell_days", 0.5, 365), ("mon_offer_days", 1, 365)):
                    if k in body:
                        try:
                            cfg[k] = max(lo, min(hi, float(body[k])))
                        except (TypeError, ValueError):
                            pass
                for k in ("hosts_prod", "hosts_sandbox"):
                    if isinstance(body.get(k), list):
                        hosts = [str(h).strip() for h in body[k] if str(h).strip()]
                        if hosts:
                            cfg[k] = hosts
                if "data_server" in body:
                    u = str(body["data_server"]).strip().rstrip("/")
                    if u and u.lower() != "off" and not re.fullmatch(r"https?://[^/\s]+(/[^\s]*)?", u):
                        raise ApiError("Адрес сервера данных должен начинаться с http:// или https://", 400)
                    cfg["data_server"] = u
                if body.get("data_key"):
                    cfg["data_key"] = "".join(str(body["data_key"]).split())
                if body.get("clear_data_key"):
                    cfg["data_key"] = ""
                if cfg["ca_file"] and not os.path.isfile(cfg["ca_file"]):
                    raise ApiError("Файл сертификата не найден: " + cfg["ca_file"], 400)
                save_config(cfg)
                ds_reset()
                mem_clear()
                return self.send(200, {"ok": True})
            if path == "/api/ratings/refresh":
                return self.send(200, {"started": ratings_start(force=True), **ratings_status()})
            client = TInvest(cfg)
            if path == "/api/test":
                return self.send(200, {"ok": True, "accounts": len(client.accounts())})
            if path == "/api/cache/clear":
                store().wipe_cache()
                shutil.rmtree(LOGO_DIR, ignore_errors=True)
                mem_clear()
                return self.send(200, {"ok": True})
            if path == "/api/import/preview":
                raw = base64.b64decode(body.get("data") or "")
                return self.send(200, import_preview(body.get("filename") or "", raw))
            if path == "/api/import/parse":
                raw = base64.b64decode(body.get("data") or "")
                ops, skipped = import_ops(body.get("filename") or "", raw, int(body.get("table") or 0),
                                          int(body.get("header_row") or 0), body.get("mapping") or {})
                kinds = defaultdict(int)
                for o in ops:
                    kinds[classify(o["type"])] += 1
                sample = [[o["date"][:10], op_type(o), o.get("name") or "", op_qty(o), qf(o["payment"]), cur_of(o["payment"])]
                          for o in ops[:15]]
                return self.send(200, {"count": len(ops), "skipped": skipped, "kinds": kinds, "sample": sample,
                                       "from": ops[0]["date"][:10] if ops else None, "to": ops[-1]["date"][:10] if ops else None})
            if path == "/api/import/commit":
                raw = base64.b64decode(body.get("data") or "")
                ops, skipped = import_ops(body.get("filename") or "", raw, int(body.get("table") or 0),
                                          int(body.get("header_row") or 0), body.get("mapping") or {})
                if not ops:
                    raise ApiError("В файле не нашлось операций с выбранными колонками.", 400)
                ops, ids = finalize_import(client, ops)
                acc_id = body.get("target") if str(body.get("target") or "").startswith("imp-") else "imp-" + uuid.uuid4().hex[:10]
                lst = imports_list()
                ex = next((x for x in lst if x["id"] == acc_id), None)
                if ex is None:
                    ex = {"id": acc_id, "name": (body.get("name") or "").strip() or "Импорт " + date.today().strftime("%d.%m.%Y"),
                          "broker": (body.get("broker") or "").strip(), "created": utc_now_str(), "files": []}
                    lst.append(ex)
                ex["files"].append({"name": body.get("filename") or "", "count": len(ops), "at": utc_now_str()})
                store().ops_put(acc_id, ops)
                store().put("imports", lst)
                mem_clear()
                found = sum(1 for v in ids.values() if v.get("uid"))
                return self.send(200, {"ok": True, "id": acc_id, "count": len(ops), "skipped": skipped,
                                       "resolved": found, "idents": len(ids)})
            if path == "/api/import/delete":
                lst = [x for x in imports_list() if x["id"] != body.get("id")]
                store().put("imports", lst)
                store().ops_clear(body.get("id") or "")
                mem_clear()
                return self.send(200, {"ok": True})
            if path in ("/api/sandbox/open", "/api/sandbox/payin"):
                if not cfg["sandbox"]:
                    raise ApiError("Доступно только в режиме песочницы.", 400)
                mem_clear()
                if path.endswith("open"):
                    return self.send(200, client.call("SandboxService", "OpenSandboxAccount", {"name": "Analytics"}))
                amount = Decimal(str(body.get("amount") or 0))
                if amount <= 0:
                    raise ApiError("Сумма должна быть больше нуля.", 400)
                acc = body.get("accountId")
                if not acc or acc == "all" or str(acc).startswith("imp-"):
                    raise ApiError("Выберите счёт песочницы в списке слева.", 400)
                return self.send(200, client.call("SandboxService", "SandboxPayIn", {"accountId": acc, "amount": to_money(amount)}))
            fn = API_POST.get(path)
            if fn:
                return self._reply(fn(cfg, body))
            self.send(404, {"error": "not found"})
        self.guard(run)


# ═══════════════════════════════ окно приложения ═══════════════════════════════

def find_app_browser():
    sysname = platform.system()
    cands = []
    if sysname == "Windows":
        for r in filter(None, [os.environ.get(k) for k in ("PROGRAMFILES", "PROGRAMFILES(X86)", "LOCALAPPDATA")]):
            cands += [os.path.join(r, "Google", "Chrome", "Application", "chrome.exe"),
                      os.path.join(r, "Microsoft", "Edge", "Application", "msedge.exe"),
                      os.path.join(r, "Yandex", "YandexBrowser", "Application", "browser.exe"),
                      os.path.join(r, "BraveSoftware", "Brave-Browser", "Application", "brave.exe")]
    elif sysname == "Darwin":
        for app, exe in (("Google Chrome", "Google Chrome"), ("Microsoft Edge", "Microsoft Edge"),
                         ("Yandex", "Yandex"), ("Brave Browser", "Brave Browser"), ("Chromium", "Chromium")):
            for base in ("/Applications", os.path.expanduser("~/Applications")):
                cands.append(os.path.join(base, app + ".app", "Contents", "MacOS", exe))
    else:
        for n in ("google-chrome", "google-chrome-stable", "chromium", "chromium-browser", "microsoft-edge",
                  "yandex-browser", "brave-browser"):
            p = shutil.which(n)
            if p:
                cands.append(p)
    return next((c for c in cands if c and os.path.isfile(c)), None)


def open_window(url):
    exe = find_app_browser()
    if exe:
        try:
            return subprocess.Popen([exe, "--app=" + url, "--user-data-dir=" + os.path.join(APP_DIR, "window"),
                                     "--window-size=1480,940", "--no-first-run", "--no-default-browser-check",
                                     "--disable-features=Translate"],
                                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except OSError:
            pass
    webbrowser.open(url)
    return None


class LocalHTTPServer(ThreadingHTTPServer):
    """Сервер только на 127.0.0.1. Стандартный server_bind вызывает socket.getfqdn(): обратный DNS-запрос
    по адресу машины на macOS идёт через mDNS и вызывает запрос «разрешить находить устройства в локальной сети»,
    а до ответа на него запуск зависает. Имя хоста серверу не нужно."""
    daemon_threads = True

    def server_bind(self):
        socketserver.TCPServer.server_bind(self)
        self.server_name, self.server_port = "127.0.0.1", self.server_address[1]


def main():
    cfg = load_config()
    port = int(os.environ.get("TINVEST_PORT") or cfg["port"])
    for i, a in enumerate(sys.argv):
        if a == "--port" and i + 1 < len(sys.argv):
            port = int(sys.argv[i + 1])
    store()
    try:
        srv = LocalHTTPServer(("127.0.0.1", port), Handler)
    except OSError:
        srv = LocalHTTPServer(("127.0.0.1", 0), Handler)
    srv.daemon_threads = True
    url = "http://127.0.0.1:%d/" % srv.server_address[1]
    print("%s → %s   (Ctrl+C — выход)\nДанные: %s" % (APP_NAME, url, APP_DIR))
    if "--no-window" not in sys.argv:
        proc = open_window(url)
        if proc:
            def watch():
                t0 = time.time()
                proc.wait()
                if time.time() - t0 > 8:
                    return srv.shutdown()
                while True:
                    time.sleep(30)
                    if _ping[0] and time.time() - _ping[0] > 200:
                        return srv.shutdown()
            threading.Thread(target=watch, daemon=True).start()
    try:
        try:
            ratings_start()
        except Exception:  # noqa: BLE001
            pass
        try:
            warmup_start()
        except Exception:  # noqa: BLE001
            pass
        for hook in STARTUP_HOOKS:
            try:
                hook()
            except Exception:  # noqa: BLE001
                pass
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        srv.server_close()
    # окно закрыто или Ctrl+C: фоновые расчёты (пулы потоков) прерываем сразу, иначе они падают с трассировкой
    # «cannot schedule new futures after interpreter shutdown». База SQLite транзакционная, данные не теряются.
    if not getattr(sys, "frozen", False):        # в собранном приложении выходом управляет лаунчер
        sys.stdout.flush()
        os._exit(0)


